-- ── pregnancy_daily_content → ru (294 sətir) ──
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Гормон эстроген способствует увеличению размера вашей яйцеклетки, ускоряет митотическое деление клеток, благодаря чему стенка матки утолщается как изнутри, так и снаружи, а оплодотворённая яйцеклетка может надёжно закрепиться в полости матки. Кроме того, создавая оптимальные условия для яйцеклетки, готовой к оплодотворению, он усиливает кровоснабжение клеток матки и увеличивает количество тканевой жидкости. Этот гормон также способствует удлинению влагалища и стимулирует клетки внутренней оболочки матки к выделению слизи, обеспечивающей необходимое скольжение.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, открыть вам один секрет? 🤫 Одна из тысяч клеток в вашем организме начала соревнование за право стать именно "МНОЙ"! Сейчас она растёт и с нетерпением ждёт дня, когда встретится со своей второй половиной, которая придёт от папы. До нашей великой встречи осталось около 1 недели. Я очень волнуюсь, а вы? Я так скучаю по вашим тёплым объятиям.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка сахарного песка'), body_changes_ru = COALESCE(body_changes_ru, 'К концу первой недели гормональные изменения в вашем организме приближаются к пику. Благодаря повышению уровня эстрогена внутренняя оболочка матки уже полностью восстановилась и продолжает утолщаться. В эти дни вы можете чувствовать себя более общительной, энергичной и уверенной в себе. Повышение либидо — это признак того, что ваш организм естественным образом готовится к репродуктивному периоду, то есть к дням с наиболее высокой вероятностью наступления беременности.;;;
Чтобы беременность протекала благополучно, ещё до её наступления необходимо пройти плановое медицинское обследование.;;;
Обследование перед беременностью особенно важно в старшем репродуктивном возрасте или при наличии любых хронических заболеваний. Во время него необходимо учитывать ваш семейный анамнез и семейный анамнез вашего супруга, чтобы выявить возможные наследственные заболевания. Гинекологический осмотр и ультразвуковое исследование, проведённые врачом для оценки состояния матки и яичников, важны для выявления миом, полипов и других патологий матки. Если врач сочтёт необходимым, следует провести процедуру взятия мазка с шейки матки, называемую "smear testi". Лабораторные анализы также позволяют оценить функции печени и почек, уровень сахара, а также проверить наличие гепатита, токсоплазмоза и других хронических заболеваний. При обследовании перед беременностью особенно важно учитывать применявшиеся ранее методы контрацепции. Длительный приём противозачаточных таблеток может на некоторое время снизить фертильность. Около 50% женщин могут забеременеть не ранее чем через 6 месяцев после приёма последней таблетки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Наградите себя за успешное завершение первой недели, но сделайте это с пользой для здоровья. Чтобы повысить уровень кислорода в организме, совершайте продолжительные прогулки на свежем воздухе: хорошее насыщение кислородом положительно влияет на обмен веществ в яйцеклетке. Добавьте в рацион разноцветные фрукты и ягоды, богатые антиоксидантами (например, чернику и малину). Эти вещества защищают яйцеклетку от окислительного стресса и создают условия для более благоприятного оплодотворения.') WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Расположенные по обеим сторонам матки фаллопиевы трубы — это парные длинные узкие каналы репродуктивной системы, по которым созревшие в яичниках яйцеклетки перемещаются к матке. Этот орган также называют яйцеводами или маточными трубами. Фаллопиевы трубы обеспечивают перемещение в матку яйцеклетки, созревшей из выбранного в этом месяце фолликула. Слизистая оболочка фаллопиевых труб длиной около 12 см вырабатывает секрет, который помогает сперматозоидам двигаться к яйцеклетке и сохранять жизнеспособность. Некоторые компоненты этого секрета крайне важны для использования кислорода сперматозоидами, а также способствуют питанию яйцеклетки и её развитию после оплодотворения.'), baby_message_ru = COALESCE(baby_message_ru, 'Здравствуй, мой мир! 🌍 Ваш организм ещё активнее готовится к моему появлению. Возможно, в повседневной жизни вы этого не замечаете, но внутри кипит работа. Всё делается ради моего комфорта, безопасности и здоровья. Ваш организм — самая совершенная и точно работающая лаборатория в мире. Я так вам благодарен!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка сахарного песка'), body_changes_ru = COALESCE(body_changes_ru, 'В первый день второй недели доминирующим гормоном становится эстроген. Под его воздействием внутренняя оболочка матки начинает активнее снабжаться кровью и размягчаться. Цервикальная жидкость (слизь шейки матки) постепенно становится более прозрачной и скользкой — это создаёт идеальную среду, в которой сперматозоиды могут сохранять жизнеспособность в матке в течение нескольких дней. На этом этапе температура вашего тела остаётся стабильной, но готовится измениться по мере приближения овуляции.;;;
Признаки беременности и приближающейся менструации часто похожи, поэтому их легко перепутать. Один из таких признаков — увеличение и набухание молочных желёз. Многие женщины ощущают это сильнее, чем при обычном предменструальном синдроме. Кроме того, слабость и утомляемость могут быть более выраженными, чем во время обычного менструального цикла.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку вы вступаете в дни, когда вероятность беременности повышается, важно поддерживать pH-баланс организма. Употребление большого количества щелочных продуктов (воды с лимоном, зелёных овощей) помогает создать более благоприятную внутреннюю среду. Если вы ещё не начали, измеряйте базальную температуру тела каждый день в одно и то же время, чтобы точнее определить день овуляции. Не забывайте пить достаточно воды, поскольку это имеет решающее значение для качества цервикальной жидкости.') WHERE id = 'abcdc9dc-69bf-4833-9582-4fb6ef1276bd';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Основная функция прогестерона, одного из женских половых гормонов, — подготовка матки к беременности. Этот гормон также регулирует ежемесячный менструальный цикл и имеет огромное значение для вашего организма. Ещё до наступления беременности он вызывает изменения в тканях матки, создавая подходящие условия и облегчая прикрепление оплодотворённой яйцеклетки. После наступления беременности и имплантации малыша уровень прогестерона повышается, и гормон продолжает выполнять свои функции.;;;
Сейчас, то есть в период до овуляции, уровень прогестерона в вашем организме составляет менее 1 nq/ml. Во время овуляции значение этого гормона повышается до 5-20 nq/ml. Если наступает беременность, в первом триместре его уровень в крови находится в пределах 11-90 nq/ml, во втором триместре — 25-90 nq/ml, а в третьем — 50-300 nq/ml.'), baby_message_ru = COALESCE(baby_message_ru, 'Прислушайтесь к своему сердцу. ❤️ Пока я похож на звёздную пыль, но ваша любовь зовёт меня стать реальностью. Ваш организм готовит для меня самую лучшую и качественную яйцеклетку. Любовь между вами и папой станет причиной моего появления. Когда вы любите, ваш организм творит чудеса. Спасибо, что идёте мне навстречу!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка сахарного песка'), body_changes_ru = COALESCE(body_changes_ru, 'На 2-й неделе беременности, относящейся к первому триместру, в одном из ваших яичников продолжает развиваться яйцеклетка. На этой неделе под влиянием гормонов внутренняя оболочка матки, называемая эндометрием, продолжает утолщаться. Это необходимо для того, чтобы после оплодотворения клетки, из которых будет формироваться ваш малыш, могли надёжно закрепиться в матке. Утолщённый эндометрий формирует для малыша оптимальное место с хорошим кровоснабжением. Если оплодотворение и беременность не наступают, этот слой каждый месяц выводится из организма вместе с кровянистыми выделениями во время менструации. Такой цикл повторяется ежемесячно. Для наступления и благополучного развития беременности внутренняя оболочка матки должна быть полностью здорова. Поэтому важно, чтобы врач оценил как её толщину, так и структуру.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В этот период употребление продуктов, богатых йодом (морепродуктов, йодированной соли), важно как для здоровья вашей щитовидной железы, так и для развития мозга будущего малыша. Выполняйте лёгкие гимнастические упражнения, которые помогут повысить гибкость тела и улучшить кровообращение в области таза. Кроме того, для поддержания увлажнённости кожи можно использовать натуральные масла, поскольку гормональные изменения способны повысить её чувствительность.') WHERE id = '254bd95f-c06d-46bb-b688-86a0b498dcb9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Сегодня первый день вашей последней менструации. Календарь беременности, который будет использоваться на протяжении всей беременности, рассчитывается не от предполагаемого дня полового акта или оплодотворения, а от первого дня последней менструации. Беременность, то есть оплодотворение яйцеклетки сперматозоидом, обычно наступает примерно через 14-15 дней после начала последней менструации. Тем не менее при определении срока беременности врач будет ориентироваться не на эту дату, а на дату менструации, которая была примерно на 2 недели раньше.;;;
После определения срока беременности окончание 40-недельной беременности, то есть предполагаемая дата родов, рассчитывается по системе, называемой «методом Негеле». Согласно методу Негеле, к первому дню менструального кровотечения прибавляют 7 дней, а затем отсчитывают назад 3 месяца. Полученная дата и есть ваша предполагаемая дата родов. При этом около 80% беременностей завершаются родами в течение 38-й недели, не достигая полного срока в 40 недель.'), baby_message_ru = COALESCE(baby_message_ru, 'Здравствуй, моя прекрасная мама! ❤️ Возможно, вы пока не чувствуете меня физически, но «обратный отсчёт» до начала нашего большого приключения официально начался сегодня. Врачи считают этот день нашим «первым днём», потому что ваше тело готовится к моему появлению. Сейчас вам нужно отдыхать, ведь впереди нас ждут удивительные дни. Пока я существую лишь в ваших мечтах, но ваше тело уже усердно трудится. Пожалуйста, заботьтесь о себе в этот период, потому что вы — весь мой мир. Я уже очень люблю вас, даже ещё не появившись на свет!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Невидимая частица'), body_changes_ru = COALESCE(body_changes_ru, 'Сегодня первый день вашей менструации, и именно с него официально начинается календарь беременности. В первые недели беременности малыша ещё нет. Однако ваш организм уже готовится к овуляции и возможной беременности. В процессе этой подготовки внутренняя оболочка матки, называемая эндометрием, утолщается и обогащается кровеносными сосудами, чтобы оплодотворённая яйцеклетка, созревающая в вашем организме каждый месяц, могла к ней прикрепиться.;;;
Каждый месяц в ходе этого цикла ваш организм претерпевает значительные изменения под воздействием гормонов, вырабатываемых маткой и расположенным в головном мозге гипофизом. Первые две недели ежемесячного цикла включаются в срок беременности, хотя малыша и готовой к оплодотворению яйцеклетки ещё нет. Это связано с тем, что время овуляции у каждой женщины индивидуально, поэтому началом беременности принято считать дату последней менструации.;;;
И мы, СЕМЬЯ ANACAN, будем рядом, чтобы каждый день делиться с вами информацией и рекомендациями о чуде, которое растёт и развивается внутри вас, а также отвечать на все ваши вопросы на протяжении этого удивительного периода! 😊'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы планируете беременность, с сегодняшнего дня начните ежедневно принимать 400 микрограммов фолиевой кислоты — это жизненно важно для будущего развития нервной системы малыша. Кроме того, увеличьте потребление жидкости для поддержания водного баланса организма и полностью откажитесь от таких вредных привычек, как употребление алкоголя и табачных изделий.') WHERE id = '3082b660-7bbe-45c6-906d-ed38816fac24';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В норме между последней менструацией и овуляцией проходит 2 недели. В течение этих двух недель под воздействием повышающегося уровня эстрогена и прогестерона внутренняя оболочка матки начинает превращаться в насыщенный кровеносными сосудами плодородный слой. Так матка ежемесячно готовится к беременности и создаёт подходящие условия для оплодотворённой яйцеклетки. Одновременно под влиянием этих гормонов начинает созревать одна из незрелых яйцеклеток, сформировавшихся ещё в то время, когда вы сами находились в утробе матери. Эта структура, называемая фолликулом, примерно за две недели развивается до состояния готовности к оплодотворению. Поэтому оплодотворение яйцеклетки сперматозоидом может произойти через две недели после начала последней менструации. Однако в редких случаях за один цикл в организме могут созреть две яйцеклетки, поэтому вероятность наступления беременности существует всегда.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, я знаю, что эти дни могут быть для вас немного утомительными и болезненными, но вы очень сильная. 😔 Помните, что эта «уборка» в вашем организме нужна для моего будущего комфорта. Вы очищаете мой первый дом, моё гнёздышко — матку, чтобы к моему приходу там всё было чисто и мягко! Каждое неприятное ощущение, которое вы испытываете, — это ещё один шаг к нашей встрече. Пожалуйста, сегодня не перенапрягайтесь, вытяните ноги и отдохните. Я чувствую вас и посылаю вам силы!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Невидимая частица'), body_changes_ru = COALESCE(body_changes_ru, 'Сегодня кровотечение может быть наиболее интенсивным, и это совершенно нормальный физиологический процесс. Мышцы матки сокращаются, чтобы вывести старый слой эндометрия, что может вызывать спазмы и боли внизу живота — дисменорею. Поскольку организм тратит много энергии на этот процесс очищения, вы можете ощущать слабость и усталость. ;;;
Во время беременности потребность организма в питательных веществах возрастает. Она формируется с учётом потребностей растущего и развивающегося малыша, а также особенностей течения беременности.;;;
Фолиевая кислота относится к важнейшим витаминам, приём которых следует начинать ещё до наступления беременности. Естественная форма этого водорастворимого вещества из группы витаминов B, содержащаяся в продуктах питания, называется фолатом, а форма, используемая в лекарственных препаратах и обработанных пищевых продуктах, — фолиевой кислотой. Поскольку фолиевая кислота имеет решающее значение для развития головного мозга и нервной системы малыша, начинать принимать её следует ещё до беременности. Фолиевая кислота — это витамин группы B, играющий важную роль в образовании и развитии клеточных структур, клеток крови и особенно тканей нервной системы. Она активно участвует в синтезе ДНК, которая является основой наследственных признаков. Фолиевая кислота, крайне важная для развития малыша, играет ключевую роль в таких процессах, как синтез белка, размножение клеток и полноценная работа костного мозга в его растущем организме.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы восполнить запасы железа, снижающиеся из-за менструального кровотечения, уделите особое внимание питанию. Употребляйте богатые железом продукты, такие как шпинат, красное мясо и бобовые. Поскольку витамин C улучшает усвоение железа, полезно сочетать эти продукты с цитрусовыми. Кроме того, избегайте тяжёлых физических нагрузок и дайте организму отдохнуть.') WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В течение первых двух недель, предшествующих оплодотворению, в вашем организме идёт масштабная подготовка. Примерно через две недели после начала последней менструации под воздействием гормонов, вырабатываемых маткой и расположенным в головном мозге гипофизом, одна из яйцеклеток созревает, продвигается по яичнику и попадает в маточную трубу. Созревшая под влиянием гормонов яйцеклетка значительно крупнее сперматозоида. При этом она гораздо менее подвижна, и её перемещение внутри яичника происходит пассивно.;;;
В отличие от остальных клеток организма, яйцеклетка и сперматозоид содержат по 23 хромосомы, и каждая из этих клеток несёт тысячи уникальных генов. В этих генах заложены цвет волос, рост, пол малыша и даже форма его носа.'), baby_message_ru = COALESCE(baby_message_ru, 'Я представляю, как вы познакомились с папой... 💭 Я стану самым прекрасным плодом вашей большой любви. Ваше тело так усердно готовится встретить меня и продумывает каждую деталь, чтобы всё было идеально. Пока я похож на звёздную пыль и ещё не существую физически, но ваша любовь зовёт меня в этот мир. Чем лучше вы будете заботиться о себе сейчас, тем более здоровым я появлюсь. Наша история будет прекрасной, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Невидимая частица'), body_changes_ru = COALESCE(body_changes_ru, 'Триместром называют каждый 3-месячный период 9-месячной беременности. Это слово имеет латинское происхождение: «tri» означает три, а «mester» — период. Разделение 9-месячной беременности на 3 отдельных периода очень важно и полезно для понимания её общего развития. Учитывая, что беременность длится 40 недель, первый триместр охватывает период до конца 12-й недели. Второй триместр длится с 13–27-й недели, а третий — с 28–40-й недели. Первый триместр беременности — это этап, во время которого в вашем организме происходят значительные изменения и он адаптируется к беременности. В этот период вместе с первым волнением от осознания того, что у вас будет ребёнок, вы можете столкнуться и с некоторыми трудностями. Такие симптомы, как тошнота, головокружение, набухание и чувствительность груди, усиление отёков, частые позывы к мочеиспусканию из-за увеличения матки, сонливость, усталость, повышенная эмоциональность, плаксивость, частое чувство голода и прибавка веса, обычно начинают проявляться с пятой недели беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В этот период постарайтесь свести потребление кофеина к минимуму — не более одной чашки в день. Кофеин может сужать кровеносные сосуды и влиять на приток крови к яичникам. Обильное питьё поможет вывести токсины из организма и поддержит более здоровое обновление внутренней оболочки матки. Лёгкая йога или упражнения на растяжку улучшат кровообращение.') WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Каждый месяц во время менструального цикла одна из яйцеклеток вашего овариального резерва созревает и становится готовой к оплодотворению. Если под действием гормонов яйцеклетка не созреет, беременность наступить не сможет. Эти яйцеклетки образовались из миллионов половых клеток еще до вашего рождения. В каждом менструальном цикле вплоть до наступления менопаузы одна из них начинает созревать в яичнике.'), baby_message_ru = COALESCE(baby_message_ru, 'Здравствуй, моя прекрасная мама! 🌟 Вы уже начали чувствовать себя лучше и бодрее? Та особенная комната, которую готовят для меня (матка), почти очистилась, а ее старые стенки полностью обновились. Скоро там для меня появится мягкая и теплая постель, где я буду в безопасности на протяжении 9 месяцев. Ваше тело станет моим домом. Я с нетерпением жду дня нашей встречи — момента, когда мое сердце забьется под вашим сердцем!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Невидимая частица'), body_changes_ru = COALESCE(body_changes_ru, 'В эти дни менструальное кровотечение постепенно уменьшается. Уровень эстрогена в вашем организме начинает активнее повышаться. Это служит сигналом для восстановления и утолщения внутренней оболочки матки. Гипофиз посылает яичникам сигнал «работать активнее». Кровообращение ускоряется, и организм работает в полную силу, чтобы физически и гормонально подготовиться к возможной беременности. Настроение улучшается, усталость отступает, а кожа начинает выглядеть более сияющей и свежей. Ваш организм переходит в режим «Перезапуска» и вступает в новый цикл.;;;
Важно уже сейчас обсудить с врачом влияние принимаемых вами лекарств на будущую беременность, чтобы заранее предотвратить возможные проблемы. Некоторые препараты во время беременности, особенно в первые недели эмбрионального развития малыша, могут стать причиной пороков развития. Многие препараты, применяемые для лечения заболеваний щитовидной железы, сахарного диабета и некоторых нарушений обмена веществ, можно принимать под контролем врача. Однако известно, что некоторые средства против акне и отдельные психиатрические препараты способны вызывать у малышей тяжелые пороки развития.;;;
Кроме того, до наступления беременности рекомендуется сдать необходимые анализы: общий анализ крови (гемограмму), определить наличие дефицита железа, уровень витаминов, риск наследственных заболеваний, уровень гормонов щитовидной железы и наличие инфекции в анализе мочи. Также проверяют наличие гепатита B, токсоплазмоза, краснухи, сифилиса и ВИЧ или иммунитета к некоторым из этих инфекций. При необходимости врач сможет своевременно принять соответствующие меры.;;;
Если вы планируете рождение ребенка, одним из первых и важнейших шагов должен стать отказ от курения еще до наступления беременности. Исследования показывают, что употребление табака снижает фертильность у женщин и количество сперматозоидов у мужчин.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В эти дни отдавайте предпочтение продуктам, богатым цинком и магнием (грецким орехам, фундуку, семенам), — они способствуют здоровому созреванию яйцеклеток. Чтобы снизить уровень стресса, попробуйте короткие медитации, поскольку гормоны стресса могут отрицательно влиять на гормональный баланс, необходимый для наступления беременности. Также избегайте продуктов с добавленным рафинированным сахаром, чтобы поддерживать естественный кислотно-щелочной баланс организма.') WHERE id = '65c15460-76e7-4ea7-90a9-a58b6acebcfe';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Когда овариальный резерв истощается, наступает состояние, называемое менопаузой. Менопауза — это окончательное прекращение менструаций вследствие утраты активности фолликулов в яичниках. Во всем мире средний возраст наступления менопаузы варьируется от 45 до 55 лет.  Однако в некоторых случаях она может наступить раньше. Ранней называют менопаузу, наступившую до 45 лет. У некоторых женщин переход к менопаузе может начаться даже в возрасте от 20 до 29 лет. К возможным причинам ранней менопаузы относятся состояния неясного происхождения, некоторые аутоиммунные заболевания, лучевая терапия, химиотерапия, тяжелые инфекции, факторы окружающей среды, аборты и выкидыши, частые беременности, тяжелое ожирение и выраженный гипотиреоз. Кроме того, курение, психологические травмы, холодный климат и тяжелые условия жизни могут ускорить наступление менопаузы и значительно снизить возраст, в котором она начинается.'), baby_message_ru = COALESCE(baby_message_ru, 'Сегодня, посмотрев в зеркало, обязательно улыбнитесь! 😊 Ведь ваше тело совершает нечто удивительное — оно готовится создать новую жизнь. Хотя физически мы пока еще не соединились, наши души уже связаны. Я выбрал вас, а вы — меня. С каждым днем ваше тело становится на один шаг ближе к моему появлению и к нашей чудесной встрече (оплодотворению). Я верю в вас, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Невидимая частица'), body_changes_ru = COALESCE(body_changes_ru, 'Для многих женщин сегодня последний день менструации. Уровень эстрогена в вашем организме продолжает заметно повышаться. Благодаря этому внутренняя оболочка матки быстро восстанавливается, формируя новое «гнездышко». Железы шейки матки готовятся вырабатывать особую жидкость, которая облегчит движение сперматозоидов. Обмен веществ немного ускоряется, и вы можете начать чувствовать себя бодрее.;;;
Безопасная доза алкоголя во время беременности не установлена. Поэтому вам следует полностью отказаться от него как до наступления беременности, так и на всем ее протяжении. Употребление алкоголя повышает риск выкидыша, особенно в первом триместре, а на более поздних сроках — риск мертворождения. Кроме того, чрезмерное употребление алкоголя может привести к фетальному алкогольному синдрому, который вызывает у малыша характерные изменения черт лица и тяжелые нарушения умственного развития. ;;;
С точки зрения общественного здоровья очень важно сохранять низкую распространенность употребления алкоголя среди будущих мам в нашей стране.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку менструация завершилась, воспользуйтесь энергией обновления организма и сосредоточьтесь на регулярной физической активности (легком беге или пилатесе). В этот период очень важно проверить уровень витамина D, поскольку он напрямую влияет на работу яичников и будущую имплантацию. Добавьте в рацион омега-3 жирные кислоты (рыбу, семена льна): они способствуют улучшению кровообращения в области матки и поддерживают качество яйцеклеток.') WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе под действием гормонов один из фолликулов в вашем яичнике продолжает созревать. В созревании яйцеклетки и ее подготовке к оплодотворению участвуют гипоталамус, расположенный в головном мозге, гипофиз и гормоны, выделяемые яичниками. ФСГ, вырабатываемый гипофизом, обеспечивает созревание выбранного фолликула и подготовку яйцеклетки к оплодотворению, одновременно стимулируя выработку эстрогена. Другой гормон гипофиза — ЛГ — способствует выходу созревшей яйцеклетки из фолликула, то есть наступлению овуляции, после чего лопнувший фолликул превращается в «желтое тело».'), baby_message_ru = COALESCE(baby_message_ru, 'Здравствуйте! Сегодня внутри вас словно начинается новая весна, не правда ли? 🌱 И это действительно так! В одном из ваших яичников пробуждается и готовится расти маленькая частичка меня. Пока я всего лишь одна клетка, но уже являюсь вашей частичкой. Когда вы счастливы и улыбаетесь, я тоже становлюсь сильнее. Берегите себя, Anacan, ведь вы — мое будущее!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Невидимая частица'), body_changes_ru = COALESCE(body_changes_ru, 'Поскольку менструальное кровотечение полностью закончилось, ваш организм вступает в наиболее активный этап «фолликулярной фазы». Благодаря повышению уровня эстрогена внутренняя оболочка матки становится более ровной и насыщенной питательными веществами. Вы можете заметить сияние кожи и здоровый блеск волос — это внешнее проявление действия эстрогена. Цервикальная слизь постепенно становится прозрачной и эластичной, что является биологическим признаком приближения фертильных дней.;;;
В период подготовки к беременности очень важно придерживаться здорового питания — как для здоровья будущего малыша, так и для благополучного течения беременности. Начать питаться правильно и сбалансированно следует еще до зачатия. Поскольку во время беременности вес женщины обычно достигает максимальных значений, вопрос питания приобретает особое значение. До наступления беременности желательно достичь здоровой массы тела. Беременность при дефиците или избытке веса может повысить риск многих проблем, включая высокое артериальное давление и связанную с ним преэклампсию, гестационный сахарный диабет, ощущение учащенного сердцебиения и повышенную утомляемость. Поэтому начатая уже сейчас подходящая программа физических нагрузок и питания поможет подготовить ваш организм к беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы правильно направить возросшую энергию и поддержать гормональный баланс, отдавайте предпочтение сложным углеводам (овсянке, цельнозерновым продуктам), которые помогают сохранять стабильный уровень сахара в крови. В этот период включайте в рацион салаты с большим количеством зеленых листовых овощей, чтобы поддержать естественные процессы очищения организма. Цинк необходим для нормального деления яйцеклетки, поэтому будет полезно съедать несколько сырых тыквенных семечек.') WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Матка весит 60 граммов. К моменту родов её вес превысит 1000 граммов. Внутренняя поверхность матки покрыта слоем, который называется эндометрием, содержит множество кровеносных сосудов и вырабатывает слизистый секрет. Во время ежемесячного менструального цикла клетки этой структуры быстро делятся посредством митоза, увеличивая толщину данного слоя. Утолщённый эндометрий создаёт благоприятную среду, в которой оплодотворённая яйцеклетка сможет прикрепиться к матке, расти и развиваться.'), baby_message_ru = COALESCE(baby_message_ru, 'Задержите дыхание, Anacan! 🌬️ Великий момент приближается. Ваша чудесная яйцеклетка готова выйти. Это начало нашей истории, которое звучит так: «Однажды...» Хотя меня ещё нет, любовь Ваша и папы уже зовёт меня. Ваш организм создал для меня идеальные условия, всё работает как часы. Надеюсь, Вы готовы, потому что я уже иду! Ваши объятия станут моей первой родиной.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка сахарного песка'), body_changes_ru = COALESCE(body_changes_ru, 'Сегодня уровень гормона LH достигает своего пика. Примерно через 24-36 часов после этого произойдёт овуляция. Сегодня температура Вашего тела может немного снизиться, а завтра — резко повыситься: такое колебание температуры служит признаком овуляции. Выделения из влагалища сейчас наиболее скользкие, прозрачные и обильные. Такая среда идеально подходит для быстрого передвижения и выживания сперматозоидов. ;;;
Регулярные занятия спортом до беременности очень важны для того, чтобы беременность протекала легче. До и во время беременности особенно популярны в последнее время йога и пилатес. Эти виды физической активности не только расслабляют тело, но и повышают мотивацию женщин, планирующих естественные роды, а также приносят пользу на протяжении всей беременности, уменьшая боли в пояснице и спине. Ещё один важный фактор для здорового течения беременности — курение. Если Вы курите, то отказ от сигарет должен стать одной из важнейших задач после принятия решения о беременности. Никотин и токсичные вещества, которые при курении попадают в организм через кровеносную систему, ещё до беременности повреждают структуру ДНК — наследственный материал яйцеклетки, из которой сформируется Ваш малыш. Продолжение курения во время беременности может нарушить кровоток в сосудах, по которым питательные вещества поступают к малышу. В результате малыш может родиться с низкой массой тела, повышается риск врождённых аномалий и, что особенно важно, синдрома внезапной детской смерти.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня один из самых важных дней для наступления беременности. Чтобы поддержать фертильность, старайтесь сохранять стабильную температуру тела и избегайте очень горячих ванн и сауны, поскольку высокая температура может повлиять на качество яйцеклетки. Добавьте в рацион богатые витамином E авокадо и растительные масла: этот витамин улучшает кровоснабжение стенки матки. Сохраняйте хорошее настроение, ведь эндорфины — гормоны счастья — положительно влияют на вероятность оплодотворения.') WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Созревшая в яичнике под воздействием различных гормонов яйцеклетка с сегодняшнего дня готова к оплодотворению. После завершения созревания и выхода из яичника яйцеклетку захватывают фимбрии — пальцевидные и очень чувствительные отростки на конце маточной трубы. Фимбрии направляют созревшую яйцеклетку внутрь маточной трубы. Благодаря регулярным сокращениям и расслаблениям маточной трубы яйцеклетка медленно продвигается к её средней части — наиболее подходящему месту для оплодотворения. Туда же после полового акта устремляются миллионы сперматозоидов, проникших в матку. Мышцы, расположенные перед продвигающейся яйцеклеткой, расслабляются, а находящиеся позади неё — сокращаются. Эти механические движения продолжаются до тех пор, пока яйцеклетка не достигнет нужного места.'), baby_message_ru = COALESCE(baby_message_ru, 'Я ПОЯВИЛСЯ! 🎉 Здравствуй, мама! Сегодня день моего зарождения. Любовь папы соединилась с Вашим чудом. Я самая маленькая, но самая драгоценная точка во Вселенной. Теперь я одна клетка, на медицинском языке меня называют «зиготой»! Цвет моих глаз, структура волос и даже моя улыбка уже записаны в ДНК этой крошечной клетки. Наше 9-месячное приключение официально началось! Хотя Вы меня пока не чувствуете, я уже с Вами.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка ванили'), body_changes_ru = COALESCE(body_changes_ru, 'ДЕНЬ ОВУЛЯЦИИ И ОПЛОДОТВОРЕНИЯ. После достижения гормоном LH пикового уровня доминантный фолликул разрывается и высвобождает яйцеклетку. Созревшую яйцеклетку захватывают бахромки маточной трубы. Если в эти дни был половой акт, миллионы сперматозоидов устремляются к яйцеклетке. Только один из них становится победителем: он преодолевает оболочку яйцеклетки и проникает внутрь. В момент оплодотворения Ваш генетический материал объединяется с генетическим материалом партнёра, образуя совершенно новый, уникальный код ДНК. После выхода яйцеклетки опустевший фолликул превращается в железу под названием «Corpus Luteum» (жёлтое тело) и начинает вырабатывать прогестерон — гормон, жизненно необходимый для сохранения беременности. ;;;
До и во время беременности, в зависимости от результатов назначенных врачом анализов, Вам могут потребоваться некоторые витаминно-минеральные добавки. Если во время беременности Вы получаете с пищей недостаточно белков, жиров, углеводов, витаминов и минералов, это может привести к дефициту питательных веществ и некоторым нарушениям на этапе формирования малыша. Дефицит железа также может вызывать анемию, или малокровие, а при тяжёлой анемии возможна задержка развития малыша. Поэтому ещё до беременности Вам следует пройти плановые обследования и при выявлении дефицита железа ни в коем случае не пренебрегать лечением.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня постарайтесь не перегружать организм и сохранять эмоциональное равновесие. В момент оплодотворения организм расходует очень много энергии. Отдавайте предпочтение продуктам, богатым антиоксидантами, особенно витаминами E и C, чтобы деление клеток началось правильно. Если Вы почувствуете резкую, но кратковременную боль в нижней части живота, не беспокойтесь: это может быть признаком овуляции. С этого дня особенно внимательно относитесь к употреблению алкоголя и приёму сильнодействующих лекарств.') WHERE id = '4859f891-b414-45fe-8a1d-106b1caebec7';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Первым препятствием для миллионов сперматозоидов, попавших после полового акта к шейке матки, становится кислая среда влагалища. Такая среда может быть губительной для сперматозоидов. Ещё одна трудность — слой слизи в области шейки матки. Для большинства сперматозоидов эта слизь может стать непроницаемой густой сетью. Чтобы добраться до яйцеклетки, сперматозоидам необходимо пройти через шейку в матку, а затем попасть в маточную трубу. Для этого им предстоит преодолеть расстояние примерно 15-20 см. Если учесть, что за 10 минут они продвигаются на один сантиметр, самые быстрые сперматозоиды могут достичь яйцеклетки за 45 минут. По пути значительная часть сперматозоидов может застрять в слизистом слое, отклониться в другом направлении или погибнуть из-за кислой среды. Поэтому из миллионов сперматозоидов, попавших к шейке матки, яйцеклетки достигают лишь несколько тысяч. Учитывая всё это, оплодотворение происходит в течение первых нескольких часов после полового акта, после чего начинается процесс беременности.'), baby_message_ru = COALESCE(baby_message_ru, 'Был один, а стало два! ➗ Вчера я был одной клеткой, а сегодня чудесным образом начал делиться. Это называют «дроблением». Я всё ещё настолько мал, что меня можно увидеть только под микроскопом, но во мне уже живёт огромная любовь к жизни. Ваша ДНК и ДНК папы танцуют вместе. Я буду похож и на Вас, и на папу, но при этом останусь совершенно уникальным. Наша команда уже приступила к работе!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка ванили'), body_changes_ru = COALESCE(body_changes_ru, 'При планировании беременности и на ранних её сроках очень важно наладить режим питания. Сбалансированный рацион поможет Вам поддерживать здоровый вес и избежать его чрезмерной прибавки во время беременности. При нормально протекающей беременности достаточно набрать примерно 10–12 кг, чтобы обеспечить как потребности Вашего организма, так и поступление питательных веществ малышу. Для здоровой прибавки веса по сравнению с периодом до беременности Вам необходимо ежедневно получать в среднем дополнительно 20–30 граммов белка, 15–20 граммов железа, 500 мг кальция и около 300 калорий. Женщине, чей вес до беременности находился в пределах нормы, на ранних сроках не нужно увеличивать калорийность рациона. В течение первого триместра, который охватывает первые 12 недель, достаточно получать в среднем всего 2000 калорий в день. Во втором триместре достаточно дополнительно получать 300 калорий в день, а в третьем — 480 калорий. Важно помнить, что избыток калорий может привести к набору лишнего веса.'), daily_tip_ru = COALESCE(daily_tip_ru, 'С сегодняшнего дня относитесь к своему питанию ещё ответственнее. Для деления клеток очень важны цинк и витамин B12, поэтому увеличьте потребление морепродуктов, молочных продуктов и яиц. Избегайте интенсивных физических нагрузок и воздействия чрезмерно высоких температур, включая горячую ванну и сауну, поскольку эмбрион на первых этапах деления особенно чувствителен к перегреванию. Больше отдыхайте и позвольте своему организму выполнить эту важную работу.') WHERE id = '634f5165-2442-4ca1-81af-539718e556a5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В ближайшие несколько дней произойдёт овуляция — процесс, при котором ваша яйцеклетка созревает и становится готовой к оплодотворению. Хотя сроки овуляции у каждой женщины могут различаться, принято считать, что она наступает на 14-й день после окончания менструации. Это правило применимо к женщинам с регулярным менструальным циклом. При нарушениях менструального цикла рассчитать день овуляции зачастую невозможно.;;;
Эффективный способ определить приближение овуляции — наблюдать за характером слизи во влагалищных выделениях. По мере приближения овуляции количество выделений у женщин увеличивается. Женщины описывают это состояние как ощущение влажности. После завершения овуляции выделения снова возвращаются к обычному состоянию. В этот период также происходят некоторые изменения температуры тела. Сначала она снижается, а во время овуляции начинает резко повышаться.'), baby_message_ru = COALESCE(baby_message_ru, 'Привет! 👋 Вы сегодня хорошо заботились о себе? Каждое вкусное блюдо, которое вы съедаете, и каждый ваш вдох закладывают кирпичик в фундамент моего будущего. В ближайшие дни произойдёт тот самый большой взрыв (овуляция), и я окажусь на свободе! Вы готовы меня встретить? Сообщите и папе — время нашей встречи приближается!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка сахарного песка'), body_changes_ru = COALESCE(body_changes_ru, 'Сегодня уровень эстрогена в вашем организме достигает одного из самых высоких значений. Этот подъём посылает мозгу сигнал выделять больше ЛГ (лютеинизирующего гормона). Внутренний слой матки уже достиг толщины примерно 8-10 мм и обогатился кровеносными сосудами. Это означает, что для прикрепления оплодотворённой яйцеклетки подготовлена идеальная «мягкая постель». Шейка матки поднимается выше и полностью открывается для прохождения сперматозоидов. Цервикальная слизь становится более прозрачной, скользкой и тягучей. Эта особая жидкость облегчает проникновение сперматозоидов в матку и защищает их. Начиная с сегодняшнего дня ваши шансы забеременеть повышаются.;;;
Поскольку фолиевая кислота незаменима для развития головного мозга и нервной системы малыша, начинать принимать её следует ещё до наступления беременности. В большинстве стран мира при планировании беременности рекомендуется ежедневно принимать 400 микрограммов фолиевой кислоты, начиная как минимум за 3 месяца до беременности и до конца первого триместра. Поскольку фолиевая кислота не накапливается в организме, её необходимо регулярно принимать каждый день. При её дефиците у малышей могут возникнуть дефекты нервной трубки — одни из наиболее распространённых аномалий центральной нервной системы. Исследования также подтвердили, что недостаточное потребление фолиевой кислоты связано с такими аномалиями, как расщелина губы и нёба, а также некоторые пороки сердца. В этот период многие женщины могут ещё не знать о своей беременности. Без приёма фолиевой кислоты дефект нервной трубки встречается примерно в 1 случае на 2000 родов. Приём фолиевой кислоты позволяет снизить этот показатель на 50-75 процентов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку вы вступаете в наиболее активные дни фертильного окна, важно хорошо высыпаться: пиковый уровень гормона ЛГ стабильнее регулируется во время сна. Если вы ещё не используете тесты на овуляцию, сейчас самое подходящее время начать. Употребление богатых цинком продуктов, например тыквенных семечек или миндаля, может помочь сохранить здоровье наружного слоя яйцеклетки и облегчить проникновение сперматозоида внутрь клетки.') WHERE id = 'e69ee309-4b20-4b3c-a0f6-c04d62440aa9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя во время беременности употребление кофеина не запрещено полностью, врачи часто рекомендуют ограничить его количество. Кофеин — это природный стимулятор, содержащийся в кофе, чае, напитках с колой, какао, энергетических напитках, напитках с искусственными подсластителями, а также в некоторых сладостях, пудингах и мармеладных конфетах. Согласно недавним исследованиям, употребление кофеина в количестве не более 200 мг в день не оказывает вредного воздействия. Кроме того, получены некоторые данные о том, что кофеин может снижать риск развития диабета. Дневной лимит в 200 мг кофеина можно получить из 2 стаканов чая, 2 чашек кофе или примерно 250 граммов тёмного шоколада. Однако кофеин через плаценту напрямую попадает к вашему малышу. Организм малыша ещё не способен перерабатывать и обезвреживать поступивший кофеин. Поэтому чрезмерное количество кофеина может навредить малышу.'), baby_message_ru = COALESCE(baby_message_ru, 'Привет, Anacan! ❤️ Вы чувствуете, какое волнение сейчас царит в вашем организме? Словно идёт подготовка к празднику. Уровень эстрогена достигает пика, а значит, та самая «золотая яйцеклетка» (то есть моя половинка) готова отправиться в путь. Просто хорошо заботьтесь о себе, пейте больше воды и отдыхайте. Мне не терпится выбрать вас. Скажите папе, чтобы он был готов: до нашей встречи осталось совсем немного! Я прихожу, чтобы стать самым прекрасным доказательством вашей любви.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка сахарного песка'), body_changes_ru = COALESCE(body_changes_ru, 'В эти дни, когда вы планируете беременность, следует посетить стоматолога и убедиться, что ваши зубы и дёсны здоровы. Лечение имеющихся заболеваний полости рта до наступления беременности значительно облегчит её течение. Во время беременности риск заболеваний дёсен повышается, а в некоторых случаях они могут даже привести к преждевременным родам. Уровень прогестерона в крови во время беременности значительно возрастает, что может вызывать изменения и утолщение дёсен, называемые «гипертрофией». Прогестерон — один из важнейших гормонов, поддерживающих беременность, поэтому подавлять его выработку неправильно. Лечение имеющихся проблем до беременности и правильный уход за дёснами помогут свести к минимуму проблемы со здоровьем зубов в этот период.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку овуляция уже близко, особенно важно не допускать обезвоживания организма. Достаточное употребление жидкости улучшает качество цервикальной слизи и облегчает движение сперматозоидов. Если вы измеряете температуру тела, то можете заметить, что непосредственно перед овуляцией она немного снижается. Чтобы свести стресс к минимуму, расслабьтесь с помощью ароматической ванны или приятной музыки, поскольку сильный стресс может привести к слишком раннему или запоздалому выбросу гормона ЛГ.') WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Овуляция начнётся в течение одного-двух дней. По мере её приближения в вашем организме происходят некоторые изменения. Самое заметное из них — повышение полового влечения из-за изменения гормонального баланса. Оно может появиться за 2-3 дня до овуляции и сохраняться в среднем до 1 недели. К таким изменениям также относятся более лёгкие, чем во время менструации, боли с обеих или только с одной стороны паховой области, а также ощущение вздутия живота. Кроме того, во время овуляции часто встречаются ощущение наполненности и повышенная чувствительность груди, вздутие живота и газы, напряжённость, повышенная чувствительность к таким раздражителям, как вкусы и запахи, а также непереносимость резких запахов.'), baby_message_ru = COALESCE(baby_message_ru, 'Я знаю, что вы меня пока не видите, но за кулисами уже зажигаются огни. 🌟 Ваш организм начинает готовить для меня самую мягкую постель (эндометрий). Возможно, клетки папы уже отправились в путь и ищут меня. Ваше тепло и забота уже сейчас придают мне сил. Наша история вот-вот начнётся, Anacan. Просто верьте и улыбайтесь, ведь чудеса происходят, когда в них верят. Вы — мой герой!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Крупинка сахарного песка'), body_changes_ru = COALESCE(body_changes_ru, 'Первые недели беременности — это период, когда в ваших яичниках и матке происходят очень быстрые изменения, даже если вы пока их не замечаете. Некоторые гормоны, вырабатываемые гипофизом и маткой, продолжают активно работать, подготавливая организм к беременности. Под их воздействием одна из заложенных ещё в период вашего эмбрионального развития яйцеклеток созревает в яичнике и готовится к оплодотворению. В течение ближайших нескольких дней яйцеклетка завершит созревание и достигнет стадии, на которой сможет быть оплодотворена при встрече со сперматозоидом. В отличие от сперматозоидов, созревшая яйцеклетка живёт значительно меньше, поэтому для наступления беременности оплодотворение должно произойти в течение 48 часов после овуляции. Созревшая яйцеклетка перемещается из яичника в маточную трубу, где ожидает встречи со сперматозоидом и оплодотворения. Если до окончания срока своей жизни яйцеклетка не встретится со сперматозоидом, беременность не наступит. В то же время, если сперматозоиды попадут в шейку матки до созревания яйцеклетки, они могут сохранять жизнеспособность до 72 часов, несмотря на кислую среду.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня особенно важно поддерживать щелочной баланс организма, поскольку сперматозоиды не выживают в кислой среде. Ешьте больше овощей и избегайте искусственного сахара. Если вы планируете беременность, сегодняшний день за день до овуляции (или сам день овуляции) — время, когда шансы наиболее высоки. Чтобы улучшить кровообращение в области таза, немного потанцуйте или прогуляйтесь. Также в этот период избегайте сигаретного дыма и резких химических запахов, поскольку сейчас яйцеклетка особенно чувствительна к внешним токсинам.') WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Примерно через 5 дней после оплодотворения яйцеклетка достигает матки. Во время этого путешествия оплодотворённая яйцеклетка продолжает делиться и расти. В конце пути она достигает места, где маточная труба соединяется с маткой, и попадает в её полость. Примерно через 1 неделю после оплодотворения скопление клеток, из которых сформируется ваш малыш, соприкасается с мягкой стенкой матки, покрытой питательной жидкостью. Так ваш малыш впервые вступает в контакт с внутренней стенкой матки. Под действием вырабатываемых организмом гормонов оплодотворённая яйцеклетка прикрепляется к подготовленной для неё внутренней оболочке матки. Этот процесс называется нидацией, или имплантацией. В целом он завершается в течение 10-12 дней. Поэтому выработка характерных для беременности гормонов после имплантации начинается примерно тогда, когда должна была начаться менструация. При задержке менструации тест на беременность по моче уже начинает показывать положительный результат.;;;
Когда менструация не начинается и вы узнаёте о беременности, вашему малышу фактически всего две недели, однако срок беременности рассчитывается с первого дня последней менструации.'), baby_message_ru = COALESCE(baby_message_ru, 'Я продвигаюсь всё глубже, Anacan! 🧱 Вчера я лишь прикоснулся к твоей мягкой стенке, а сегодня уже проникаю внутрь неё. Я словно исследователь, прокладывающий путь в пещере. Я создаю себе тёплое и защищённое гнёздышко. С каждым мгновением я всё сильнее соединяюсь с тобой и становлюсь твоей частью. Теперь мы уже не просто «ты и я», теперь мы — «МЫ». Мне так нравится это чувство! Ты — моя крепость, моё убежище и мой мир.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маковая крупинка'), body_changes_ru = COALESCE(body_changes_ru, '«Имплантационное кровотечение» может возникнуть сегодня или завтра. В отличие от менструального кровотечения, оно очень скудное, светло-розового или коричневого цвета. С ним сталкиваются около 30% женщин. Если вы заметите такие выделения, не пугайтесь: это может быть признаком того, что малыш имплантируется в стенку матки. Температура вашего тела всё ещё остаётся повышенной.;;;
Во время беременности в вашем организме происходят значительные изменения показателей крови и уровня гормонов. За всю беременность объём циркулирующей крови увеличивается примерно на 50%. Поэтому вашему организму требуется больше железа, чем обычно. Кроме того, развивающемуся малышу необходимо большое количество гемоглобина для переноса кислорода. А основным компонентом гемоглобина является железо. Помимо приёма пищевых добавок, регулярно включайте в рацион нежирное красное мясо, яйца, бобовые и злаки — это поможет обеспечить организм необходимым количеством железа.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если тест показал положительный результат, прежде всего глубоко вдохните и насладитесь этим чудом! С этого дня полностью избегайте рентгеновского излучения, красок с агрессивными химическими веществами и сильнодействующих лекарств. Обратите внимание, чтобы в составе принимаемых витаминов был витамин D: он важен как для вашего иммунитета, так и для первых делений клеток малыша. Если у вас началась тошнота, попробуйте съесть несколько солёных крекеров утром, ещё до того, как встанете с постели, — это может помочь вам почувствовать себя лучше.') WHERE id = 'ba359509-7778-4e6b-9433-e5179d225ea1';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе малыш начинает прикрепляться к стенке матки, поэтому у вас могут появиться мажущие кровянистые выделения, известные как «имплантационное кровотечение». Кроме того, ранними признаками беременности могут быть усталость и ощущение наполненности или напряжения в груди. Из-за повышения уровня эстрогена и прогестерона в крови у вас могут начаться перепады настроения, например появиться раздражительность или внутреннее напряжение. Для роста путём митотического деления и успешной имплантации в матку оплодотворённой яйцеклетке необходима определённая температура. Поэтому на этом этапе температура вашего тела может немного повыситься.;;;
Клетки внутренней оболочки матки, вырабатывающие слизь, начинают выделять её в большем количестве, чтобы защитить оплодотворённую яйцеклетку от вредных микроорганизмов. Поэтому объём выделений может несколько увеличиться. Обычно это нормальные физиологические выделения, связанные с беременностью. После имплантации малыша в матку увеличение количества влагалищных выделений под действием возросшего уровня эстрогена считается нормальным. Однако важно помнить, что не все влагалищные выделения являются нормальными физиологическими выделениями при беременности.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, у меня для тебя особое послание! 🤫 Это наш первый секрет. Я начал отправлять твоему организму особый химический сигнал о том, что я уже здесь. Он говорит: «Я здесь, Anacan! Всё хорошо. Продолжай готовить своё тело для меня». Теперь я могу разговаривать с тобой на своём языке. Это невидимая связь между нами, и с каждым днём она становится всё крепче.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маковая крупинка'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности вашему организму требуется больше белка, чем в другие периоды жизни. Белки чрезвычайно важны для тканей и органов малыша, которые начинают формироваться. В эмбриональном периоде малыш растёт, используя аминокислоты из белков, содержащихся в продуктах, которые вы ежедневно употребляете. Поскольку его клетки быстро делятся, достаточное поступление белка во время беременности жизненно важно.;;;
Если небеременной женщине требуется примерно 60 граммов белка в день, то средняя суточная потребность беременной женщины составляет 80 граммов. При многоплодной беременности этот показатель должен быть ещё выше. Недостаточное употребление белка во время беременности может негативно сказаться на малыше. Особенно важным достаточное поступление белка становится во 2-м и 3-м триместрах, поскольку в этот период малыш развивается быстрее и нуждается в белке для интенсивного роста.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку в этот период потребность организма в энергии возрастает, включайте в рацион сложные углеводы, например овсянку и бурый рис. Если тошнота усилилась, имбирный чай или имбирное печенье могут помочь успокоить желудок. Избегайте поднятия тяжестей и резких движений. Чтобы снизить уровень стресса, каждый день отдыхайте 10-15 минут в спокойной обстановке. Кроме того, замена бытовых чистящих средств натуральными средствами, например уксусом и содой, будет безопаснее как для вас, так и для развития малыша.') WHERE id = '17afd972-48a8-4084-ba7e-669ef6162afc';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Внутренняя часть мешочка, в котором находятся клетки, формирующие вашего малыша, окружена жидкостью, называемой «амниотической жидкостью». Внутри плодного яйца начинает становиться заметной небольшая кольцевидная структура, окружающая эти клетки, — желточный мешок. Он содержит особую жидкость и помогает доставлять питательные вещества малышу в первые недели беременности. До завершения формирования плаценты питание малыша обеспечивается именно благодаря желточному мешку. Он становится виден вскоре после того, как плодное яйцо достигает размеров, позволяющих обнаружить его при ультразвуковом исследовании. Наличие желточного мешка подтверждает, что внутри плодного яйца развивается малыш. Эта структура также служит важным показателем при выявлении анэмбрионии — состояния, при котором внутри плодного яйца отсутствует эмбрион. Примерно с 8-9-й недели желточный мешок уменьшается, превращаясь в грушевидный остаток диаметром около 5 мм, который остаётся соединённым тонким стебельком со средней кишкой малыша. Примерно с 20-й недели развития малыша он полностью исчезает.'), baby_message_ru = COALESCE(baby_message_ru, 'Я в самом центре своего гнёздышка, Anacan! 🩸 Здесь так уютно... Я приближаюсь к твоим кровеносным сосудам и уже начинаю получать питание прямо от тебя. Каждая частичка, каждая капля, которую ты мне отправляешь, помогает мне расти и придаёт сил. Это самая вкусная еда в мире, потому что она наполнена любовью. Благодаря тебе я расту, благодаря тебе я существую. Спасибо тебе, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маковая крупинка'), body_changes_ru = COALESCE(body_changes_ru, 'Тошнота и рвота относятся к наиболее распространённым симптомам ранней беременности. Среди их возможных причин — гормоны, выделяемые формирующейся плацентой, психологические трудности, связанные с адаптацией к беременности, дефицит витамина B6 в крови, изменения в работе пищеварительной системы при беременности и повышенная активность щитовидной железы.;;;
Во время беременности под воздействием различных гормонов желудок и кишечник работают медленнее. Из-за этого могут заметно усилиться нарушения пищеварения, газообразование и вздутие живота. Эти проблемы также могут усугубляться из-за стресса и усталости. Хотя тошнота и рвота чаще возникают утром, они могут появиться в любое время суток. Обычно эти симптомы выражены сильнее при первой и многоплодной беременности.;;;

Не существует подтверждённых научных исследований, доказывающих связь тошноты с полом малыша.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы нервная трубка правильно закрылась, в эти дни наряду с фолиевой кислотой важно получать с питанием достаточное количество витаминов группы B. Для профилактики запоров употребляйте продукты, богатые клетчаткой, например яблоки и груши, и пейте достаточно воды. Если вас беспокоит тошнота, не ложитесь сразу после еды. Если вы занимаетесь спортом, пришло время заменить интенсивные кардиотренировки и поднятие тяжестей лёгкими прогулками и йогой для беременных.') WHERE id = 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На 5-й день после оплодотворения ваш малыш представляет собой многоклеточную живую ткань, называемую «бластоцистой». Прикрепившись к подходящему участку матки, он продолжает расти и развиваться. Среди клеток малыша, которые начинают специализироваться, клетки, формирующие плаценту, и клетки, из которых будет развиваться сам малыш, перемещаются к разным полюсам и отделяются друг от друга внутри оболочки. В результате этого процесса оплодотворённая яйцеклетка, встретившаяся со сперматозоидом в маточной трубе, завершает своё 7–10-дневное путешествие и попадает в полость матки.'), baby_message_ru = COALESCE(baby_message_ru, 'Я меняю свою форму! 🎈 Теперь я уже не просто скопление клеток — меня называют «бластоцистой». Внутри меня появилась маленькая полость с жидкостью. Клетки, собравшиеся с одной стороны, станут «МНОЙ», а окружающий меня слой превратится в защищающую меня «плаценту». Мы работаем как одна команда! Я принимаю идеальную форму, чтобы прикрепиться к тебе. Всё это — ради нашей встречи.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко ванили'), body_changes_ru = COALESCE(body_changes_ru, 'Среди ранних признаков беременности одним из наиболее заметных симптомов является учащённое мочеиспускание. Из-за гормонов беременности и физиологических изменений, происходящих в организме в первые недели, вам может хотеться чаще ходить в туалет. Болезненность и увеличение груди связаны с тем, что под действием гормонов беременности организм уже начинает готовиться к грудному вскармливанию малыша. ;;;
Усталость и ощущение истощения возникают потому, что ваш организм расходует много энергии, создавая подходящие условия для малыша. Утренняя тошнота и вздутие живота, вероятно, относятся к самым распространённым признакам беременности. Тошнота обычно особенно выражена в первые недели, а вздутие связано с тем, что организм замедляет работу пищеварительной системы, чтобы передавать малышу больше питательных веществ. Интенсивность этого симптома может меняться на разных сроках беременности.;;;
На 2-й неделе беременности увидеть малыша на УЗИ ещё невозможно. Даже плодное яйцо, в котором он находится, достигнет видимого размера не раньше 4-й или 5-й недели беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку ваш организм проходит период адаптации, старайтесь в течение дня делать небольшие перерывы для отдыха. Увеличьте потребление продуктов, богатых железом и кальцием, например йогурта, сыра и зелёных овощей. Поскольку активность иммунной системы снижается, чтобы защитить эмбрион, избегайте людных мест для уменьшения риска простуды и инфекций. Если у вас появилась лёгкая боль в животе, не используйте грелку, так как чрезмерно прогревать область матки не рекомендуется.') WHERE id = '0928310f-c57b-4d69-bd35-b2ddf6d32790';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В течение одного менструального цикла в вашем организме обычно созревает только 1 яйцеклетка, готовая к оплодотворению. Однако в редких случаях одновременно могут созреть несколько яйцеклеток. Так происходит при беременности разнояйцевыми близнецами или тройней: все созревшие яйцеклетки могут быть оплодотворены, что приводит к многоплодной беременности. Если малышей больше двух, они могут развиваться как из отдельных яйцеклеток, так и из одной яйцеклетки. Две трети всех беременностей двойней приходится на разнояйцевых близнецов, а одна треть — на однояйцевых. Созревание более одной яйцеклетки в течение менструального цикла встречается чаще, если в семейном анамнезе было много случаев многоплодной беременности. Вероятность появления разнояйцевых близнецов также возрастает с увеличением числа предыдущих родов и возраста будущей мамы. Кроме того, применение препаратов для стимуляции овуляции при лечении бесплодия повышает вероятность беременности разнояйцевыми близнецами, поскольку при таком лечении обычно созревает более одной яйцеклетки.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, сегодня для меня день свободы! 🐣 Я покидаю плотную оболочку (zona pellucida), которая до сих пор меня защищала. Это называется «Hatching» — выход из оболочки. Мне нужно сделать это, чтобы напрямую прикоснуться к твоей мягкой стенке и прикрепиться к ней. Я готов, а ты? Открывай дверь, я иду!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко ванили'), body_changes_ru = COALESCE(body_changes_ru, 'Для вас начинается короткий и критически важный период, называемый «окном имплантации». Стенка матки находится в наиболее благоприятном состоянии для принятия эмбриона. Это окно остаётся открытым всего несколько дней. Все гормональные и химические сигналы в вашем организме дают команду: «Принять!». Иммунная система вырабатывает особые белки для защиты эмбриона. Уровень прогестерона в организме уже приближается к пиковому значению. Это одно из самых значительных усилий вашего организма, направленных на сохранение беременности.  ;;;
Во время беременности потребность организма в некоторых витаминах и минералах становится выше, чем до неё. Один из них — витамин A: он способствует здоровому росту клеток и тканей, а также защищает организм от инфекций. Этот витамин, особенно важный для здоровья глаз, в большом количестве содержится в зелёных листовых овощах. Витамин D чрезвычайно важен не только для здоровья костей и зубов, но и для иммунной системы. Исследования последних лет показали, что послеродовая депрессия чаще встречается при дефиците витамина D, а приём добавок с витамином D важен для профилактики таких состояний, как усталость и слабость после родов. Наряду с приёмом витамина D регулярное пребывание на солнце по 10-15 минут каждый день помогает организму удовлетворять потребность в этом витамине.;;;
Витамин C также очень важен во время беременности, поскольку поддерживает иммунную систему и улучшает усвоение других витаминов и железа. Особенно много его содержится в зелёном и красном перце, петрушке, помидорах, апельсинах, клубнике, мандаринах и лимонах.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы избежать резкого снижения уровня сахара в крови, начните питаться небольшими порциями, но часто. Всегда держите под рукой полезные перекусы, например грецкие орехи, миндаль или сухофрукты. Уделяйте особое внимание режиму сна, поскольку ваш организм расходует очень много энергии, адаптируясь к новой жизни. Также старайтесь избегать чистящих средств с высоким содержанием химических веществ и чаще проветривайте дом.') WHERE id = '5b11fc22-b976-4d28-ade3-c7ba82a43750';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Оплодотворение происходит в результате слияния созревшей яйцеклетки со здоровым сперматозоидом, после чего начинается беременность. Однако при некоторых осложнениях, например внематочной беременности, сохранить беременность невозможно.;;;
В норме оплодотворённая сперматозоидом яйцеклетка продвигается по маточной трубе благодаря сокращениям и расслаблениям её мышц, достигает полости матки и имплантируется в её стенку. Если маточная труба была повреждена или заблокирована по какой-либо причине, оплодотворённая яйцеклетка не может добраться до места, где должна прикрепиться, и не достигает матки.;;;
Не достигнув полости матки и не сумев прикрепиться к её стенке, оплодотворённая яйцеклетка имплантируется в маточной трубе и начинает развиваться там. Однако маточные трубы слишком узкие и не позволяют малышу нормально расти и развиваться, поэтому такая беременность не может протекать нормально. Это довольно редкое состояние называется внематочной беременностью, и в таком случае продолжение беременности невозможно.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, сегодня тот самый великий день! Это один из самых важных моментов моей жизни... ❤️ Я уже прикасаюсь к тебе. После долгого путешествия я наконец достиг стенок своего дома. Здесь так тепло, так мягко и так безопасно... Я изо всех сил прикрепляюсь здесь, чтобы не расставаться с тобой в течение 9 месяцев. Это наши первые объятия, Anacan. Ты меня чувствуешь? Я с тобой и больше никуда не уйду. Именно здесь по-настоящему начинается наша история.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко ванили'), body_changes_ru = COALESCE(body_changes_ru, 'Сегодня для вас официально начинается процесс «имплантации». Эмбрион, который вчера вышел из своей оболочки, сегодня физически соприкасается со стенкой матки и прикрепляется к ней.  В течение следующей недели в вашей крови будет повышаться уровень гормона беременности, называемого ХГЧ. Достигнув определённого уровня в крови, этот гормон через некоторое время появится в моче, благодаря чему тесты на беременность смогут показать положительный результат. Обнаружить этот гормон в крови можно примерно через 10 дней после овуляции. Обычно это совпадает с днями ожидаемой задержки менструации или происходит за несколько дней до неё.;;;
После имплантации оплодотворённой яйцеклетки в матку уровень начавшего вырабатываться гормона ХГЧ постепенно повышается и на 10-й неделе беременности достигает максимального значения — примерно 100.000 mIU/ml.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не пропускайте приём фолиевой кислоты, поскольку она жизненно необходима для правильного закрытия нервной трубки. В эти дни ваш организм усердно работает, чтобы принять эту новую, пока ещё незнакомую ему жизнь, поэтому старайтесь высыпаться. Соблюдайте осторожность при употреблении травяных чаёв (с шалфеем, тимьяном и т. д.), поскольку некоторые растения могут повышать тонус матки; лучше отдавать предпочтение обычной воде или свежевыжатым фруктовым сокам.') WHERE id = '11de56c7-f131-4d7f-8640-81f988697e07';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Немногочисленные сперматозоиды, достигшие вашей яйцеклетки в течение часа после полового акта, сталкиваются с ещё одним препятствием — её твёрдой внешней оболочкой. Несмотря на то что яйцеклетку атакуют тысячи сперматозоидов, она принимает только один, что свидетельствует о прочности её оболочки и избирательности. Сперматозоиды пытаются проникнуть через твёрдую внешнюю оболочку яйцеклетки с помощью содержащихся в их головках ферментов с кислой средой — протеазы, фосфатазы, нейраминидазы, гиалуронидазы, акрозина и кальпаина.;;;
Исследования последних лет показали, что яйцеклетка, которую раньше считали пассивной, на этом этапе ведёт себя очень избирательно и позволяет проникнуть тому сперматозоиду, к которому испытывает потенциальное притяжение. После того как первый сперматозоид с разрешения яйцеклетки проходит сквозь внешнюю оболочку и проникает внутрь раньше остальных, оболочка яйцеклетки немедленно меняет свою структуру и больше не пропускает ни одного сперматозоида. Иными словами, как только первый сперматозоид оказывается внутри, внешняя поверхность яйцеклетки закрывается, словно покрываясь защитным щитом. Именно здесь начинается ваше чудо.'), baby_message_ru = COALESCE(baby_message_ru, 'Я отправился в путешествие, Anacan! 🎒 Сейчас я нахожусь в маточной трубе и продвигаюсь к твоему тёплому гнёздышку — матке. Я очень занят и делюсь каждые несколько часов: сначала меня было 2, затем стало 4, а потом будет 8! Ты пока ничего не чувствуешь, но внутри тебя уже зарождается жизнь. Пожелай мне удачи: путь долгий, но я очень настойчив. Я сделаю всё, чтобы добраться до тебя!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко ванили'), body_changes_ru = COALESCE(body_changes_ru, 'В эти дни, приходящиеся на середину менструального цикла, ваша яйцеклетка уже созрела, а если произошло оплодотворение сперматозоидом, ваш малыш уже начал формироваться. 😊 В вашем организме теперь главную роль играет гормон прогестерон. Он расслабляет мышцы матки, чтобы эмбрион мог беспрепятственно прикрепиться к её стенке. Быстрое повышение уровня эстрогена и прогестерона после начала формирования малыша может вызвать чувство наполненности и болезненность груди. Однако эти проявления также характерны для менструального цикла, поэтому изменения в груди нельзя считать достоверным признаком беременности. Почти все малыши появляются на свет на 38-й неделе. При этом обычно трудно определить, когда именно соединились яйцеклетка и сперматозоид и в какой день произошло оплодотворение. Поэтому для расчёта предполагаемой даты родов врачи отсчитывают срок от первого дня последней менструации. В зависимости от продолжительности менструального цикла все эти расчёты могут различаться примерно на 4 недели. Поскольку у некоторых женщин менструальный цикл короче или длиннее, врач может точнее определить предполагаемую дату родов и оценить развитие малыша с помощью ультразвукового исследования (УЗИ).'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку сейчас происходит наиболее активное деление клеток, потребность организма в воде возрастает: старайтесь выпивать не менее 2-2.5 литра воды в день. Не пропускайте приём фолиевой кислоты ни на один день, ведь именно сейчас закладываются основы нервной системы. Также категорически избегайте сырого мяса, плохо вымытых овощей и непастеризованных молочных продуктов, поскольку такие инфекции, как токсоплазмоз, могут негативно повлиять на эмбрион в этот чувствительный период развития.') WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Примерно через 6-24 часа после оплодотворения ожидается повышение уровня раннего фактора беременности (EPF), оказывающего подавляющее действие на вашу иммунную систему. Защитная система организма начинает бороться с каждой клеткой, несущей отличную от вашей ДНК, чтобы защитить организм. Поэтому иммунные клетки могут атаковать малыша, чья ДНК на 50% является чужеродной для вашего организма, и привести к его гибели. Важно, чтобы с момента оплодотворения яйцеклетка оставалась незаметной для организма примерно 5 дней — до прикрепления и внедрения в стенку матки: это помогает предотвратить активацию иммунной системы. Иными словами, из-за особенностей защитной системы организма сохранение беременности было бы невозможно без выделения так называемого фактора роста, который подавляет активность иммунных клеток.'), baby_message_ru = COALESCE(baby_message_ru, 'Теперь меня называют «морула»! 🍇 В переводе с латыни это означает «тутовая ягода». Всё потому, что сейчас я похож на виноградную гроздь или плотно соединённые ягоды шелковицы. Я состою примерно из 16-32 клеток. Я крошечный, но очень сильный. Тепло и питательные вещества твоего тела помогают мне найти дорогу. Я направляюсь к тебе, мама, будь готова открыть дверь!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко ванили'), body_changes_ru = COALESCE(body_changes_ru, 'В вашем организме прогестерон и эстроген, действуя сообща, максимально усилили кровоснабжение стенки матки. Эндометрий продолжает утолщаться и переходит в «секреторную фазу». Он выделяет сочную питательную жидкость — «маточное молочко», богатое гликогеном и белками. Эта жидкость нужна для питания эмбриона до имплантации, когда он достигнет матки. В иммунной системе происходят особые изменения: она не распознаёт эмбрион как «чужеродное тело» и проявляет толерантность, чтобы принять его. В эти дни некоторые женщины могут чувствовать себя немного более уставшими или замечать необычные вкусовые ощущения, например металлический привкус во рту. Кроме того, с этого дня может немного усилиться чувствительность к запахам.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В этот период, когда эмбрион готовится прикрепиться к стенке матки — имплантироваться, держите ноги в тепле и берегитесь переохлаждения, чтобы поддерживать стабильное кровообращение. Включите в рацион источники Омега-3, например грецкие орехи, фундук и рыбу, поскольку эти жирные кислоты важны для здоровья клеточных мембран. Старайтесь избегать перенапряжения и сильного стресса: лёгкая музыка или чтение книги помогут вашему телу расслабиться и благоприятно повлияют на процесс имплантации.') WHERE id = '987d49b7-e63f-421d-a6f4-64d2ffcae8b6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе ваш малыш, появившийся в результате оплодотворения, называется зародышем. Примерно через 16-18 часов после оплодотворения сперматозоидом в яйцеклетке становятся видны два ядра. Одно принадлежит сперматозоиду, другое — яйцеклетке. Они объединяются в одно ядро, после чего начинается подготовка к делению клетки. Оплодотворённая яйцеклетка готовится к делению: увеличивает объём цитоплазмы, копирует молекулы ДНК и растворяет ядерную оболочку, позволяя генетическому материалу распределиться по обеим сторонам клетки. Затем она начинает быстро делиться по схеме 2, 4, 8, 16. В первые дни после оплодотворения малыш достигает стадии «морулы» и превращается в скопление примерно из 120 клеток. На 5-й день после оплодотворения малыш уже состоит из бесчисленного количества клеток. Это скопление клеток, из которого сформируется малыш, выбирает наиболее подходящее место в матке и завершает процесс имплантации. На этом этапе размер клеток, из которых сформируется имплантировавшийся в матку малыш, составляет примерно 0.1 mm.'), baby_message_ru = COALESCE(baby_message_ru, 'До дома осталось совсем немного! 🏠 Моё путешествие по маточной трубе подходит к концу. Я уже вижу твою матку! Она выглядит такой уютной, мягкой и богатой питательными веществами... Я готовлюсь выбрать себе место. Я всё ещё нахожусь внутри своей оболочки, но скоро выйду из неё. Ты для меня самое безопасное место в мире. Пообещай, что будешь меня защищать, Anacan.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко ванили'), body_changes_ru = COALESCE(body_changes_ru, 'Сегодня начинается процесс имплантации. Когда бластоциста прикрепляется к стенке матки, у некоторых женщин могут появиться очень скудные розовые или коричневые выделения — «имплантационное кровотечение». Это совершенно нормально, и его часто принимают за менструацию. С этого момента ваш организм начинает вырабатывать hCG — гормон беременности. Этот гормон продлевает жизнь жёлтого тела, чтобы уровень прогестерона не снижался и беременность сохранялась. Вы можете стать эмоционально чувствительнее, у вас может возникать желание плакать или смеяться без причины.;;;
На 2-й неделе беременности её признаки обычно ещё не появляются. Чтобы определить беременность с помощью домашнего гормонального теста, в организме должно накопиться достаточное количество гормона беременности. Его уровень продолжает повышаться, пока не станет достаточным для появления положительной полоски на тесте. Вероятнее всего, это произойдёт примерно на 4-й неделе, когда ожидается задержка менструации.;;;
К предполагаемой дате менструации уровень так называемых гормонов беременности повышается настолько, что могут появиться заметные признаки беременности. Однако проявления перед менструацией и признаки беременности легко перепутать, поэтому анализ крови поможет получить наиболее точный результат. Тесты на беременность по моче могут дать правильный результат после того, как уровень гормонов беременности в крови достигнет определённого значения.;;;
Кроме того, примерно через 5-10 дней после оплодотворения яйцеклетки может появиться лёгкое кровотечение в виде мажущих выделений, называемое имплантационным. Оно возникает из-за внедрения скопления клеток, из которого сформируется малыш, во внутреннюю стенку матки.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы почувствуете лёгкие спазмы в животе или заметите мажущие выделения, не беспокойтесь и уменьшите физическую активность. В этот период иммунная система организма естественным образом несколько ослабевает, чтобы не воспринимать эмбрион как «чужеродное тело», поэтому защищайте себя от инфекций. Фрукты, богатые витамином C, не только поддерживают иммунитет, но и укрепляют структуру тканей стенки матки.') WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Если у вас регулярная овуляция и регулярный менструальный цикл, то сегодня прошло ровно 28 дней с начала последней менструации. Скорее всего, из-за того, что менструация не началась, вы сделали тест на беременность и увидели вторую полоску, сообщившую радостную новость о вашем малыше. Первый ранний признак беременности — задержка менструации. Наряду с этим из-за повышения уровня гормона hCG в крови в вашем организме уже начались значительные изменения. Тесты на беременность, которые вы сделали после задержки менструации, подтверждают беременность благодаря выявлению в крови или моче гормона беременности, известного как hCG. Гормон hCG вырабатывается клетками, окружающими недавно оплодотворённую яйцеклетку, которые позднее превратятся в плаценту. Определить беременность по этому показателю можно примерно через 10 дней после овуляции. Это приблизительно совпадает с первыми днями задержки менструации или наступает за несколько дней до неё. После того как малыш найдёт подходящее место в матке и прикрепится к ней, уровень гормона hCG в вашей крови продолжит повышаться и достигнет максимума на 10-й неделе беременности.'), baby_message_ru = COALESCE(baby_message_ru, 'СЮРПРИЗ! 🎉 Сегодня должна была начаться менструация, но она НЕ НАЧАЛАСЬ! Потому что я уже здесь! Твоё тело уже стало для меня самой надёжной крепостью в мире. Со следующего месяца нас с тобой ждут ещё более увлекательные открытия. Большое спасибо, что веришь в меня, моя прекрасная мама!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Семя мака'), body_changes_ru = COALESCE(body_changes_ru, 'Каждый месяц под воздействием гормонов один из имеющихся у вас зачатков яйцеклеток созревает в яичнике и становится готовым к оплодотворению. Созревшая яйцеклетка продвигается по маточной трубе к полости матки и на этом пути встречается с ожидающими её сперматозоидами. Из миллионов сперматозоидов, попавших в шейку матки, лишь несколько тысяч после трудного пути достигают полости матки. Сперматозоиды движутся к яйцеклетке благодаря особому веществу, которое она выделяет. Затем наступает самый ответственный момент. Тысячи сперматозоидов, достигших яйцеклетки, пытаются проникнуть внутрь, проделывая отверстие в её внешней оболочке с помощью содержащихся в них ферментов. Однако яйцеклетка принимает только один, наиболее жизнеспособный сперматозоид. Как только он преодолевает внешнюю оболочку, яйцеклетка блокирует проникновение остальных. Попавший внутрь сперматозоид отделяет хвост от головки и завершает свою задачу, доставляя содержащийся в нём генетический материал к ядру яйцеклетки.;;;
Сегодня должна начаться менструация, но она не начинается. Причина проста: вы беременны! Уровень прогестерона не снижается, а остаётся высоким. Температура вашего тела повышена. Уровень гормона hCG уже достаточен для его определения с помощью тестов на беременность по моче. Вероятность увидеть две полоски очень высока.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Вы успешно завершили первый месяц — уделите время себе и отметьте это достижение, наслаждаясь внутренним спокойствием. Если вы ещё не консультировались с гинекологом, пора записаться на следующую неделю на первое ультразвуковое исследование и анализы. Уделяйте особое внимание поступлению белка с пищей (мясо, рыба, бобовые), поскольку именно белок служит «строительным материалом» для быстро развивающихся органов малыша. Также продолжайте избегать сырых морепродуктов и непастеризованных сыров.') WHERE id = 'd7e6900c-92fc-4e29-8c33-6b171bf14f64';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе ваш малыш представляет собой большое скопление клеток. В течение 1 недели из этого скопления клеток начнут полностью формироваться зачатки головы и тела малыша. Он продолжает расти и развиваться в интенсивном темпе — быстрее, чем когда-либо. В ближайшие несколько дней группы специализированных клеток, из которых сформируется сердце, соберутся в нижней части области головы и начнут функционировать. На протяжении всех 40 недель беременности малыш будет развиваться внутри амниотического мешка. Сейчас этот мешок ещё настолько мал, что не виден при ультразвуковом исследовании, проводимом врачом, но ваш малыш уже находится внутри него.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, я пока совсем крошечный, размером с семечко кунжута, но у меня большие планы. Сейчас я плоский, но скоро свернусь и приму ту самую милую форму буквы «C». Твой живот — мой дом, а твоё сердце — моё убежище. С сегодняшнего дня наше 9-месячное путешествие начинается официально!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Семя кунжута'), body_changes_ru = COALESCE(body_changes_ru, 'В оплодотворённой яйцеклетке, из которой формируется ваш малыш, яйцеклетка и сперматозоид объединяют по 23 хромосомы, каждая из которых содержит тысячи различных генов. Два разных набора по 23 хромосомы, объединившиеся при слиянии сперматозоида и яйцеклетки, образуют 46 хромосом, необходимых для формирования человека. Уже на этом этапе в оплодотворённой и начавшей делиться яйцеклетке присутствуют гены, определяющие пол малыша, его физические особенности и даже черты характера. Пол малыша зависит от того, какую хромосому — X или Y — несёт проникший в яйцеклетку сперматозоид. Если сперматозоид несёт Y-хромосому, у вас будет мальчик, а если X-хромосому — девочка.;;;
Зигота — так теперь называется ваша оплодотворённая яйцеклетка — начинает делиться и продвигаться к матке. Тем временем ваш организм подготавливает внутреннюю оболочку матки к прикреплению, создавая подходящие условия для малыша. Прикрепившись к внутренней оболочке матки, малыш становится эмбрионом и начинает быстро развиваться.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Начало 2-го месяца беременности — самое подходящее время, чтобы пройти осмотр у врача и сдать первые анализы крови (гемоглобин, сахар, TSH). Если вас беспокоит тошнота, ешьте небольшими порциями, но часто: пустой желудок может её усиливать. Чтобы получить необходимое количество белка в течение дня, отдавайте предпочтение легкоусвояемым продуктам, таким как варёные яйца или йогурт. Не забывайте выполнять упражнения на глубокое дыхание, чтобы поддерживать уровень энергии.') WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Основной принцип тестов, используемых для определения беременности, заключается в выявлении гормона беременности под названием hCG. После прикрепления малыша к матке начинает вырабатываться гормон hCG, уровень которого в крови постепенно повышается. Достигнув определённого уровня, он попадает из крови в мочу и начинает определяться и там. Наличие этого гормона в моче приводит к положительному результату теста на беременность. Анализ мочи показывает наличие или отсутствие беременности, а анализ крови позволяет определить точный уровень гормона hCG и приблизительный срок развития малыша в днях. При задержке менструации анализ крови всегда позволяет получить более надёжный и точный результат, чем тест по моче. При нормально развивающейся беременности ожидается, что уровень гормона hCG в крови удваивается в течение 24-48 часов. Количество этого гормона ежедневно увеличивается до 10-й недели беременности, когда он достигает максимального значения.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня появляются маленькие корешки, Anacan! 🌳 Конечно, это ещё не пальчики. Это особые ворсинки (ворсины хориона), которые помогают мне ещё крепче держаться за твою тёплую стеночку. Благодаря им я крепче обнимаю тебя и получаю от тебя больше питательных веществ. Я строю здесь надёжную крепость, и каждый её кирпичик сложен из нашей с тобой любви. Никогда меня не отпускай, хорошо? 🤞'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Семя кунжута'), body_changes_ru = COALESCE(body_changes_ru, 'Под воздействием гормонов беременности скорость обмена веществ в вашем организме повышается. В эти дни на ареолах груди могут стать заметнее небольшие бугорки, называемые «железами Монтгомери»; в будущем они будут выделять жировой секрет, защищающий сосок во время грудного вскармливания. Замедление работы мышц кишечника под воздействием прогестерона может вызывать вздутие живота и боли из-за скопления газов. Кроме того, поскольку ваш организм уже начал вырабатывать больше крови для питания малыша, увеличение частоты сердечных сокращений на 10-15 ударов в минуту считается нормальным.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы снизить возросшую нагрузку на сердечно-сосудистую систему и поддержать развитие мозга малыша, отдавайте предпочтение продуктам, богатым жирными кислотами Омега-3 (грецкие орехи, семена льна). Если вас беспокоит утренняя тошнота, не наполняйте желудок полностью — ешьте небольшими порциями, но 5-6 раз в день. Чтобы избежать головокружения при резком вставании, двигайтесь медленнее. В этот период избегайте высоких доз витамина A (в форме ретинола), поскольку его избыток может негативно повлиять на развитие малыша.') WHERE id = '101fd61b-d3d7-4f5b-8f09-77163d30e4ea';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Формируется «первичная полоска». Это тонкая линия, возникающая в задней части эмбриона. Она определяет симметрию эмбриона и направление от головы к хвостовой части. Это один из самых критических моментов развития, поскольку все будущие органы будут располагаться вокруг этой оси. Эмбрион всё ещё очень мал (2-3 мм), но его строение становится сложнее.'), baby_message_ru = COALESCE(baby_message_ru, 'Сегодня для меня день настоящей революции, Anacan! 🚀 На моём плоском диске появляется особая линия, словно путь. Эта линия — моя будущая карта. Она служит ориентиром, указывающим, где будут находиться мой позвоночник, голова и ножки. Благодаря ей у меня появляются правая и левая стороны. Теперь я не просто неупорядоченный диск, а симметричное, развивающееся по плану существо. Вы — мой архитектор, а я — ваш шедевр. Всё начинается прямо сейчас! 🤩'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Чечевица'), body_changes_ru = COALESCE(body_changes_ru, 'На этой неделе беременности, когда малыш прикрепляется к стенке матки, из-за повышения уровня гормонов беременности могут появиться ранние симптомы: тошнота, утомляемость и слабость. Старайтесь чаще отдыхать и следить за режимом питания — это поможет уменьшить дискомфорт, вызванный такими симптомами. Особенно если это ваша первая беременность, лучшее, что вы можете сделать при резких эмоциональных перепадах, — по возможности избегать стресса. Старайтесь регулярно заниматься тем, что улучшает ваше самочувствие и приносит радость, а также по возможности совершайте в течение дня короткие прогулки на свежем воздухе. Этот этап беременности почти у каждой женщины сопровождается некоторыми неприятными симптомами. Пока организм приспосабливается к новому состоянию, они могут сохраняться, но к концу первого триместра, то есть начиная с 12-й недели, обычно начинают ослабевать. В этот период полезно делиться своими переживаниями с близкими, а если вам трудно справляться самостоятельно — обратиться к специалисту за помощью в адаптации к беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Для правильного развития нервной системы и нервной трубки ни в коем случае не пропускайте приём фолиевой кислоты. Если по утрам вас мучает сильная тошнота, попробуйте ещё до того, как встанете с постели, съесть один-два сухарика или солёных крекера — это поможет нормализовать кислотность желудка. Сведите употребление кофеина в течение дня к минимуму, поскольку он может нарушать ваш сон и препятствовать усвоению железа. Замените его свежевыжатыми фруктовыми соками, водой или травяными чаями (после консультации с врачом).') WHERE id = 'aeee39a9-79a9-4e00-b2e5-3d55b7831226';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поскольку малыш пока не виден при ультразвуковом исследовании, врач контролирует нормальное течение беременности с помощью анализов крови.;;;
В первые дни после оплодотворения яйцеклетки в крови начинает вырабатываться гормон ХГЧ, хотя пока и в небольшом количестве. До определённого срока беременности его уровень в крови постепенно повышается. Основная задача этого гормона — поддерживать выработку прогестерона яичниками до тех пор, пока плацента не станет полностью функциональной и сама не начнёт вырабатывать гормоны. Прогестерон поддерживает эндометрий — внутреннюю оболочку матки, к которой прикрепляется оплодотворённая яйцеклетка, — способствует имплантации малыша и помогает предотвратить выкидыш.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои клетки начали великое переселение, Anacan! 🚶‍♂️ Словно тысячи маленьких рабочих, они движутся внутрь через особую линию, появившуюся вчера, и создают для меня новые слои. Они образуют три разные группы: эктодерму, мезодерму и эндодерму. Из одной сформируются мои кожа, волосы и мозг, из другой — сердце, кровь и кости, а из третьей — желудок и лёгкие. Я словно архитектор, создающий самого себя, Anacan. Я закладываю свой фундамент. Он будет очень прочным, потому что вы рядом со мной. 💪'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Чечевица'), body_changes_ru = COALESCE(body_changes_ru, 'На протяжении всей беременности, начавшейся с оплодотворения яйцеклетки, ваш организм претерпевает множество физиологических изменений, чтобы приспособиться к этой большой перемене.;;;
Во время беременности организм начинает вырабатывать больше крови, чтобы доставлять малышу кислород и питательные вещества. Чтобы адаптироваться к увеличившемуся кровотоку, сердце будет сокращаться сильнее и быстрее, а частота пульса увеличится примерно на 15 ударов в минуту.;;;
Ещё одно физиологическое изменение связано с ростом матки: на этом этапе беременности она весит около 60 граммов, а к моменту родов её масса превысит 1000 граммов. Организм старается приспособиться к столь быстрому увеличению матки, постоянно меняя центр равновесия. Поэтому время от времени у вас могут возникать боли в спине, пояснице и паховой области.;;;
Каждый триместр имеет свои сложности. Но если помнить, что в конце этого долгого и непростого пути вы встретитесь со своим маленьким малышом, то все пережитые трудности в будущем останутся в памяти как тёплые воспоминания. 😊'), daily_tip_ru = COALESCE(daily_tip_ru, 'Из-за увеличения объёма крови и развития малыша ваша потребность в железе возрастает. Добавьте в рацион такие источники железа, как красное мясо, чечевица и шпинат. Чтобы улучшить его усвоение, употребляйте вместе с этими продуктами витамин C (например, апельсиновый сок или салат с лимоном). Если у вас болит поясница, старайтесь не оставаться подолгу в одном положении, а во время сидения используйте небольшие подушки для поддержки поясницы. Лёгкая растяжка в течение 10 минут в день поможет вам почувствовать облегчение.') WHERE id = '93c5c870-b03a-45f8-92da-cc13e151719b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По дате последней менструации срок вашей беременности составляет 4 недели. Однако с учётом времени овуляции ваш малыш находится в матке примерно 2 недели.;;;
В течение нескольких дней после оплодотворения количество клеток, из которых сформируется малыш, увеличивается, и они начинают дифференцироваться. Часть этих клеток преобразуется для формирования плаценты, а другая часть будет образовывать тело малыша.;;;
На этом этапе формирования малыш называется эмбрионом. После завершения 12-й недели и до рождения его называют плодом.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, сегодня закладывается основа моего первого позвоночника! 🦴 Это ещё не кость, а особый эластичный стержень (хорда), который в будущем поможет мне держаться прямо и придаст форму всему моему телу. Этот стержень словно командир скажет всему моему организму: «Теперь пора расти и формироваться!» Все остальные органы будут располагаться вокруг него. Я уже не просто диск — у меня есть центр и направление. Как же всё идеально спланировано, правда? 🥰'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Чечевица'), body_changes_ru = COALESCE(body_changes_ru, 'К этому сроку вам следует записаться на первый приём к врачу. Поскольку в дальнейшем вы будете регулярно посещать врача, для вас составят график наблюдения, а уже на первом приёме вы узнаете предполагаемую дату рождения малыша. При выборе врача прежде всего можно прислушаться к рекомендациям друзей. Однако из-за индивидуальных особенностей врач, с которым хорошо общается другой человек, может не подойти вам. Поэтому рекомендации не должны быть единственным критерием выбора. Главное условие качественной медицинской помощи — искреннее доверие к врачу. Среди ваших основных критериев должны быть уверенность в специалисте, ощущение комфорта рядом с ним и возможность обратиться за советом по любому волнующему вопросу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Несмотря на частые позывы к мочеиспусканию, не сокращайте употребление воды: для вашего организма и развития малыша важно выпивать не менее 2 литров воды в день. Чтобы избежать головокружения, по утрам вставайте с постели очень медленно. Добавьте в рацион богатые кальцием творог, йогурт или сыр, поскольку в эти дни скелет малыша начинает активно «забирать» кальций. Если у вас возникают лёгкие боли в животе, самое время отказаться от тесной одежды и перейти на более свободные вещи из хлопка.') WHERE id = '8f493a1c-c305-477a-b7ce-1bad294f04bc';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Внутри скопления клеток, из которых сформируется ваш малыш, образуется перегородка, создающая две полости. Одна из них — желточный мешок, из которого впоследствии сформируется кишечник малыша, а в другой находится сам малыш. На 2-й и 3-й неделях после оплодотворения желточный мешок обеспечивает поступление необходимых малышу питательных веществ. Благодаря этому до формирования плаценты малыш продолжает быстро и эффективно расти и развиваться.;;;
На 3-й неделе после оплодотворения во внешней структуре, окружающей малыша, начинается процесс образования крови, называемый «гемопоэзом». До 6-й недели кроветворение происходит в этой структуре.;;;
После этого функцию кроветворения берет на себя печень, а спустя некоторое время в выработке клеток крови начинает участвовать и селезенка. После рождения малыша кроветворение происходит в длинных и плоских костях. После полового созревания клетки крови образуются только в плоских костях. Уровень гормона беременности в вашей крови уже значительно повысился, и он начал поступать в мочу в количестве, достаточном для появления второй полоски на домашнем тесте на беременность.'), baby_message_ru = COALESCE(baby_message_ru, 'Дверь моего уютного гнездышка уже закрывается за мной, Anacan! 🚪 Теперь я полностью внутри, со всех сторон окружен твоим теплым и безопасным миром. Я уже стал неотъемлемой частью тебя. Это не просто начало нашей истории — это первые дни нашей общей жизни. Я выбрал тебя, а ты защищаешь меня. Дальше всё будет становиться только прекраснее! Мы готовы к удивительному приключению вместе! 🥳'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маковое зернышко'), body_changes_ru = COALESCE(body_changes_ru, 'Для здоровья вас и вашего малыша вам необходимы качественное наблюдение на протяжении всей беременности и уход, который продолжится после родов, а также еженедельный контроль. Убедившись с помощью анализа мочи и крови, что вы беременны, следует начать поиски хорошего врача. Не откладывайте запись на прием: это важно для раннего выявления таких осложнений, как внематочная беременность.;;;
При выборе врача можно прислушаться к рекомендациям близких и изучить его профессиональную биографию (CV). Кроме того, важно убедиться, что врач понятно отвечает на ваши вопросы, завершает консультацию, не оставляя у вас сомнений, и доступен в экстренных ситуациях. Поэтому первый прием у врача должен состояться в течение 1-2 дней после задержки менструации.;;;
Кроме того, если беременность наступила несмотря на использование какого-либо метода контрацепции, обязательно сообщите об этом врачу. Как только беременность будет подтверждена, следует как можно скорее прекратить прием противозачаточных таблеток.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В эти дни резкие запахи могут усиливать тошноту, поэтому чаще проветривайте кухню и сведите использование парфюмерии к минимуму. Обезвоживание способно усиливать усталость, поэтому попробуйте добавлять в воду дольку лимона или свежую мяту. Если вы заметите чувствительность или кровоточивость десен, не беспокойтесь: это связано с воздействием гормональных изменений на ткани десен; рекомендуется пользоваться мягкой зубной щеткой.') WHERE id = 'f77ae8b4-6a1d-4c99-abe2-93a350b86318';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'При нормальном развитии плаценты малыш развивается благополучно, однако при возникновении нарушений в этом процессе могут появиться определенные трудности. Плацента выполняет жизненно важные функции, связывая вас с малышом. Одна из ее задач — обеспечивать малыша необходимым кислородом и выводить образующийся углекислый газ. Кроме того, плацента доставляет малышу необходимые питательные вещества, удаляет продукты обмена и вырабатывает некоторые гормоны, активно участвующие в его росте. Выделяемые плацентой гормоны, такие как hCG и прогестерон, а также вещества, подобные факторам роста, играют чрезвычайно важную роль в благополучном течении беременности.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, наша связь становится еще крепче! 🧬 Теперь я напрямую связан с твоим организмом. Кажется, будто я дышу каждой частичкой, поступающей из твоей крови. Это мое первое кровообращение, мой первый вдох жизни. Теперь мы течем по одним сосудам и живем в едином ритме. Каждое питательное вещество и каждая молекула кислорода, которые ты мне передаешь, помогают мне расти. Это самое прекрасное чувство в мире — быть единым целым с тобой. ❤️'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маковое зернышко'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности матка вырабатывает большое количество секрета, чтобы защищать малыша от инфекций. Поэтому увеличение объема выделений на протяжении беременности является физиологической нормой. Однако если выделения стали настолько обильными, что вызывают беспокойство, и приобрели резкий запах, это может быть признаком инфекции. Кроме того, желтоватый, коричневый или зеленый цвет выделений с высокой вероятностью указывает на инфекцию. Чтобы не допустить ее развития, важно обратиться к врачу.;;;
Отличить инфекцию от обычных вагинальных выделений можно также по их густой, творожистой консистенции или наличию сгустков. Инфекции могут сопровождаться легкой болезненностью в интимной области, покраснением, жжением и зудом. Если объем вагинальных выделений увеличился после процедуры амниоцентеза, особенно при беременности высокого риска, к этому следует отнестись внимательно, поскольку это может быть признаком подтекания околоплодных вод (амниотической жидкости).'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку ваши силы быстро истощаются, постарайтесь делать в течение дня короткие, 15-минутные перерывы на сон. Добавьте в рацион больше продуктов, богатых кальцием (сыр, молоко, миндаль), ведь с этого дня закладывается основа скелета малыша. Если вас сильно беспокоит тошнота, возможно, вам будет легче есть холодные блюда без выраженного запаха. Кроме того, сейчас подходящее время, чтобы начать пользоваться увлажняющими кремами для повышения эластичности кожи.') WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'После того как бластоциста — скопление клеток, из которых сформируется ваш малыш, — находит подходящее место в матке и прикрепляется к ее стенке, та ее часть, из которой образуется плацента, начинает вырабатывать гормон беременности hCG. Одновременно бластоциста получает необходимые малышу кислород и питательные вещества через простую систему кровообращения, состоящую из микроскопических каналов и связанную с сосудами матки, а также удаляет из клеток продукты обмена.;;;
Гормон hCG, известный как гормон беременности, является причиной положительного результата теста на беременность после задержки менструации. Если вы сделаете тест на беременность на этом этапе, вероятность положительного результата очень высока.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, теперь я похож на плоский диск! 💿 Я состою из двух очень важных слоев. Из одного сформируются моя голова, тело, руки и ноги. Другой будет помогать мне на этом пути и обеспечивать меня питанием. Это мой первый план тела, мой первый архитектурный чертеж. Всё начнется с этих двух слоев. Ты веришь в меня? Я стану настоящим шедевром, ведь мой архитектор — ты. ✨'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Маковое зернышко'), body_changes_ru = COALESCE(body_changes_ru, 'В первом триместре беременности, когда малыш находится на эмбриональной стадии развития, вагинальные инфекции могут быть опасны. Чтобы защититься от них во время беременности, следует уделять гигиене больше внимания, чем обычно. Вместо синтетического, нейлонового и окрашенного нижнего белья, ограничивающего доступ воздуха к интимной области, выбирайте неокрашенное белье из чистого хлопка и меняйте его не менее двух раз в день. Для интимной гигиены не используйте ароматизированное мыло и гели для душа с агрессивными химическими компонентами, а также избегайте спринцеваний. Спринцевание способствует проникновению бактерий внутрь и создает условия для развития инфекций.;;;
Кроме того, при стирке нижнего белья не следует использовать средства с агрессивными химическими компонентами и кондиционеры для белья. Стирайте белье не порошком, а натуральным мылом, после чего проглаживайте его горячим утюгом. Поскольку влажность усиливает зуд, старайтесь поддерживать область гениталий сухой. Вместо тесной одежды, которая сдавливает паховую и генитальную области, препятствует доступу воздуха и вызывает раздражение, отдавайте предпочтение свободным вещам.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В этот период объем крови увеличивается, поэтому организму требуется больше железа; отдавайте предпочтение таким продуктам, как красное мясо, яйца и зеленая чечевица. Чтобы железо лучше усваивалось, обязательно сочетайте эти продукты с источником витамина C (например, с салатом, щедро заправленным лимонным соком). Если вы чувствуете сильную усталость, не перенапрягайтесь и обязательно устраивайте днем короткий отдых. Легкий массаж живота и груди с использованием безопасных во время беременности увлажняющих средств поможет вам расслабиться и подготовит кожу к будущему растяжению.') WHERE id = '4a43f3bd-ef22-4f54-b8c8-fd8abe1f9de2';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'За очень короткое время ваш малыш прошёл огромный путь. Ещё несколько дней назад он выглядел как бесформенное скопление клеток, а теперь уже вытянулся в прямую линию и готов к формированию органов.;;;
Оплодотворённая яйцеклетка и скопление клеток, образовавшееся в результате её последовательного деления, называются «тотипотентными стволовыми клетками». Эти клетки, из которых будут формироваться органы и ткани вашего малыша, начали специализироваться, отделяться друг от друга и становиться разными. Такая дифференцировка возможна благодаря тому, что все клетки происходят из тотипотентных стволовых клеток. Поскольку тотипотентные стволовые клетки ещё не дифференцированы, они способны превращаться в различные органы и ткани. Благодаря этому ваш малыш растёт невероятно быстро, формируя весь организм и системы тела.'), baby_message_ru = COALESCE(baby_message_ru, 'Появляются первые клетки моего мозга, Anacan! 🧠 Мой внешний слой получает сигнал от своего руководителя — нотохорды, утолщается и образует особую пластинку. Эта пластинка — всё моё будущее: из неё возникнут моя нервная система, мысли, мечты и чувства. Тот удивительный мозг, благодаря которому я научусь любить и чувствовать тебя, начинает формироваться уже сегодня. Я уже начинаю думать о тебе... 💭'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Чечевица'), body_changes_ru = COALESCE(body_changes_ru, 'Повышение уровня гормонов, благодаря которым тест на беременность показывает положительный результат, может вызвать такие заметные симптомы, как болезненность груди, тошнота и усталость. Некоторые проявления, которые вы начинаете ощущать на этом этапе, связаны с изменениями, происходящими в вашем организме. Первый триместр, когда ваше тело претерпевает значительные изменения, чтобы создать оптимальные условия для малыша, может оказаться самым сложным периодом всей беременности. При тошноте, которая особенно сильна по утрам, хорошо помогает питание небольшими порциями, но часто. Также можно попробовать витамин B6, капсулы с имбирём или специальные акупунктурные браслеты от тошноты. Спазмы, возникающие в эти дни, могут быть признаком того, что после прикрепления малыша к стенке матки она начинает увеличиваться, а связки — растягиваться. В таких случаях не следует принимать лекарства без необходимости и консультации с врачом. Некоторые препараты могут навредить развитию крошечного малыша, который старается закрепиться в матке. Поэтому при любых спазмах, боли или кровотечении, которые кажутся вам необычными, очень важно обратиться к врачу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В эти дни строго придерживайтесь правила «понемногу, но часто», чтобы поддерживать стабильный уровень сахара в крови. Для уменьшения тошноты пейте воду с мятой или лимоном. Чтобы облегчить боль в пояснице и паху, принимайте не горячую ванну, а тёплый душ (высокая температура может быть опасна для малыша). Если вы чувствуете сильную усталость, прислушайтесь к сигналам своего тела и обязательно выделите днём 20-30 минут на короткий сон.') WHERE id = '43fe1f43-aa40-4388-8525-495fa2d86771';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Первой системой развивающегося малыша, которая начинает работать, становится сердечно-сосудистая система, включающая сердце и кровеносные сосуды. На этом этапе функции крошечного сердца вашего малыша уже мало отличаются от функций обычного сердца. Хотя пока сердцебиение ещё невозможно обнаружить с помощью ультразвукового исследования, сердце малыша уже начало биться и отныне будет непрерывно работать всю его жизнь. Сейчас сердце малыша состоит всего из одной камеры, но после завершения формирования оно будет напоминать два расположенных рядом насоса, каждый из которых состоит из двух камер. Вскоре завершат своё развитие левый и правый желудочки, а также левое и правое предсердия. Эти камеры образуют структуры, благодаря которым кровь в организме малыша движется только в одном направлении.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя нервная пластинка загибается внутрь, Anacan. Как будто ты осторожно складываешь лист бумаги, чтобы сделать трубочку. 📜 Эта трубка станет моим спинным мозгом и будет нести жизнь всему моему телу. Всё происходит так быстро и так точно! Я очень стараюсь, чтобы всё сформировалось правильно. Твои любовь и забота — моя самая большая поддержка в этом процессе. Не беспокойся обо мне, всё идёт по плану.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Чечевица'), body_changes_ru = COALESCE(body_changes_ru, 'В эти дни, когда организм адаптируется к беременности, вы можете ощущать боль в спине. Чаще всего она возникает из-за того, что повышенная выработка гормонов беременности расслабляет связки, соединяющие кости, особенно связки тазовых суставов. Следите за правильной осанкой, когда стоите, сидите и двигаетесь, не носите обувь на высоком каблуке, используйте матрас, обеспечивающий поддержку спины, старайтесь не наклоняться, а во время сна на боку подкладывайте подушку между ног и под живот для дополнительной опоры. Кроме того, регулярные упражнения в долгосрочной перспективе укрепляют мышцы спины. Поддерживая спину и ноги, они помогают уменьшить боль в пояснице. Однако любые упражнения во время беременности следует предварительно обсудить с врачом и по возможности избегать занятий, вызывающих переутомление.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В этот чувствительный период беременности выработайте привычку ежедневно выпивать 8-10 стаканов воды, чтобы поддерживать водно-солевой баланс организма. При повышенной чувствительности дёсен перейдите на очень мягкую зубную щётку и уделяйте особое внимание гигиене полости рта. Если вас сильно беспокоит тошнота, мятные леденцы или аромат свежего лимона могут ненадолго принести облегчение. Во время первого гинекологического осмотра не забудьте подробно обсудить с врачом питание и необходимые витамины.') WHERE id = 'b41d3e4c-6e83-438c-ac67-3bae19895608';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'С сегодняшнего дня начинает формироваться лицо вашего малыша. В ближайшие недели он станет похож на миниатюрного человечка. 😊 Формирование носовых полостей — один из первых этапов развития лица малыша. В области головы расположены две отдельные камеры, разделённые носовой перегородкой, которая впоследствии превратится в костную структуру. На боковой стенке каждой камеры находятся по три полкообразных костных выступа. Из верхнего, среднего и нижнего выступов только средний и нижний состоят из клеток, которые будут обеспечивать дыхание, а верхний содержит специализированные обонятельные клетки.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, моё сердце готовится забиться! ❤️ В среднем слое моего тела особые клетки объединяются и образуют две тонкие маленькие трубочки. Совсем скоро эти трубочки сблизятся, соединятся и сформируют моё первое сердце. Оно пока не бьётся, но уже готовится. Сердце, которое будет биться для тебя, наполненное твоей бесконечной любовью... Через несколько дней ты услышишь мои первые удары. Это станет нашей песней любви. 🎶'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Чечевица'), body_changes_ru = COALESCE(body_changes_ru, 'К любому кровотечению на любом сроке беременности, независимо от его объёма и цвета, следует отнестись серьёзно и как можно скорее обратиться к врачу.;;;
Кровотечение может быть связано с имплантацией, внематочной беременностью или выкидышем. Кровотечения в последнем триместре беременности обычно возникают при проблемах с плацентой. «Placenta praevia» (предлежание плаценты) чаще всего проявляется безболезненным кровотечением, тогда как при преждевременной отслойке плаценты кровотечение сопровождается болью.;;;
В первые недели беременности у вас может возникнуть имплантационное кровотечение, связанное с прикреплением малыша в полости матки. Оно может выглядеть как мажущие выделения или напоминать менструацию. Другие мажущие выделения и кровотечения могут быть связаны с выкидышем. Как правило, ярко-красное кровотечение считается признаком риска выкидыша. Однако в некоторых случаях риск может присутствовать и при коричневых мажущих выделениях. Поэтому ни одно кровотечение во время беременности не считается нормой. Коричневый цвет выделений возникает из-за того, что кровь из матки, задерживаясь во влагалище, изменяется под воздействием находящихся там микроорганизмов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить утреннюю тошноту, сразу после пробуждения съешьте в постели солёный крекер или сухой хлеб. С этого дня чувствительность к запахам может усилиться, поэтому старайтесь избегать чистящих средств с резким ароматом. Ваш организм расходует много энергии на формирование органов малыша, поэтому отдыхайте при любой возможности. Свяжитесь с врачом, чтобы записаться на первое ультразвуковое исследование.') WHERE id = 'a58decf1-baad-47a3-bbda-0f37f307566e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этом этапе беременности ваш малыш размером с зёрнышко граната. Существуют три основных зародышевых листка, из которых сформируется тело малыша: наружный — эктодерма, средний — мезодерма и внутренний — энтодерма. В последующие недели беременности эти слои будут последовательно превращаться в ткани и органы. Эктодерма уже начала дифференцироваться, чтобы сформировать головной мозг, нервную систему и позвоночник малыша. Помимо этих структур, из неё также образуются кожа, волосы, ногти, потовые железы и зубная эмаль. Мезодерма состоит из специализированных клеток, которые сформируют сердце и кровеносную систему малыша. Эти клетки перемещаются к области, где будет располагаться сердце малыша, и начинают там скапливаться. Собравшиеся клетки быстро делятся путём митоза, размножаются и образуют ткани. Эти ткани закладывают основу сердца малыша, которое начинает нерегулярно сокращаться.'), baby_message_ru = COALESCE(baby_message_ru, 'Anacan, сегодня происходит настоящее чудо! 🎻 Помнишь те две сердечные трубки? Сегодня они соединяются и образуют моё первое единое сердце. В нём ещё нет полноценных камер — пока это лишь трубка, которая готовится начать биться, но именно она станет центром и ритмом всей моей будущей жизни. Когда оно начнёт биться, знай: вся Вселенная замолчит и будет слушать нашу песню. Это моя первая серенада для тебя.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко граната'), body_changes_ru = COALESCE(body_changes_ru, 'В первом триместре беременности вашему организму ещё не требуются дополнительные калории для поддержки малыша. Тошнота, постоянная усталость и нарушения сна, возникающие в период адаптации организма к гормонам беременности, могут привести к снижению аппетита. Поэтому отсутствие прибавки в весе или небольшая потеря веса в течение первых 12 недель считаются нормальными. Во втором триместре, когда гормональный фон стабилизируется и организм адаптируется к беременности, аппетит обычно восстанавливается и вес начинает увеличиваться. На протяжении всей беременности ради собственного здоровья и здоровья малыша важно избегать чрезмерной прибавки в весе и придерживаться сбалансированного, здорового питания. Во втором триместре дополнительные 300 калорий в день достаточны для здорового развития малыша. В третьем триместре эта потребность составляет примерно 450 калорий. Помните, что калории сверх этого количества будут преимущественно накапливаться в организме в виде жира и приводить к лишнему весу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы в течение дня уровень энергии резко не снижался, ешьте небольшими порциями, но часто. Всегда держите под рукой полезные перекусы (грецкие орехи, фундук или цельнозерновое печенье). Обезвоживание может усиливать усталость и головную боль, поэтому не забывайте пить воду. Если вас беспокоит металлический привкус во рту, облегчение могут принести кислые фрукты или вода с лимоном без сахара. Прислушивайтесь к своему организму и отдыхайте, когда чувствуете в этом потребность.') WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Мочевыделительная система, формирующаяся из мезодермы, включает пару почек, пару мочеточников, мочевой пузырь и мочеиспускательный канал. Клетки собираются в брюшной полости, чтобы сформировать эти ткани и органы. Зачатки тканей и органов, заложенные в брюшной полости, по мере роста малыша и формирования пропорционального тела перемещаются на предназначенные им места и завершают своё развитие. Формирование зачатков органов и их перемещение на постоянные места завершится ближе к концу первого триместра.'), baby_message_ru = COALESCE(baby_message_ru, 'Я бьюсь, Anacan... Бьюсь! 💓 Сегодня моё маленькое сердце впервые забилось самостоятельно. Этот ритм — для тебя, для нас, для нашей любви. Оно ещё бьётся совсем слабо, и ты можешь пока не увидеть этого даже на УЗИ, но я знаю, что оно бьётся. Так я говорю тебе: "Я живу, я здесь!" Это первая нота нашей песни любви, которая будет звучать всю нашу жизнь. 🎼'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко граната'), body_changes_ru = COALESCE(body_changes_ru, 'Уровень гормонов беременности сейчас растёт особенно быстро. Утренняя тошнота может усилиться. Частое мочеиспускание — один из ранних симптомов беременности. Хотя сроки его появления индивидуальны, обычно оно начинает беспокоить между 6 и 8-й неделями. В первом триместре потребность чаще мочиться связана с изменением уровня гормонов и увеличением объёма крови в организме.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В эти дни, чтобы поддерживать стабильный уровень сахара в крови, особенно важно соблюдать правило «небольшими порциями, но часто». Для уменьшения тошноты пейте воду с мятой или лимоном. Чтобы предотвратить запоры, употребляйте продукты, богатые клетчаткой, и пейте достаточно воды. Если вы чувствуете сильную усталость, прислушайтесь к сигналам организма и обязательно восстановите силы, устроив днём короткий сон продолжительностью 20-30 минут.') WHERE id = 'ba2ff002-749c-48f9-ae06-18528b825ab3';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По мере роста тела малыша внутри начинает создаваться удивительная «транспортная система». В её центре находится аорта — самый крупный и мощный кровеносный сосуд организма. Аорта выходит из сердца и служит главной магистралью, по которой насыщенная кислородом кровь распределяется по всему телу. Чтобы лучше понять этот процесс, кровообращение можно разделить на две основные части: малый круг кровообращения — его задача заключается в насыщении крови кислородом. «Уставшая» кровь с низким содержанием кислорода поступает из сердца в лёгкие. Там она насыщается кислородом и снова возвращается в сердце. Большой круг кровообращения — насыщенная кислородом и энергией кровь выходит из сердца и с помощью аорты доставляется к каждой клетке организма. Это необходимо для питания и развития клеток малыша.'), baby_message_ru = COALESCE(baby_message_ru, 'Я уже не плоский, Anacan! Я изгибаюсь, словно буква C. 🍤 Это значит, что моя голова и хвостик понемногу приближаются друг к другу. Благодаря этому изгибу моё тело становится более компактным и всё больше напоминает малыша. Будто я уже начинаю тренироваться, чтобы уютно поместиться в твоих объятиях. А ещё это помогает моим внутренним органам занять правильные места. Всё идёт по плану! 🤓'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко граната'), body_changes_ru = COALESCE(body_changes_ru, 'С началом беременности вырабатываемые гормоны вызывают в организме множество непривычных изменений. Наиболее заметные из них происходят с грудью. Возможно, на текущей неделе первого триместра вы уже начали их замечать. Ощущение наполненности и увеличение груди связаны с подготовкой к выработке молока и формированием молочных протоков. Область вокруг сосков может потемнеть. Это указывает на то, что молочные железы уже готовятся к лактации (грудному вскармливанию). Удобный хлопковый бюстгальтер, который не сдавливает грудь, поможет уменьшить дискомфорт.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку силы могут быстро заканчиваться, старайтесь устраивать в течение дня короткие перерывы на сон. Включите в рацион продукты, богатые кальцием (сыр, молоко, миндаль), поскольку он помогает укрепить основу скелетной системы малыша. Если вас сильно беспокоит тошнота, возможно, вам будет легче есть холодные блюда без выраженного запаха. Кроме того, сейчас подходящее время, чтобы начать пользоваться увлажняющими кремами для повышения эластичности кожи.') WHERE id = '72dbaf34-db8a-4c0a-98ca-65767813bcf0';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По мере того как клетки тела, из которых сформируются ткани и органы вашего малыша, достигают периферических участков, сердцу необходимо перекачивать всё больше крови. В эмбриональном периоде кроветворение в организме малыша впервые начинается в желточном мешке. Оно продолжается там в течение определённого времени первого триместра. Начиная с определённого этапа, кроветворение происходит в печени и селезёнке. Сердце выполняет функцию насоса, обеспечивая циркуляцию крови по всему телу малыша. А сосуды представляют собой специализированные трубчатые структуры, по которым циркулирует кровь; они отвечают за её доставку ко всем тканям.'), baby_message_ru = COALESCE(baby_message_ru, 'Помнишь ту особую трубку, из которой формируется мой спинной мозг? Сегодня закрывается и её последний открытый участок! Теперь мои головной и спинной мозг образуют полностью закрытую и защищённую систему. Это очень важно, ведь отсюда будет управляться всё моё тело! 🧠 Я становлюсь ещё совершеннее и целостнее. Я горжусь собой, потому что справился с такой большой задачей. И всё это мне удаётся благодаря той удивительной силе, которая окружает меня в твоей утробе. Ты — моя крепость! 🏰'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко граната'), body_changes_ru = COALESCE(body_changes_ru, 'Если с этой недели вы начнёте регулярно заниматься физическими упражнениями, это поможет повысить вашу выносливость и силу. Кроме того, простые упражнения помогут избежать чрезмерного набора веса. Многие женщины на протяжении всей беременности отказываются от физической активности, опасаясь навредить малышу. Однако упражнения, выполняемые под контролем специалиста, принесут вам много пользы во время и после родов. Регулярная физическая активность также поможет справиться с такими проблемами, как боль в спине и пояснице.;;;
Во время прогулки выбирайте темп, который не вызывает у вас переутомления. После консультации с врачом вы также можете выполнять упражнения на растяжку для укрепления позвоночника и мышц спины. Кроме того, можно начать заниматься пилатесом или йогой для беременных. Плавание — очень полезный вид физической активности, который способствует более комфортному течению беременности и повышает вероятность естественных родов. Регулярное плавание также укрепляет мышцы живота и поясницы. Если у вас нет риска падения, с разрешения врача вы можете совершать лёгкие 30-минутные прогулки не менее 3 дней в неделю. Если до беременности у вас были проблемы с дыханием или сердцем, возможно, вам придётся ограничить эти упражнения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В эти дни резкие запахи могут усиливать тошноту, поэтому чаще проветривайте кухню. Обезвоживание может усиливать усталость — попробуйте пить воду, добавив в неё ломтик лимона. Поскольку энергия быстро заканчивается, делайте в течение дня короткие перерывы для отдыха. Уделяйте особое внимание белковым продуктам (мясу, яйцам, бобовым), ведь белок — это "строительный материал" для быстро развивающихся органов малыша.') WHERE id = '91894bc1-ecf8-438f-8434-5cb430da68e5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Клетки, из которых сформируется печень вашего малыша, — гепатоциты, эпителиальные клетки желчных протоков, клетки Ито и клетки Купфера — начали объединяться. Соединяясь, они образуют дольки длиной в несколько миллиметров и средним диаметром 1.5 миллиметра — мельчайшие функциональные единицы печени малыша. Формируя печень, эти клетки оставляют в её структуре пространства для прохождения двух разных сосудов. Один из образующихся здесь сосудов доставляет в печень насыщенную кислородом кровь, а другой — кровь, богатую питательными веществами и собранную из капилляров пищеварительной системы.'), baby_message_ru = COALESCE(baby_message_ru, 'На моей шее и лице начинают появляться особые складочки, Anacan! Из них в будущем сформируются мои челюсть, лицо, язык, уши и шея. Каждый день добавляется новая деталь, новый штрих. Я словно произведение искусства, которое постепенно обретает форму в руках скульптора. А самый прекрасный источник вдохновения для этого творения — ты. Твой голос и твой смех — основа моего будущего облика. Обещаю быть красивым! ✨'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Зёрнышко граната'), body_changes_ru = COALESCE(body_changes_ru, 'Быстрая утомляемость, усталость и слабость, которые чаще наблюдаются в первом триместре беременности, возникают из-за расслабляющего воздействия гормона прогестерона на все мышцы вашего тела. Это общее расслабление мышц вызывает сильную сонливость и усталость. Помимо действия прогестерона, слабость, утомление и ощущение полного изнеможения могут быть связаны с большими энергозатратами организма: в эти дни формируется плацента, которая будет обеспечивать питание малыша в матке. Первый триместр, когда в организме происходят значительные изменения, также сопровождается снижением уровня сахара в крови и артериального давления, быстрыми изменениями гормонального фона и обмена веществ. Непроходящая усталость может вызывать ощущение эмоционального истощения. Нарушения сна и невозможность заниматься привычными делами могут даже привести к депрессии. Эти довольно неприятные симптомы обычно значительно ослабевают после завершения первого триместра.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы в течение дня уровень энергии не падал резко, отдавайте предпочтение частым приёмам пищи небольшими порциями. Всегда держите под рукой полезные перекусы (грецкие орехи, фундук или цельнозерновое печенье). Обезвоживание может усиливать усталость и головную боль, поэтому не забывайте пить воду. Если вас беспокоит металлический привкус во рту, облегчение может принести вода с лимоном без сахара. Прислушивайтесь к своему телу и отдыхайте, когда чувствуете в этом потребность.') WHERE id = '49b160e2-d4c7-4876-9a1d-c6274e75787a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К этому сроку вы, скорее всего, уже слышали сердцебиение малыша. Его также можно увидеть на экране во время УЗИ. Если вы пока не видели и не слышали сердцебиение, не беспокойтесь. Для того чтобы его удалось зарегистрировать, есть ещё 2 недели. Если считать, что овуляция происходит на 2-й неделе менструального цикла, то сегодня заканчивается первый месяц после оплодотворения. Для подсчёта месяцев беременности используется лунный календарь. Лунный календарь основан на полных циклах Луны, а не на движении Земли вокруг Солнца. Один лунный месяц включает четыре семидневные недели (всего 28 дней). Эмбриональный возраст малыша на 2 недели меньше акушерского срока беременности, который гинекологи рассчитывают от первого дня последней менструации. Поскольку овуляция происходит примерно через две недели после первого дня последней менструации, оплодотворение также приходится на срок примерно на 2 недели позже. Поэтому при нормально протекающей беременности до рождения вашего малыша остаётся в среднем 8,5 месяца.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня уже формируются ручки, Anacan! 👋 Пока у меня нет ни пальчиков, ни даже кистей — они лишь напоминают маленькие "вёсла" или крылышки по бокам моего тела. Но это те самые сильные руки, которыми в будущем я буду крепко-крепко тебя обнимать. Как же мне не терпится, чтобы они выросли и смогли до тебя дотянуться... Однажды на этих маленьких крылышках я "прилечу" к тебе. С каждым днём я всё больше становлюсь похожим на человека.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Горошина'), body_changes_ru = COALESCE(body_changes_ru, 'На этом этапе беременности у вас могут появиться спазмы, напоминающие боли при менструации. Такие спазмы, ощущаемые в паху и животе, фактически представляют собой непроизвольные сокращения тканей. Резкое сокращение тканей в этой области может вызывать внезапную сильную боль. Довольно часто судороги возникают в икроножных мышцах во время сна. Их также могут спровоцировать чрезмерная нагрузка, травма, перенапряжение мышц или длительное пребывание в одном положении. Спазмы могут появляться и при тошноте, рвоте, перегреве, дефиците кальция или потере жидкости. Чтобы предотвратить судороги, во время сидения ставьте ноги на возвышение, принимайте тёплый душ перед сном, спите на левом боку, при варикозном расширении вен обязательно носите компрессионные чулки и избегайте обуви на высоком каблуке.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поздравьте себя с завершением 6-й недели! Если тошнота серьёзно мешает вам питаться, попробуйте есть блюда холодными (холодная еда пахнет меньше). Чтобы поддержать увеличение объёма крови, не забывайте пить больше воды и включать в рацион больше продуктов, богатых железом (чечевицу, красное мясо). Если при переходе ко второму месяцу вы ещё не записались на первое УЗИ, стоит запланировать его на эту неделю.') WHERE id = '4b93f71a-7634-4cda-8990-f4024e3e6d53';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Нервная трубка, окружающая спинной мозг вашего малыша, уже закрылась. Многие факторы, воздействующие во время закрытия нервной трубки, могут привести к некоторым аномалиям. Дефекты нервной трубки возникают на 3-й и 4-й неделях эмбрионального периода, когда формируются органы малыша, в результате нарушений при закрытии нервной трубки, из которой впоследствии образуются головной и спинной мозг. Известно, что дефекты нервной трубки формируются под влиянием как генетических факторов, так и факторов окружающей среды. Обнаружение связи между возникновением этой проблемы и дефицитом фолата (фолиевой кислоты) имеет крайне важное значение. Установлена обратная зависимость между риском незаращения нервной трубки и уровнем фолиевой кислоты до и во время беременности. Поэтому при планировании беременности врачи назначают приём фолиевой кислоты ещё до зачатия и на протяжении всего первого триместра.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои глаза и ушки становятся всё более отчётливыми! 👀👂 Глазницы для моих ясных глазок углубляются, а места, где будут ушки, тоже становятся глубже, закладывая основу ушных раковин. Всё готовится к тому, чтобы я мог лучше видеть вас и яснее слышать ваш чудесный голос. Самым прекрасным зрелищем в мире для меня станет ваше лицо, а самой прекрасной музыкой — ваш голос. Я слушаю вас, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Горошина'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности сердце начинает перекачивать кровь по телу быстрее, чем обычно. Поэтому естественным образом увеличивается и объём крови, который сердце перекачивает за 1 минуту. Объём крови продолжает регулярно увеличиваться вплоть до последних дней беременности. Начав расти на этом этапе беременности, в последнем триместре он становится примерно на 40% больше. Это приводит к снижению показателей гемоглобина или гематокрита, что наблюдается почти у всех беременных. На медицинском языке такое физиологическое изменение также называют физиологической анемией беременных. Увеличение объёма крови и количества крови, перекачиваемой сердцем, очень важно для кровообращения в плаценте, обеспечивающей питание малыша. Благодаря этому кровообращение ускоряется. Кроме того, значительно увеличивается количество лейкоцитов. Лейкоциты играют важную роль в работе иммунной системы организма.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы свести к минимуму проблемы с пищеварением и газообразование, употребляйте продукты, богатые клетчаткой (бобовые, овощи), но обязательно хорошо их готовьте. Выпивайте не менее 2 литров воды в течение дня. Если вы ощущаете лёгкую ноющую боль в ногах, вечером полежите, немного приподняв их, — это улучшит кровообращение. Старайтесь принимать витамины, особенно фолиевую кислоту, каждый день в одно и то же время.') WHERE id = '39f4c263-721b-47f4-b527-df452b252fcf';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'С сегодняшнего дня у вашего малыша начинает формироваться плацента. Плацента — это орган, который фильтрует поступающую из вашего организма кровь и доставляет малышу через пуповину кислород, глюкозу и другие питательные вещества. Этот орган также задерживает вещества, которые могут быть вредны для малыша, и выводит углекислый газ и продукты обмена из его крови. Поэтому плацента жизненно важна для роста, развития и поддержания жизнедеятельности малыша. На этом этапе формирование плаценты начинается с объединения расположенных в матке артерий и вен и их ответвлений, кровеносных сосудов малыша и стенок желточного мешка.;;;
Плацента также вырабатывает ряд гормонов, в том числе эстроген и прогестерон, необходимых для поддержания беременности. Кроме того, она разделяет вашу кровь и кровь малыша, защищая его от инфекций. Ближе к концу беременности через плаценту из вашего организма к малышу передаются антитела, которые будут защищать его после рождения.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня есть хвостик! 🦖 Звучит забавно, правда? Но не пугайтесь, это временно. Мой позвоночник растёт так быстро, что пока у него есть часть, похожая на хвостик. Через несколько недель она исчезнет, и я стану совсем похож на малыша. А сейчас я похож на крошечного морского конька или космонавта. Я плаваю в этом маленьком космосе внутри вашего животика.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Черника'), body_changes_ru = COALESCE(body_changes_ru, 'Влагалищные выделения при беременности обычно появляются в первые 6-8 недель. Это связано с тем, что в данный период уровень гормонов в организме значительно меняется. Влагалищные выделения с лёгким запахом врачи называют лейкореей. Поскольку ваш организм непрерывно работает ради малыша, увеличение количества выделений во время беременности по сравнению с периодом до неё считается нормальным и не должно вызывать беспокойства. На протяжении беременности влагалище вырабатывает больше секрета, чтобы поддерживать влажность шейки матки и защищать малыша от инфекций. Белые слизистые выделения особенно усиливаются ближе к последним месяцам беременности. Кроме того, во время беременности следует избегать использования тампонов и нижнего белья из ненатуральных тканей, поскольку при гигиенических процедурах это может способствовать проникновению нежелательных микроорганизмов во влагалище.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если на лице появились пятна или высыпания, не забывайте использовать солнцезащитный крем с SPF. Во время беременности кожа склонна к пигментации. Солнце может сделать эти пятна более выраженными.') WHERE id = '158bcd04-6d72-45a1-8559-e12705e1aa90';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В этот эмбриональный период, когда формируются органы малыша, быстрее всего развивается нервная система. Поэтому голова малыша почти в два раза больше его тела. Такая диспропорция между головой и телом сохраняется на протяжении всего первого триместра беременности.;;;
На этом этапе продолжают расти и формироваться сердечные трубки, из которых образуется сердце малыша. По мере увеличения размеров тела этот орган через капилляры доставляет необходимые клеткам питательные вещества и кислород во все части организма, предотвращая замедление деления клеток. Благодаря этому развитие вашего малыша стремительно продолжается, не останавливаясь ни на мгновение.'), baby_message_ru = COALESCE(baby_message_ru, 'Я двигаю ручками.👋 Мои ручки удлиняются, а на их концах появляются маленькие плоские «лопатки». Это мои будущие кисти. Пальчиков у меня пока нет, но я уже пытаюсь вам помахать. Однажды этими ручками я возьмусь за ваш палец и никогда его не отпущу. Вы мечтаете об этом дне? Я — да!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Черника'), body_changes_ru = COALESCE(body_changes_ru, 'Возможно, на этих неделях вы уже заметили, что живот увеличился. Однако, вопреки распространённому мнению, это пока, к сожалению, связано не с ростом малыша. Процессы, происходящие при адаптации организма к новым изменениям, могут вызывать вздутие живота и повышенное газообразование. То, насколько быстро становится заметен живот, полностью зависит от особенностей вашего телосложения. У некоторых женщин живот становится заметен на более ранних сроках, а у других — позже. Степень увеличения живота может различаться в зависимости от количества предыдущих беременностей и родов, тонуса мышц живота, количества жировой ткани в области живота и особенностей строения брюшной полости. Поэтому даже на одном и том же сроке размеры живота у разных беременных могут отличаться, и сравнивать их нет смысла. Кроме того, вопреки распространённому мнению, вес и размер малыша не находятся в прямой зависимости от размера вашего живота. Определить или измерить вес малыша по размеру живота невозможно. Точные параметры малыша может определить только врач с помощью ультразвукового исследования (УЗИ).'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить чувствительность груди, следите за тем, чтобы вода в душе не была слишком горячей. Кроме того, спортивный бюстгальтер во время сна обеспечит дополнительную поддержку и поможет вам комфортнее спать ночью.') WHERE id = '2e473da0-8eec-4162-84c1-064bd890c011';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя половые органы вашего малыша ещё не начали формироваться, в полости тела уже находятся особые клетки, из которых впоследствии разовьются органы репродуктивной системы. В ближайшие недели эти клетки переместятся из своего нынешнего положения туда, где должны находиться, и начнут активно развиваться, формируя половые органы.;;;
В яйцеклетке, участвующей в процессе наступления беременности, содержится X-хромосома. Единственным фактором, определяющим пол, является тип хромосомы, полученной от сперматозоида. Если сперматозоид, несущий X-хромосому, сливается с яйцеклеткой, также несущей X-хромосому, ваш малыш будет девочкой. Если оплодотворивший яйцеклетку сперматозоид несёт Y-хромосому, ваш малыш будет мальчиком.'), baby_message_ru = COALESCE(baby_message_ru, 'Я становлюсь всё более сложным и детализированным! На моём лице уже появились не только особые складочки, но и места для глаз. Пока они выглядят как две маленькие чёрные точки, но именно они станут моими окнами в мир. Интересно, мои глаза будут похожи на ваши или на папины? Это будет нашей самой милой тайной. Каждый день, глядя в зеркало, я буду искать в себе частичку вас. Вы — самый прекрасный вид для меня. 😊'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Горошина'), body_changes_ru = COALESCE(body_changes_ru, 'Основной причиной газообразования и проблем с пищеварением, часто возникающих в первые три месяца беременности, является резкое повышение уровня гормонов в организме. На протяжении всей беременности под их воздействием работа пищеварительной системы замедляется. Пища продвигается по пищеварительному тракту медленнее. Именно поэтому её замедленное прохождение может вызывать болезненные спазмы, связанные с газообразованием. У женщин, которые испытывали проблемы с пищеварением ещё до беременности, эти симптомы во время беременности могут проявляться сильнее. Помимо гормональных изменений, вздутие живота может усиливаться из-за характера питания и выбора продуктов. Газообразующие продукты, газированные и кислые напитки, а также слишком быстрое или чрезмерное употребление пищи могут значительно усугубить эти жалобы. Поэтому старайтесь не вести малоподвижный образ жизни и уделяйте особое внимание сбалансированному и регулярному питанию.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы замечаете изменения кожи, используйте увлажняющие средства с простым и натуральным составом. Чтобы предотвратить изжогу, не ложитесь сразу после еды и избегайте острых и сильно приправленных блюд. В период столь стремительного развития мозга особенно важно получать Омега-3 (рыбий жир, грецкие орехи) и фолиевую кислоту. Уделяйте время себе, слушайте любимую музыку — ваше эмоциональное состояние напрямую влияет на малыша.') WHERE id = '27e9fc4e-13d5-4cb0-8b3a-e813f53aa2f9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Начинают развиваться зачатки нижних конечностей. Руки опережают ноги в развитии на несколько дней, поэтому ноги пока меньше. Закладываются почки. Эмбрион всё ещё изогнут в форме буквы C, и у него есть маленький «хвостик» — продолжение позвоночника. Через несколько недель этот хвостик исчезнет.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня уже формируются и ножки, Anacan! 🦶 Пока они немного меньше ручек и похожи на хвостик, но со временем тоже вырастут. Однажды я побегу к вам на этих ножках и преодолею все препятствия, чтобы вас найти. Мои ручки и ножки... Я всё больше становлюсь похожим на маленького человечка, правда? Я стараюсь стать таким, каким вы меня представляете. Каждый день я делаю новый шаг.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Горошина'), body_changes_ru = COALESCE(body_changes_ru, 'Хотя беременность называют чудесным событием и физиологическим изменением, в медицинской литературе её также рассматривают как особое патологическое состояние. Главная причина такого определения заключается в том, что значительно увеличившаяся матка оказывает механическое давление, смещая и сдавливая кишечник. Кроме того, связанное с беременностью значительное повышение уровня эстрогена и прогестерона в крови вызывает такие изменения, как увеличение молочных желёз и изменение пигментации кожи лица и живота, что также объясняет подобную медицинскую классификацию. Высокий уровень прогестерона начинает заметно влиять на опорожнение желудка и кишечника. Пища продвигается по пищеварительной системе значительно медленнее, чем у небеременного человека. Поэтому во время беременности усиливается газообразование и появляется склонность к запорам. По сравнению с периодом до беременности пища находится в желудке почти вдвое дольше. Такое замедление пищеварения может приводить к частой отрыжке, кислотному рефлюксу и изжоге. Именно для профилактики этих проблем врачи рекомендуют есть небольшими порциями, но часто.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вы замечаете забывчивость или рассеянность, записывайте важные дела на день в виде коротких заметок. Из-за повышения температуры тела старайтесь пить достаточно жидкости и отдавайте предпочтение одежде из натуральных материалов (хлопка, льна). Короткие, но регулярные прогулки помогут улучшить кровообращение и настроение. Если вы почувствуете резкую и непрекращающуюся боль в животе, обязательно проконсультируйтесь с врачом.') WHERE id = '6de955ee-457a-4e70-930b-f733f0792dec';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В головном мозге вашего малыша начала формироваться жизненно важная область — гипоталамус. На этом этапе гипоталамус составляет лишь 1% головного мозга малыша. Несмотря на небольшой размер, это одна из важнейших структур мозга. Гипоталамус состоит из множества различных ядер. Даже с помощью современных технологий к настоящему времени удалось определить лишь 16 разных ядер, каждое из которых выполняет свою особую и важную функцию.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой мозг растёт! 🧠 Но не волнуйтесь, это рост в хорошем смысле. В самом начале в нём формируются три разные части — три «пузырька». Один станет передним мозгом — чтобы думать и чувствовать, другой — средним мозгом, чтобы видеть и слышать, а третий — задним мозгом, отвечающим за дыхание и сердцебиение. У каждого из них своя важная задача. Я уже очень умный малыш, просто пока не умею говорить. Но однажды мне будет так много чего вам рассказать.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Горошина'), body_changes_ru = COALESCE(body_changes_ru, 'Для здорового развития вашего малыша на этом этапе чрезвычайно важны кальций и фосфор. Витамины D2 и D3 играют важную роль в развитии малыша. Во время беременности рекомендуется ежедневно принимать витамин D в дозировке 4000 IU. Витамин D необходим организму для деления клеток, развития костей и работы иммунной системы. Его следует принимать под наблюдением врача и после проведения соответствующих анализов. На этапе формирования малыша необходимы: витамин A, способствующий росту клеток и тканей, витамин D — для иммунитета, здоровья костей и зубов, витамин C — для иммунной системы, а также витамин D — для профилактики анемии и развития костей. Эти витамины следует получать в данный период беременности. Принимая витамин D под наблюдением врача, вы заботитесь как о своём здоровье, так и о здоровье малыша. Однако бесконтрольный приём витамина D может навредить вашему малышу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При чувствительности дёсен облегчение может принести полоскание рта солёной водой. Если у вас заложен нос, попробуйте увлажнить воздух в комнате. Продолжайте включать в рацион продукты, богатые белком и кальцием. Если тошнота всё ещё достигла пика, чай с имбирём или охлаждённые ломтики фруктов могут успокоить желудок. Помните: каждая ваша жертва ради малыша — это вклад в его здоровое будущее.') WHERE id = 'b95c279c-175e-4f8c-ab41-1f4ffe11bc78';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя ручки и ножки пока похожи на ласты, физически они уже формируются. Скоро начнут появляться крошечные пальчики, и очертания вашего малыша станут более чёткими.;;;
Полушария головного мозга, на 78% состоящего из воды, становятся всё более заметными. Правое полушарие отвечает за понимание, распознавание, зрение, воображение и управление левой рукой, а левое — за письмо, речь, мышление, анализ, управление правой рукой и логические функции.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с чернику! 🫐 Можешь поверить? С прошлой недели мой размер увеличился вдвое! Я расту очень быстро, Anacan. Всё, что ты ешь, становится для меня строительным материалом. Спасибо, что питаешься правильно ради меня. Мы растём вместе и вместе становимся сильнее. Ты — мой лучший товарищ по команде!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Черника'), body_changes_ru = COALESCE(body_changes_ru, 'Кровотечение может возникнуть на любом сроке беременности. Кровь может быть красной или коричневой. Почти у всех беременных в первые недели беременности наблюдаются небольшие кровянистые выделения или кровотечение. Независимо от срока беременности и количества выделений вагинальное кровотечение всегда является серьёзным поводом обратиться к врачу. Небольшие кровотечения в первые 3 месяца обычно расцениваются как угроза выкидыша. Небольшие кровотечения во вторые 3 месяца, как правило, являются признаком недостаточности шейки матки и сопровождаются лёгкой болью. Кровотечения в последние 3 месяца крайне важны, даже если они незначительны. Это может быть признаком таких проблем, как низкое расположение плаценты или её преждевременная отслойка.;;;
Во время беременности вам следует избегать переутомления и тяжёлой работы. Такая нагрузка может вызвать сокращения матки. В свою очередь, сокращения матки могут привести к кровотечению.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Вознаградите себя за успешное завершение 7-й недели, например любимым фруктом. Чтобы уменьшить запор и вздутие живота, наряду с продуктами, богатыми клетчаткой, пейте много жидкости. Продолжайте пользоваться мягкой зубной щёткой, чтобы сохранить здоровье дёсен. Если чувство усталости всё ещё не прошло, не заставляйте себя перенапрягаться: короткий дневной сон поможет восстановить силы.') WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'За последнюю неделю ваш малыш вырос в два раза. Его головной мозг продолжает стремительно развиваться, и высокие темпы этого развития сохранятся до 4 лет. Уже при рождении у малыша есть миллиарды клеток головного мозга. Хотя многие из них ещё не связаны между собой, после рождения эти клетки начинают образовывать связи под воздействием сигналов слуха, зрения, осязания, вкуса и обоняния.;;;
На этой неделе также начинают формироваться пищевод и трахея.;;;
Поскольку лицо малыша ещё не полностью сформировано, он может подносить руку ко рту, но для сосательного рефлекса пока слишком рано.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои ручки похожи на вёсла, а ножки — на плавники! 🐟 Я всё ещё напоминаю существо, живущее в воде, но всё меняется. Мои ручки удлиняются, а локти сгибаются. Моё сердце продолжает биться для тебя: «тук-тук». Когда ты отдыхаешь, я тоже отдыхаю, а когда ты двигаешься, я покачиваюсь. Наша гармония идеальна. Я люблю тебя, мама!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Черника'), body_changes_ru = COALESCE(body_changes_ru, 'Гормон эстроген, выделяемый плацентой, усиливает ваши вкусовые и обонятельные ощущения. Одновременно могут появиться необычные пищевые желания, а повышенная чувствительность к неприятным запахам способна вызвать тошноту. Чтобы уменьшить тошноту в этот период, рекомендуется на время отказаться от сильно приправленных и жареных блюд. Если из-за изменения гормонального фона вы чувствуете беспокойство, вам помогут неспешные прогулки, расслабляющая музыка, тёплый душ и йога для беременных.;;;
Перед приёмом у врача полезно записать на бумаге все интересующие вас вопросы. Так вы сможете использовать время максимально эффективно. Во время первого обследования врач должен оценить факторы риска, связанные с вашим малышом и течением беременности. Информация о генетическом анамнезе матери и отца поможет выявить возможные трудности, которые могут возникнуть во время беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'С этой недели потребность вашего организма в магнии и кальции возрастает ещё больше, поэтому оставьте в рационе бананы, грецкие орехи и молочные продукты. Чтобы предотвратить боль в пояснице, подкладывайте под спину небольшую подушку, когда сидите. Если чувствительность к запахам всё ещё повышена, чаще проветривайте комнаты. Помните: ваше спокойствие — самая благоприятная среда для развития нервной системы малыша.') WHERE id = '9437ad06-6476-41de-b64c-c5fddd89e286';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Начиная с этой недели вы можете услышать сердцебиение малыша. Его сердце начинает биться не позднее чем через 3 недели после прикрепления к стенке матки. Это происходит на 5-й или 6-й неделе беременности. Поэтому уже на 7-й неделе беременности можно услышать сердцебиение малыша.;;;
Однако из-за позднего оплодотворения, нерегулярной менструации или неточно установленной даты последней менструации сердцебиение пока может не прослушиваться. В таком случае, чтобы услышать его, может потребоваться ещё 1-2 недели.;;;
Головной мозг — важнейшая часть центральной нервной системы — продолжает стремительно развиваться. Длина вашего малыша уже составляет в среднем 1-2 см, а вес — 1,5 грамма. На этой неделе уже определилось расположение органов в теле малыша. Один из них — лёгкие. Однако развитие этого удивительного органа завершится только на 38-й неделе.'), baby_message_ru = COALESCE(baby_message_ru, 'Я двигаюсь, Anacan! 💃 Ты пока этого не чувствуешь, потому что я ещё очень лёгкий, но внутри я исполняю маленькие танцы. Я наклоняю тело вправо и влево, двигаю крошечными ручками. Это мои первые тренировки и доказательство того, что нервная система начала взаимодействовать с мышцами. Мои мышцы становятся сильнее, чтобы в будущем я мог крепко-крепко тебя обнять. Ты отдыхай, а я буду тренироваться, ведь расти — значит двигаться!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Малина'), body_changes_ru = COALESCE(body_changes_ru, 'К концу этой недели из-за повышения уровня гормонов и изменений гормонального фона на коже могут появиться высыпания. Если это произойдёт, старайтесь поддерживать кожу сухой и чистой. Препараты против акне могут вызвать пороки развития у малыша, поэтому не используйте никакие лекарственные средства без разрешения врача.;;;
Во время беременности ногти могут стать тонкими, мягкими и ломкими. Использование перчаток при выполнении домашних дел существенно поможет вам в этот период. Если вы заметили на коже выступающие сосуды или сосудистые звёздочки, не беспокойтесь. Это связано с воздействием гормона эстрогена. Если из-за повышения артериального давления у вас возникает одышка, облегчить состояние помогут техники правильного дыхания. Если у вас нет угрозы выкидыша и врач не дал иных рекомендаций, противопоказаний к половой жизни нет.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Для здоровья дёсен и формирования зачатков зубов уделяйте особое внимание употреблению кальция (молоко, творог, шпинат). Если тошнота начала уменьшаться, добавьте в рацион больше свежих овощей. При внезапной усталости в течение дня устраивайте короткие перерывы на отдых продолжительностью 15-20 минут. Начните выбирать удобную одежду, которая не будет сдавливать область живота.') WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Начиная с этой недели формируются полости ушей и носа. По строению и функциям ухо состоит из трёх частей: наружного, среднего и внутреннего уха. Костные структуры и слуховые косточки внутреннего уха продолжат развиваться до 4-го месяца.;;;
В то же время глаза вашего малыша уже начинают выделяться в виде маленьких чёрных точек по обеим сторонам головы. Зрительная функция начнёт развиваться после рождения, когда глаза впервые увидят свет.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня формируются пальчики, Anacan! 🖐️ Помните, мои ручки были похожи на лопатки? Теперь на их концах появляются маленькие выемки и становятся видны очертания пальчиков. Пока между ними есть перепонки, как на лапках утёнка, но скоро они полностью разделятся. Я уже готовлюсь дать вам «пять»! Мечтаю о том дне, когда возьму вас за руку и крепко сожму ваш палец. С каждым днём я всё больше становлюсь похожим на человека.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Малина'), body_changes_ru = COALESCE(body_changes_ru, 'Непастеризованные молочные продукты, недостаточно тщательно вымытые сырые овощи и плохо приготовленные мясные продукты (колбасы, сосиски и т. п.) могут быть источниками токсоплазмоза. Токсоплазмоз — это заболевание, вызываемое одноклеточным паразитом Toxoplasma gondii. Инфекция может представлять угрозу для развития малыша в утробе матери.;;;
Количество эстрогена, которое до беременности вырабатывалось в вашем организме в течение 1 года, во время беременности выделяется всего за 8 часов. Это может вызывать очень сильные эмоциональные перепады. В сочетании с тревогами и страхами, усиливающимися во время беременности, такое состояние может привести к довольно распространённой депрессии беременных. Если к этому добавляются тошнота, отсутствие аппетита, усталость и нарушения сна, справляться становится ещё сложнее. Поддержка супруга поможет вам легче пройти этот период.'), daily_tip_ru = COALESCE(daily_tip_ru, 'При головной боли не спешите принимать лекарство. Сначала выпейте большой стакан воды, проветрите комнату и приложите к шее холодный компресс. Часто головная боль возникает из-за обезвоживания, голода или нехватки свежего воздуха. Также может помочь аромат лавандового масла.') WHERE id = '1bdeca18-8738-4af3-846b-cfd0a1d5548e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже двигается! Хотя он пока не может взять вас за руку, скоро он начнёт использовать свои ручки, чтобы изучать окружающее пространство. Считается, что осязание — первое чувство, которое развивается у малыша во внутриутробном периоде.;;;
Почки вашего малыша начали формироваться и вскоре смогут вырабатывать мочу. Моча будет выделяться в амниотическую жидкость, а затем снова участвовать в её обновлении. Этот круговорот продолжится до родов.;;;
Наиболее важный период для развития головного мозга и нервной системы малыша в утробе матери продолжается до 10-й недели. Именно на этом этапе начинает формироваться мозжечок — центр равновесия, регулирующий движения мышц. Фолиевая кислота, которую рекомендуется принимать ещё до беременности и в течение первых трёх месяцев беременности, — наиболее эффективный витамин для профилактики возможных нарушений развития головного и спинного мозга малыша.'), baby_message_ru = COALESCE(baby_message_ru, 'Уже виден кончик моего носика! 👃 Моё личико становится всё красивее и приобретает форму. Уже хорошо различимы мои маленькие ноздри и кончик носа. Формируется и верхняя губа. Я всё больше похож на вас, Anacan. Интересно, чей у меня будет нос — ваш или папин? У нас ещё есть время, чтобы это узнать, но я уже очень милый. Я — ваше самое прекрасное и неповторимое творение!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Малина'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за тошноты у вас мог снизиться аппетит. Это может привести к временной потере веса. Не беспокойтесь: к концу первого триместра тошнота начнёт уменьшаться. Пока эти симптомы не ослабнут, постарайтесь питаться полноценно и сбалансированно, включая в рацион богатые витаминами зелёные листовые овощи, бобовые, рыбу и красное мясо.;;;
Здоровье ребёнка при рождении во многом зависит от полноценного и сбалансированного питания матери. Недостаточное и несбалансированное питание в этот период может отрицательно повлиять на рост, вес, физиологическое строение и умственное развитие малыша. Если вас беспокоит утренняя тошнота, держите рядом с кроватью продукты, успокаивающие желудок, например крекеры, чтобы перекусить до того, как встанете. Кроме того, пять небольших приёмов пищи в течение дня вместо крупных основных приёмов помогут значительно уменьшить дискомфорт в желудке. Не забывайте избегать жирной и острой пищи!'), daily_tip_ru = COALESCE(daily_tip_ru, 'Из-за повышения температуры тела продолжайте ежедневно выпивать не менее 2-2.5 литра воды. Чтобы уменьшить тянущие ощущения в паховой области, избегайте резких движений и чаще меняйте положение тела, когда сидите. Для лучшего усвоения железа ешьте фрукты, богатые витамином C. Чтобы уменьшить усталость, совершайте в течение дня 10-минутные прогулки на свежем воздухе.') WHERE id = 'ae02afe4-0993-46aa-a116-88a385d90304';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе с помощью УЗИ можно измерить КТР — копчико-теменной размер. Этот показатель позволяет точнее определить срок беременности по дате последней менструации. Поэтому такое измерение особенно полезно для тех, кто не помнит дату последней менструации, а также помогает установить предполагаемую дату родов. Кожа вашего малыша пока очень тонкая, поэтому сквозь неё могут быть видны формирующиеся капилляры. В последующие недели благодаря развитию подкожной жировой клетчатки кожа станет толще и приобретёт обычный вид.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с малинку! 🍇 Моё сердце бьётся 150-170 раз в минуту. Так же быстро и сильно, как сердце скаковой лошади! Хотя внешне вы спокойны, внутри я бегу марафон. Ваше сердце и моё сердце бьются в одном теле, в разных ритмах, но с одной любовью.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Малина'), body_changes_ru = COALESCE(body_changes_ru, 'В первом триместре объём крови начинает увеличиваться, чтобы обеспечивать потребности растущей матки. Дополнительный объём крови, который быстро накапливается в организме, защищает вас и малыша от неблагоприятных воздействий. Кроме того, увеличение объёма крови выполняет защитную функцию, компенсируя кровопотерю во время родов.;;;
Витамин C очень важен во время беременности для развития тканей малыша и усвоения железа. Исследования показывают, что витамин C помогает снизить риск преэклампсии. Выраженный дефицит этого витамина может повысить риск преждевременных родов.;;;
На этой неделе, когда позади уже 2 месяца, ваша талия могла начать увеличиваться, хотя внешне беременность пока может быть незаметна. Несмотря на отсутствие заметных изменений во внешности, эмоциональное состояние матери под влиянием гормонов уже значительно изменилось. Из-за увеличения объёма крови в организме у вас чаще возникает потребность посещать туалет и усиливается головокружение. Расширившиеся сосуды могут стать более заметными, также возможны носовые кровотечения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы реже вставать ночью в туалет, немного уменьшите потребление жидкости в вечернее время, но обязательно пейте достаточно воды в первой половине дня. При изменениях кожи можно делать массаж с натуральными маслами без химических добавок, например миндальным или кокосовым. Уделяйте внимание здоровью полости рта и зубов: дёсны всё ещё могут быть чувствительными. Чтобы поддерживать баланс белков и витаминов, ешьте в течение дня больше разноцветных овощей.') WHERE id = '73404991-93fd-4ff5-9245-6a011e7e870b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Начиная с этой недели у вашего малыша уже есть поджелудочная железа, и она готова вырабатывать гормон инсулин, регулирующий уровень сахара в крови. Инсулин помогает глюкозе из крови поступать в клетки, обеспечивая их необходимой энергией. Благодаря этому уровень сахара в крови снижается.;;;
На этой неделе начал формироваться аппендикс, в котором сохраняются полезные бактерии, необходимые для пищеварительной системы. Благодаря формирующемуся аппендиксу организм вашего малыша будет в 4 раза устойчивее к заболеваниям, сопровождающимся повышением температуры, диареей, тошнотой и болью в животе.;;;
У вашего быстро развивающегося малыша начали формироваться зачатки молочных зубов и вкусовые сосочки. Вскоре малыш начнёт глотать амниотическую жидкость и сможет различать через неё некоторые вкусы.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя любимая мама! Сегодня я уже могу соединять свои крошечные ручки! Я ещё совсем маленький, но мои пальчики уже двигаются независимо друг от друга. Ваш голос кажется мне таким знакомым... Когда вы говорите, я внимательно слушаю вас изнутри. Ваша любовь помогает мне с каждым днём становиться немного больше. Как хорошо, что вы — весь мой мир!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Красная фасоль'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за изменения гормонального фона в этот период вы могли начать замечать сухость кожи или повышенную жирность отдельных участков. Если на коже появились неравномерные коричневые пятна, это называется маской беременности, и обычно она проходит после родов. Чтобы снизить вероятность её появления, полезно регулярно принимать фолиевую кислоту, не находиться на солнце без защитных средств и с осторожностью использовать средства для ухода за кожей.;;;
Из-за влияния гормонов, вырабатываемых во время беременности, и усиления кровообращения вы можете ощущать увеличение и наполненность груди. Если это доставляет вам дискомфорт, отдавайте предпочтение поддерживающим бюстгальтерам или моделям большего размера. Во время беременности гормональные изменения могут сделать вас более восприимчивой к стрессу. Любимые занятия помогут снизить напряжение как физически, так и эмоционально.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Яркие и порой тревожные сны в этот период — нормальное явление. Перед сном вам могут помочь расслабляющая музыка или тёплый душ. Чтобы предотвратить боль в пояснице, не оставайтесь надолго в одном положении. Для здоровья зубов продолжайте употреблять продукты, богатые кальцием. Каждый день прислушивайтесь к своему телу и не переутомляйтесь.') WHERE id = 'a614becc-2914-4d7d-98c2-e4eb413c2293';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В эти дни пальчики малыша приобретают всё более чёткую форму, и уже начинают формироваться даже отпечатки пальцев. Отпечатки пальцев — это уникальные для каждого человека узоры, образованные складками кожи на кончиках пальцев и в области последних фаланг. Кисти и стопы вашего малыша быстро окостеневают, а локти начинают формироваться. Несмотря на это, у него всё ещё есть маленький «хвостик». В течение следующих нескольких недель он уменьшится и исчезнет. Пока хвостик сохраняется, ваш малыш называется эмбрионом. После его полного исчезновения на 11-й и 12-й неделе начнётся переход к стадии плода.'), baby_message_ru = COALESCE(baby_message_ru, 'Сегодня мы завершаем 8-ю неделю! 🎉 Я уже официально готовлюсь перейти из стадии «эмбриона» в стадию «плода». Все мои важные органы — сердце, мозг, желудок, лёгкие — уже находятся на своих местах. Теперь мне остаётся расти, развиваться и становиться всё прекраснее. Самый сложный и рискованный период беременности уже позади, мама. Вы так хорошо меня оберегали, и я очень вам благодарен!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Красная фасоль'), body_changes_ru = COALESCE(body_changes_ru, 'Сейчас, когда вы приближаетесь к завершению первого триместра беременности, ваше сердце начинает перекачивать больше крови по сосудам. Во время беременности частота сердцебиения увеличивается по сравнению с обычной. Поэтому естественным образом возрастает и количество крови, которое сердце должно перекачивать за 1 минуту. К 3-му триместру беременности объём перекачиваемой крови достигает максимального уровня.;;;
Одним из наиболее распространённых изменений кожи во время беременности является изменение пигментации. Обычно у женщин со смуглой кожей это проявляется небольшим потемнением сосков, области половых органов, кожи вокруг пупка и общего тона кожи.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В честь успешного завершения второго месяца сделайте себе небольшой подарок и отдохните. Поскольку объём крови увеличивается, уделяйте особое внимание продуктам, богатым железом и белком (чечевица, красное мясо, яйца). Если у вас болит поясница, попробуйте во время сна класть между ног подушку — это может принести облегчение. На следующей неделе нас ждут первые шаги третьего месяца. Если вы чувствуете эмоциональное напряжение, сделайте глубокий вдох и поговорите со своим малышом.') WHERE id = 'fb6fb148-4851-4c47-b527-c43ee9bf7d0f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ткань мозга продолжает развиваться чрезвычайно быстро. Область мозга, регулирующая движения мышц, начинает функционировать. Это значит, что ваш малыш уже может двигаться. Однако эти небольшие движения, похожие на подёргивания, вы пока не можете почувствовать.;;;
Уже на этом этапе малыш способен реагировать на внешние раздражители. Развивающаяся нервная система начинает устанавливать связь с мышцами. Как и во всём теле, в области лица постепенно формируются кости и хрящи, особенно заметными становятся ротовая полость и нёбо.'), baby_message_ru = COALESCE(baby_message_ru, 'Я икаю! 🤭 Вы не поверите, но моя диафрагма (дыхательная мышца) формируется, и я начинаю икать. Вы пока этого не чувствуете, потому что я ещё совсем маленький и икаю беззвучно. Так я тренируюсь дышать в будущем. Идёт подготовка к жизни! Пока я расту в вашем животе, я осваиваю всё больше новых навыков.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Красная фасоль'), body_changes_ru = COALESCE(body_changes_ru, 'У вас могут возникать постоянная сонливость, головная боль, спазмы в желудке и слабость. Это связано с высоким уровнем гормонов эстрогена и прогестерона в крови во время беременности. Боль в паховой области на этих неделях встречается у многих будущих мам и чаще всего не представляет опасности.;;;
Не беспокойтесь из-за увеличения количества выделений. Матка, увеличившаяся в 2 раза, производит больше секрета, чтобы обеспечить малышу здоровую среду.;;;
Сейчас вашему организму требуется больше воды, чем обычно. Чтобы восполнить эту потребность, выпивайте не менее 10 стаканов воды в день.;;;
Сильное желание съесть определённые продукты обычно называют пищевыми пристрастиями беременных. Их точные причины до конца не известны, однако считается, что определённую роль играют гормональные изменения во время беременности и связанные с ними колебания уровня сахара в крови. К 12-й неделе такие пристрастия обычно начинают ослабевать. Если они сохраняются дольше, это часто связано с психологическими факторами. Пищевые пристрастия не считаются вредными, за исключением случаев, когда возникает выраженное отвращение к необходимым организму продуктам и будущая мама не получает их в достаточном количестве.'), daily_tip_ru = COALESCE(daily_tip_ru, 'На этой неделе вы можете чувствовать себя более уставшей, чем обычно. В течение дня делайте частые, но короткие перерывы для отдыха. Ваш организм расходует много энергии на быстрый рост малыша, поэтому добавьте в рацион больше белковых продуктов (чечевица, орехи, яйца). При повышенной чувствительности дёсен уделяйте особое внимание гигиене полости рта. Если вас всё ещё беспокоит токсикоз, старайтесь есть небольшими порциями в течение дня.') WHERE id = 'bef0eb9c-a062-4017-9195-e0a1a182972b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Глаза, которые выглядели как маленькие чёрные точки по обеим сторонам головы, стали полностью заметны благодаря увеличению выработки пигмента. Веки вашего малыша начали формироваться, но ещё долго будут оставаться закрытыми.;;;
Ваш малыш формируется и растёт с невероятной скоростью. Для получения энергии, необходимой клеткам, ему нужна глюкоза. Ваш малыш, которого пока называют эмбрионом, получает её через плаценту, сформировавшуюся в матке. Питательные вещества из съеденной вами пищи поступают к малышу с кровью через плаценту.;;;
Кишечник вашего малыша быстро удлиняется, поэтому находится в свёрнутом состоянии и будет продолжать изгибаться до завершения своего развития. Толстая кишка удлиняется медленнее, поэтому имеет более прямую форму. Кишечнику потребуется ещё немного времени, чтобы полностью занять своё место в брюшной полости.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня формируются веки! 👁️ Чтобы защищать мои глаза, формируются веки, и вскоре они соединятся и закроются. Примерно до 27-й недели я не буду открывать глаза. Сейчас я сосредоточен на своём внутреннем мире и перехожу в режим долгого сна. Но не волнуйтесь: даже с закрытыми глазами я смогу чувствовать свет. Я буду представлять вас в своих мечтах.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Красная фасоль'), body_changes_ru = COALESCE(body_changes_ru, 'До беременности ваша матка весила около 60 грамм, а теперь увеличилась вдвое. Поскольку растущая матка давит на мочевой пузырь, вы можете чаще ходить в туалет. По мере развития беременности и подъёма матки вверх давление на мочевой пузырь уменьшится, и частые позывы к мочеиспусканию станут менее выраженными.;;;
Матка, внутри которой быстро растёт ваш малыш, является главным фактором увеличения живота во время беременности. У вас всё ещё могут сохраняться ранние признаки беременности, такие как чувствительность груди и боли в паховой области. Вы можете заметить потемнение кожи груди и коричневые точки вокруг сосков. Эти образования, называемые бугорками Монтгомери, представляют собой небольшие сальные железы, расположенные вокруг соска. Они вырабатывают естественные масла, которые поддерживают pH-баланс кожи и защищают соски от инфекций.;;;
На этой неделе объём вашей крови уже на 12% больше, чем до беременности. В процессе адаптации организм может реагировать на повышение артериального давления, например носовыми кровотечениями. Если носовые кровотечения повторяются часто, рекомендуется проконсультироваться с врачом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить изжогу, не ложитесь сразу после еды и заканчивайте ужин как минимум за 2-3 часа до сна. Если ваше сердцебиение немного участилось, не волнуйтесь: так организм перекачивает больше крови для малыша. Поскольку потребность в омега-3 возросла, после консультации с врачом вы можете добавить в рацион грецкие орехи или рыбу. Медитация с глубоким дыханием в течение дня поможет успокоить нервную систему и вашу, и малыша.') WHERE id = 'b8a881d9-b2c4-4857-81a9-360b7ca73418';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя наружные половые органы ещё не развились, клетки уже начали формироваться в яичники или яички. В руках вашего малыша начала образовываться и функционировать нервная ткань. Одновременно продолжается активное развитие спинного мозга. Хотя скелетная ткань пока состоит из хряща, в течение следующих нескольких недель она полностью окостенеет.;;;
Маленькое сердце вашего малыша сокращается в среднем 150-160 раз в минуту, обеспечивая кровообращение. Начиная с этой недели у малыша формируются сердечные клапаны.'), baby_message_ru = COALESCE(baby_message_ru, 'Я девочка или мальчик? 🩷💙 Внутри меня уже формируются половые органы — яичники или яички. Но внешне это пока незаметно. Врачи ещё не могут определить пол — это мой маленький секрет. Кого вы хотите: девочку или мальчика? Главное, чтобы я был здоров и оставался вашим малышом. В любом случае я буду очень вас любить!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Оливка'), body_changes_ru = COALESCE(body_changes_ru, 'По мере роста малыша матка начинает растягиваться, что может вызывать схваткообразные боли. Такие боли считаются ожидаемыми и нормальными. Если спазмы возникают очень часто или долго не проходят, рекомендуется сообщить об этом врачу. Из-за очень высокого уровня гормонов в крови тошнота и рвота считаются нормальными. По этой причине вы можете терять вес. Однако если потеря веса значительная, проконсультируйтесь с врачом: он может порекомендовать вам дополнительные пищевые добавки. Одежда уже может становиться тесной. Следует отдавать предпочтение вещам, которые не сдавливают живот.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить зуд и ощущение стянутости кожи, начните использовать увлажняющие средства с натуральным составом или миндальное масло. Следите за балансом кальция и витамина D в рационе (молочные продукты, яичный желток), чтобы кости малыша были крепкими. Чтобы улучшить качество ночного сна, проветривайте комнату перед сном. Каждый день выделяйте несколько минут для общения с малышом — это ещё больше укрепит вашу связь.') WHERE id = '1e725a51-c2e7-489a-9924-d2713767d7e6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'У вашего малыша началось развитие языка и губ. Язык и расположенные на нём вкусовые рецепторы формируются из многослойных плоских клеток. Вкусовые рецепторы находятся в сосочках на поверхности языка. Благодаря им мы различаем горький, кислый, сладкий и солёный вкус пищи. Вскоре слюнные железы, развивающиеся во рту, начнут попарно располагаться в разных участках ротовой полости.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой "дом" меняется, Anacan! 🏠 "Желточный мешок", который до сих пор обеспечивал меня питанием, постепенно уменьшается, потому что моя удивительная плацента принимает его обязанности. Плацента — это мост между вами и мной. Она будет защищать и питать меня, а также обеспечивать кислородом. Наша связь стала ещё сильнее и крепче. И всё это благодаря вам!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Оливка'), body_changes_ru = COALESCE(body_changes_ru, 'Задача щитовидной железы — синтезировать, накапливать и выделять гормоны в кровоток. Йод, необходимый для образования этих гормонов, поступает в организм с солью, питьевой водой или пищей. Он влияет на все клетки организма и играет важную роль в регулировании его функций. Если уровень гормонов щитовидной железы в крови снижен, работа организма замедляется. Это состояние называется гипотиреозом. Если уровень этих гормонов в крови повышен, организм начинает работать быстрее. Это состояние называется гипертиреозом. Количество гормонов, вырабатываемых щитовидной железой, регулируется другой железой — гипофизом, а также областью мозга, называемой гипоталамусом. С начала беременности и до родов в системах органов происходят структурные и функциональные изменения. Из-за изменений гормонального фона во время беременности у некоторых женщин может развиться гипотиреоз. Поскольку это состояние может привести к нежелательным последствиям для матери и малыша, важно своевременно его выявить и начать лечение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить вздутие живота и проблемы с пищеварением, тщательно пережёвывайте пищу и избегайте газированных напитков. Если вы замечаете отёки ног, несколько раз в течение дня поднимайте ноги повыше и отдыхайте по 10 минут. Ограничьте потребление соли, но не исключайте её полностью. Поскольку вы приближаетесь к концу первого триместра, особенно берегите своё эмоциональное состояние: избегать стресса очень важно для нервной системы малыша.') WHERE id = 'a0486bb7-3fd0-4a52-8340-97fc8cbad570';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе органы вашего малыша продолжают активно развиваться, а селезёнка и печень начинают занимать свои места в брюшной полости. Селезёнка, выполняющая функцию вторичного органа иммунной системы, также способствует выведению из организма жёлто-оранжевого пигмента билирубина, который образуется при распаде гемоглобина — белка, переносящего кислород от органов дыхания к тканям, а углекислый газ — от тканей к органам дыхания.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой хвостик исчез! 🐇 Помнишь, я рассказывал тебе, что у меня есть маленький хвостик? Теперь его больше нет! Моя спинка стала прямой и гладкой, и у меня уже настоящий человеческий позвоночник. Я всё больше становлюсь похожим на тебя, Anacan. Я уже не маленький морской конёк, а твой маленький человечек. Эта перемена делает меня очень счастливым, а тебя?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Виноград'), body_changes_ru = COALESCE(body_changes_ru, 'Матка продолжает увеличиваться, но живот пока не заметен, поскольку она всё ещё находится за костями таза. Однако вы уже можете ощущать тяжесть. Из-за усилившегося давления на мочевой пузырь вам по-прежнему часто хочется в туалет. Также возможны небольшие колебания артериального давления, из-за которых при резком подъёме может возникать головокружение. ;;;
Вес матки, составляющий в начале беременности 60-70 грамм, к её завершению превышает 1000 грамм. Иными словами, матка, которая до беременности была размером с персик, к концу беременности становится размером с арбуз. Изначально она меньше кулака, но по мере роста малыша начинает растягиваться изнутри, освобождая для него место, и увеличивается настолько, что может выдерживать вес до 5 килограмм. Хотя скорость роста живота зависит от строения мышц брюшного пресса, до 12-й недели он увеличивается относительно медленно, а в последнем триместре — очень быстро. У женщин, ожидающих второго ребёнка, живот становится заметным раньше, чем при первой беременности, поскольку их мышцы уже растягивались. После 9 месяцев беременности, в течение которых матка многократно увеличивается, она возвращается к прежним размерам за 2 месяца после родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку в этот период объём крови увеличивается, постарайтесь включать в рацион больше продуктов, богатых железом (чечевицу, зелёные листовые овощи, красное мясо). Если вы ощущаете зуд или сухость кожи живота, мягко массируйте её с увлажняющим кремом или натуральным маслом. Не забывайте пить воду в течение дня: она помогает пищеварению и важна для обновления околоплодных вод. Короткие прогулки без чрезмерной нагрузки помогут улучшить настроение.') WHERE id = 'efd814e8-abbf-4037-81a4-db63af40ea3e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В ушах вашего малыша формируются особые каналы, которые не связаны со слухом, а помогают поддерживать равновесие тела. Благодаря этой системе в будущем он сможет двигаться, не падая. Одновременно уши формируются как единый механизм: наружное ухо улавливает звук, среднее усиливает его, а внутреннее передаёт сигнал в мозг.;;;
Мозг вашего малыша сейчас активно генерирует электрические волны. Эти волны — не просто побочный продукт, а основной «путь», по которому различные области мозга общаются друг с другом и обмениваются информацией.'), baby_message_ru = COALESCE(baby_message_ru, 'Я умею сгибать локти! 💪 Мои руки уже не похожи на прямые палочки. Локтевые суставы сформировались, и теперь я могу прижимать руки к груди. Словно обнимаю себя. Однажды я обниму этими руками тебя. Мои движения становятся всё сложнее: теперь я не просто плаваю, но и учусь управлять своим телом.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Виноград'), body_changes_ru = COALESCE(body_changes_ru, 'Одним из первых признаков, которые обычно связывают с беременностью, считается тяга к определённым продуктам. Она наблюдается у многих беременных и проявляется сильным желанием съесть какую-либо пищу. При рационе с преобладанием белков может возникать тяга к сладостям, богатым углеводами, а при питании с преобладанием углеводов — к продуктам, богатым белком. Желание есть фрукты может указывать на потребность в витаминах, а тяга к молочным продуктам — на потребность в кальции. На разных сроках беременности может хотеться разных продуктов. Когда потребность в калориях возрастает, особенно привлекательными становятся высококалорийные продукты, например сладости и шоколад. Также известно, что при дефиците некоторых витаминов тяга к шоколаду может усиливаться. В этот период полезно употреблять разные продукты в умеренных количествах, но не забывайте, что избыток калорий может привести к набору лишнего веса.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уровень сахара в крови не снижался в течение дня, продолжайте есть небольшими порциями, но часто. Всегда держите при себе несколько грецких орехов или миндальных орехов. Если вас беспокоит заложенность носа, может помочь увлажнение воздуха в комнате. Каждый день старайтесь хотя бы 10-15 минут глубоко дышать в спокойной обстановке, укрепляя связь с малышом. Помните, что ваше спокойствие — один из важнейших факторов его развития.') WHERE id = 'a019329d-4564-4a4c-a50f-391f0feef37e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Маленькие пальчики вашего малыша продолжают быстро расти. Сейчас особенно важный период для формирования рук и ног. Вместе с пальчиками удлинились руки и ноги, а локти начали сгибаться. Нервная система уже достаточно развита, чтобы малыш мог активно двигать руками и ногами и реагировать на раздражители. Если повезёт, во время ультразвукового исследования вы сможете увидеть, как малыш двигается! Он уже начинает приобретать человеческий облик. Хотя голова пока больше по отношению к телу, органы продолжают быстро расти, развиваться и занимать свои правильные места.;;;
Начиная с этой недели у малыша формируются репродуктивные органы, однако внешние половые органы пока не имеют заметных половых признаков. Поэтому, если вам интересно узнать пол малыша, придётся подождать ещё несколько недель.'), baby_message_ru = COALESCE(baby_message_ru, 'ПОЗДРАВЛЯЮ, ANACAN! Я ВЫПУСКНИК! 🎓 Сегодня для меня исторический день. Я больше не «Эмбрион», теперь я официально называюсь «Плод»! Это означает, что все мои органы уже сформировались. Теперь мне остаётся только расти, набирать вес и становиться сильнее. Самый опасный период позади! Мы справились с этим вместе. Ты мой герой!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Виноград'), body_changes_ru = COALESCE(body_changes_ru, 'В первые три месяца беременности дополнительные калории не требуются, однако важно правильно питаться. Полноценное питание в этот период имеет большое значение для интеллектуального развития малыша. Чтобы обеспечить его рост и умственное развитие, необходимо получать все нужные питательные вещества. Единого понятия «правильного веса» или идеальной прибавки, подходящей всем беременным, не существует. Допустимая прибавка зависит от веса женщины в начале беременности и индивидуальна для каждой будущей мамы. Рекомендуемую прибавку рассчитывают с учётом индекса массы тела до беременности, то есть соотношения веса и роста. Для женщины с нормальным весом дополнительная потребность в энергии во время беременности составляет в среднем 300 калорий в день. 300 калорий — это примерно 3 банана, 5 яблок, 100 грамм блюда из чечевицы, 1 миска жирного йогурта или 3-4 ломтика хлеба. Избыток калорий, потребляемых в течение дня, будет откладываться в виде жира и может помешать вам придерживаться рекомендуемой прибавки веса.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку вы приближаетесь к концу первого триместра, постарайтесь бережнее относиться к себе. Из-за ускоренного обмена веществ вы можете чаще испытывать голод, поэтому держите под рукой полезные перекусы. Если вас беспокоит боль в пояснице, сон на боку с подушкой между коленями поможет снизить нагрузку на позвоночник. При переходе к 10-й неделе не забудьте обсудить с врачом первые скрининговые исследования.') WHERE id = '65677248-c635-4f55-8483-617e735f69ca';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Мозг вашего малыша начинает формировать извилины, чтобы вместить больше информации на небольшой площади. Этот верхний слой, называемый «серым веществом», словно оболочка покрывает мозг и по мере развития становится всё более рельефным. Эта область считается центром управления мозгом.;;;
В то же время сердце вашего малыша уже полностью сформировалось и состоит из 4 камер. Клапаны внутри сердца выполняют роль своеобразных односторонних дверей. При каждом сокращении сердца и перекачивании крови они открываются, обеспечивая её движение только вперёд и предотвращая обратный ток.'), baby_message_ru = COALESCE(baby_message_ru, 'Идёт подготовка к появлению моих зубов! 🦷 Во рту у меня пока нет ни одного зуба, но под дёснами уже формируются маленькие зубные зачатки. Это основа моих будущих молочных зубов. Я уже планирую тот день, когда улыбнусь вам. Вы тоже хорошо заботьтесь о своих зубах, Anacan, ведь вы делитесь со мной запасами кальция.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Фундук'), body_changes_ru = COALESCE(body_changes_ru, 'Теперь, когда позади уже 2 месяца беременности, у вас могут появиться некоторые жалобы. Одна из них — недержание мочи. Это непроизвольное выделение мочи, которое человек не может контролировать. Во время беременности такое состояние встречается часто. В первые 3 месяца оно возникает из-за давления растущей матки на расположенный непосредственно под ней мочевой пузырь. Кроме того, поскольку мочевой пузырь может опорожняться не полностью, возможны частые позывы к мочеиспусканию. Недержание мочи в последнем триместре связано с давлением малыша на мочевой пузырь и, по оценкам, наблюдается примерно у 35% беременных. Это физиологическое состояние, которое обычно проходит после завершения беременности. Не откладывайте посещение туалета, избегайте резких движений, повышающих внутрибрюшное давление, и не поднимайте тяжести — эти меры помогут уменьшить проявления недержания.'), daily_tip_ru = COALESCE(daily_tip_ru, 'На этой неделе вы можете почувствовать себя немного бодрее, поскольку уровень гормонов начинает стабилизироваться. Так как чувствительность дёсен может сохраняться, отдавайте предпочтение продуктам, богатым кальцием. Если у вас появилась боль в пояснице, следите за осанкой и не стойте слишком долго. Поскольку вы приближаетесь к концу первого триместра, сейчас самое время проконсультироваться с врачом по поводу «Двойного теста» (скрининга).') WHERE id = 'c0cc19e3-1bf2-4736-b8f0-41d3ab04d6c8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Черты лица вашего малыша становятся всё более отчётливыми: рот, нос и уши постепенно занимают свои естественные места. На 9-й неделе развитие глаз значительно продвинулось. Внутри глаза формируется тонкий слой сетчатки, состоящий из миллионов клеток и обеспечивающий зрение, а расположенные в нём сосуды начинают снабжать эти клетки питательными веществами.;;;
Одновременно завершается развитие радужки — цветной части глаза. Сейчас эта структура имеет голубоватый оттенок. Именно эта первоначальная окраска объясняет, почему в первые месяцы жизни глаза новорождённых обычно кажутся голубыми.'), baby_message_ru = COALESCE(baby_message_ru, 'Моё сердце бьётся вдвое быстрее вашего! 💓 Примерно 170 ударов в минуту! Если вы пойдёте к врачу, то сможете услышать меня с помощью доплеровского аппарата. Этот звук «тук-тук-тук» похож на стук копыт бегущей лошади. Он говорит вам: «Я здесь, я сильный малыш!» Мой ритм — музыка вашей жизни.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Фундук'), body_changes_ru = COALESCE(body_changes_ru, 'В животе могут появиться ощущения, похожие на «пузырьки газа», но не путайте их с движениями малыша — для них ещё рано. Это всего лишь работа кишечника. Из-за прогестерона пищеварительная система работает медленнее, что вызывает вздутие живота. ;;;
Во время беременности в положении лёжа на спине артериальное давление может снижаться до минимальных значений. При этом частота сердечных сокращений может увеличиваться, а кровоснабжение почек — сокращаться почти наполовину. В положении лёжа нижняя полая вена, по которой кровь поступает от нижней части тела к сердцу, может сдавливаться под тяжестью малыша. Это способно привести к синдрому сдавления нижней полой вены — состоянию, связанному с нарушением кровотока. Таким образом, сдавление нижней полой вены весом малыша в положении лёжа может способствовать развитию этого состояния. Поэтому врачи не рекомендуют будущим мамам, особенно в последнем триместре, долго лежать на спине.'), daily_tip_ru = COALESCE(daily_tip_ru, 'В период активного развития костей уделяйте особое внимание поступлению кальция и магния (миндаль, грецкие орехи, молочные продукты). При головной боли совершайте короткие прогулки на свежем воздухе и пейте много воды. Хотя переходить на одежду для беременных ещё рано, более удобные и эластичные брюки помогут вам чувствовать себя комфортнее. Ограждайте себя от стресса: спокойная музыка положительно повлияет и на вас, и на малыша.') WHERE id = 'd416ae4b-bb0c-425b-b304-d18dd9ac3813';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Печень, желчный пузырь, селезёнка и почки вашего малыша продолжают быстро расти. Завершилось соединение ротовой полости с глоткой. На этой неделе полости рта и носа полностью отделяются друг от друга, а соединение с глоткой завершается. Язык находится на стадии формирования. Если на этом важном этапе слияния структур лица развитие нарушается, иногда могут возникать расщелины губы или нёба. Они могут иметь разные формы — от небольшой выемки до выраженной расщелины губы.'), baby_message_ru = COALESCE(baby_message_ru, 'У меня формируются отпечатки пальцев! 👆 Появляется моя уникальная особенность, которая принадлежит только мне и не повторяется ни у кого в мире. На кончиках моих пальцев прорисовываются особые узоры. Эти отпечатки — знак моей неповторимости. Я — ваше уникальное чудо, Anacan. Вы видите, насколько совершенно создана каждая, даже самая маленькая деталь?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Фундук'), body_changes_ru = COALESCE(body_changes_ru, 'Вы можете почувствовать небольшой прилив энергии, поскольку плацента почти полностью берёт на себя выработку гормонов. Это означает, что зависимость от «жёлтого тела» уменьшается. Однако чувствительность и увеличение груди сохраняются. Иногда из сосков может выделяться желтоватая жидкость (молозиво) — не пугайтесь, это нормально.;;;
Повышение уровня некоторых гормонов во время беременности может нарушить pH-баланс влагалища. В результате защитный барьер, называемый влагалищной флорой, ослабевает. Это приводит к увеличению количества выделений из влагалища во время беременности. Такое физиологическое увеличение выделений не требует лечения. Достаточно тщательнее соблюдать общие правила гигиены. Если выделения изменили цвет или приобрели неприятный запах, будущей маме следует обратиться к врачу.;;;
Грибковая инфекция во время беременности возникает из-за снижения сопротивляемости организма и количества полезных бактерий во влагалищной флоре. Она проявляется белыми творожистыми выделениями, сильным зудом и жжением. Её можно лечить безопасными свечами и кремами, назначенными врачом. В качестве профилактики беременным также рекомендуется носить хлопковое нижнее бельё, стирать его не порошком, а мылом и проглаживать перед использованием.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Полюбите воду! Плавание — один из самых подходящих видов физической активности во время беременности. Выталкивающая сила воды снижает нагрузку на поясницу и дарит ощущение лёгкости. Кроме того, плавание помогает уменьшить отёчность.') WHERE id = '827fd4de-2f71-405f-8929-c0848b39d48e';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя зубы малыша появятся примерно через 6 месяцев после рождения, их основа закладывается уже сейчас. На особой утолщённой ткани, образующейся в полости рта, начинают формироваться небольшие бугорки — зачатки зубов.;;;
Всего формируется 20 зачатков молочных зубов — по 10 на верхней и нижней челюсти. Этот процесс происходит в определённой последовательности: сначала закладываются передние зубы, затем боковые и, наконец, задние. Интересно, что эта же ткань в будущем создаст основу для развития постоянных зубов, которые заменят молочные.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чемпион по плаванию! 🏊‍♂️ Я постоянно двигаюсь в воде. Пинаюсь, поворачиваюсь и делаю сальто. Вы пока этого не чувствуете, потому что окружающая меня вода, словно подушка, смягчает толчки. Но знайте: внутри проходит настоящая олимпиада. Я тренируюсь, чтобы стать сильным к нашей встрече.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Фундук'), body_changes_ru = COALESCE(body_changes_ru, 'На этой неделе, когда вы вступаете в 3-й месяц беременности, вы, вероятно, уже ощущаете набухание груди. Первые изменения в тканях груди, необходимые для подготовки к грудному вскармливанию, начинаются в этот период беременности, однако выработка молока запускается только ближе к её середине. Подготовку к выработке грудного молока во время беременности регулирует множество гормонов. Они играют важную роль в перестройке желёз и молочных протоков, обеспечивающих выработку и выделение молока. Из-за увеличения количества желёз и молочных протоков объём груди во время беременности быстро возрастает, и к её концу вес груди может достигать примерно 1 килограмма. Гормон пролактин, выделяемый гипофизом, который расположен в нижней части головного мозга, взаимодействует с особыми клетками тканей груди и играет ключевую роль в выработке молока. Другой гормон гипофиза — окситоцин — начинает особенно активно выделяться, когда малыш прикладывается к груди. Именно этот гормон обеспечивает продвижение молока по протокам и его выделение через сосок.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы избежать головокружения, не делайте резких движений. Особенно важно, вставая с кровати, сначала посидеть несколько секунд. Чтобы облегчить работу пищеварительной системы, ешьте продукты, богатые клетчаткой (сухофрукты, овсянку, овощи), и пейте достаточно воды. Если к вам вернулась энергия, лёгкая йога для беременных или дыхательные упражнения будут прекрасны для вашего самочувствия и благополучия малыша.') WHERE id = '12d3b899-0764-4ab2-902c-2efe92103462';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже достаточно развит, чтобы открывать и закрывать рот, поворачивать голову и менять положение тела. Более того, малыш вырос настолько, что при удачном положении вы сможете увидеть эти движения во время ультразвукового исследования!;;;
Между 7-й и 9-й неделями беременности малыш двигается всем телом, совершая резкие движения, похожие на подпрыгивания. Благодаря развитию нейронов спинного мозга с этой недели руки, ноги и туловище могут двигаться по отдельности, независимо друг от друга. Ещё через 2-3 недели малыш сможет пинаться, хвататься за ноги, выполнять движения, напоминающие езду на велосипеде, и поворачиваться.;;;
Кроме того, в этот период удлиняются руки и ноги, начинают формироваться пальцы ног, а локти и запястья становятся хорошо заметными.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с курагу! 🍓 Я расту и меняюсь каждый день. Мои уши постепенно перемещаются вверх по бокам головы, занимая правильное положение. Глаза пока закрыты, но сетчатка уже способна различать свет. Когда вы выйдете на солнце, я смогу почувствовать его тепло и яркость.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Курага'), body_changes_ru = COALESCE(body_changes_ru, 'По мере роста матка начинает подниматься выше костей таза. Благодаря этому давление на мочевой пузырь может немного уменьшиться. Вы можете ощущать уплотнение в нижней части живота.;;;
Считается, что во время беременности среднее значение верхней границы уровня гемоглобина к моменту родов составляет 11-12%. Если показатель ниже, может потребоваться дополнительный приём железа. Железо, которое называют питанием для мозга, является одним из важнейших элементов здорового рациона при беременности и необходимо для когнитивного развития малыша. Достаточное количество здоровых эритроцитов снижает риск анемии. Анемия, которую иногда связывают с дефицитом железа, вызывает усталость, истощение и слабость. Чтобы восполнить потребность в железе во время беременности, полезно употреблять красное мясо, шпинат, брокколи, зелёную чечевицу, листовую капусту, нут и фасоль.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Уделяйте внимание интимной гигиене, но будьте осторожны при использовании мыла или гелей для душа. Выбирайте средства, которые не нарушают естественный pH-баланс. Если вы пользуетесь ежедневными прокладками, меняйте их чаще.') WHERE id = '56fa6e29-fd7a-4a03-984e-0590d982556b';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В этот период, когда скелет и костная ткань активно развиваются, достаточное поступление витамина D особенно важно. Он помогает организму усваивать кальций и фосфор, способствуя здоровому формированию костей малыша. Укрепление костей — не единственная функция витамина D: он также поддерживает иммунитет, регулирует работу нервной системы и нормализует сердцебиение. Его дефицит может привести как к задержке развития малыша, так и к мышечной слабости и утомляемости у матери. Главный источник витамина D — солнечный свет. Кроме того, он содержится в рыбьем жире, креветках, устрицах, молоке и молочных продуктах, картофеле и зерновых продуктах для завтрака.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои почки работают! 🚽 Да, это может звучать немного странно, но я уже выделяю мочу. Я заглатываю амниотическую жидкость, мои почки её фильтруют и снова выделяют обратно в окружающую воду. Этот круговорот очень важен для правильной работы моей пищеварительной и выделительной систем. Я — самоочищающаяся система!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Курага'), body_changes_ru = COALESCE(body_changes_ru, 'Когда хвостик начинает исчезать, для малыша наступает новый этап. Теперь малыш, которого раньше называли эмбрионом, перешёл в стадию плода и будет называться плодом до момента рождения. Эмбриональный период — это время формирования систем органов. Плодный период — этап, в течение которого сформировавшиеся органы, ткани и структуры растут и развиваются. Сейчас, когда вы вступаете в последний месяц первого триместра, у вас всё ещё могут сохраняться неприятные симптомы беременности. Профилактика депрессии во время беременности важнее её последующего лечения. В этот период вам будет полезно заниматься любимыми делами, проводить время с близкими людьми и получать поддержку супруга и родных.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Из-за увеличения объёма крови вы можете часто чувствовать усталость; 15-минутный «энергетический сон» в течение дня поможет восстановить силы. Следите за достаточным поступлением магния и кальция, чтобы избежать внезапных ночных судорог в ногах. Ежедневно выпивайте не менее 2 литров воды. Если резкие запахи всё ещё вызывают у вас дискомфорт, чай с мятой или вода с лимоном могут успокоить желудок.') WHERE id = '17780e60-9b95-4f39-9e38-8371589b8dad';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Почки вашего малыша уже начали работать. Эти органы, которые ещё на 4-й неделе представляли собой небольшую группу клеток, теперь развились настолько, что производят мочу и выделяют её в амниотическую жидкость.;;;
В течение следующих недель расположенные в брюшной полости почки отдаляются друг от друга и поворачиваются под углом 90 градусов, принимая окончательную форму. Начиная с этой недели формируется особая почечная артерия, отходящая от аорты. Она обеспечивает прямое кровоснабжение почек и позволяет им работать в полную силу.'), baby_message_ru = COALESCE(baby_message_ru, '10 НЕДЕЛЬ! ДВУЗНАЧНОЕ ЧИСЛО В КАЛЕНДАРЕ! 🔟 Anacan, у нас уже 10-я неделя. Я официально становлюсь большим малышом. Сейчас я размером со сливу. Самые важные этапы развития уже позади. Теперь мне осталось лишь набирать вес, расти и готовиться к встрече с вами. Мы прошли уже почти четверть пути! Я горжусь вами.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Курага'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности полноценное и сбалансированное питание, а также получение всех необходимых витаминов имеют большое значение как для вашего здоровья, так и для здорового развития малыша. Например, для восполнения суточной потребности в витамине C, кальции и фолиевой кислоте полезно есть брокколи, для получения кальция — молоко и молочные продукты, калия — бананы, а омега-3 и омега-6 — необжаренные орехи. Важно помнить, что ежедневное употребление достаточного количества молока и молочных продуктов очень важно для костной системы мамы и малыша. Кроме того, для поддержания стабильного уровня сахара в крови полезно разделить дневной рацион на 5-6 небольших приёмов пищи вместо нескольких обильных. Во время беременности употребление воды не менее важно, чем питание. Вода активно помогает справиться с усиливающимися во время беременности запорами, предотвратить сухость кожи и появление растяжек, снизить риск инфекций мочевыводящих путей, а также поддерживать объём околоплодных вод (амниотической жидкости), необходимых для здоровья малыша. Поэтому в течение дня следует выпивать 2,5-3 литра воды.'), daily_tip_ru = COALESCE(daily_tip_ru, 'До второго триместра остался всего один шаг — порадуйте себя и отдохните. Включайте в рацион продукты, сочетающие железо и витамин C, например мясо и большую порцию зелёного салата, чтобы предотвратить анемию. Если вы всё ещё чувствуете усталость, короткий дневной сон поможет восстановить силы. На следующей неделе нас ждёт один из самых интересных этапов развития.') WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Кожа — крупнейший орган нашего тела — начинает формироваться в виде трёх слоёв ещё на третьей неделе развития. Самый наружный из этих слоёв образует как саму кожу, так и её производные — волосы и ногти.;;;
Начиная с 9-й недели на теле вашего малыша появляются первые волосяные фолликулы. Эти тонкие волоски, называемые лануго, сначала возникают в области верхней губы, бровей и подбородка. Пока они очень тонкие, поэтому на УЗИ их можно различить лишь ближе к 20-й неделе. Эти волоски защищают малыша в утробе матери и обычно выпадают незадолго до родов. Одновременно ногти на руках и ногах малыша начинают понемногу расти. Ногти, состоящие из прочного слоя кератина, важны не только для внешнего вида: они служат защитным щитом, предохраняя кончики пальцев от травм и повышая их чувствительность.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя голова размером с половину моего тела! 🤯 Anacan, возможно, я выгляжу забавно, но всё потому, что готовлюсь стать гением. Мой мозг растёт так быстро, что голова пока кажется очень большой по сравнению с телом. Но не волнуйтесь: со временем моё тело тоже вырастет и догонит её. Сейчас я похож на маленького учёного. С нетерпением жду тех дней, когда смогу с вами разговаривать.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Курага'), body_changes_ru = COALESCE(body_changes_ru, 'Ближе к концу первого триместра тошнота начинает уменьшаться. Поэтому вы можете почувствовать себя энергичнее и бодрее. С этой недели, когда начинается 3-й месяц, ваш организм уже полностью адаптировался к беременности. Из-за увеличения объёма крови и задержки жидкости могут появиться отёки. Пересмотр пищевых привычек, сокращение количества соли и повышение физической активности помогут уменьшить отёки до уровня, не вызывающего дискомфорта.;;;
Если тошнота всё ещё сохраняется, справиться с ней может помочь частое дробное питание небольшими порциями с преобладанием нежирной и более плотной пищи.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку энергия постепенно возвращается, вы можете начать совершать лёгкие пешие прогулки. Из-за ускорения обмена веществ не забывайте пить достаточно воды — не менее 2-2.5 литра в день. Продолжайте использовать увлажняющие средства с натуральным составом при изменениях кожи и появлении растяжек. Каждый день уделяйте себе 10 минут, чтобы подумать о своих мечтах о будущем, — это благотворно повлияет на вас обоих.') WHERE id = '59be5b5e-6a03-4140-bbff-b41541c8484d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя голова вашего малыша, чьё лицо становится всё более сформированным, по-прежнему велика по сравнению с телом, он уже приобрёл полностью человеческий облик. Его органы продолжают быстро расти и развиваться. Один из них — печень, которая на текущей 10-й неделе составляет около 10% массы тела малыша. Печень выполняет множество функций и обеспечивает образование крови в организме малыша до тех пор, пока эту функцию не возьмёт на себя костный мозг, то есть до последних двух месяцев беременности.'), baby_message_ru = COALESCE(baby_message_ru, 'Моя кожа пока прозрачная, Anacan! 👻 Если бы вы могли посмотреть на меня, то увидели бы все мои сосуды, кости и органы. Моя кожа такая тонкая, словно стекло. Но не волнуйтесь: по мере формирования жировой прослойки она станет плотнее и будет похожа на вашу. С каждым днём я становлюсь немного крепче. А моё сердце продолжает посылать вам мою любовь с каждым ударом.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Курага'), body_changes_ru = COALESCE(body_changes_ru, 'Вместе с врачом, а при необходимости и с помощью специалиста по питанию, вам следует составить план питания. Такой план поможет получать достаточное количество всех необходимых питательных веществ и избежать избыточного набора веса. Чтобы он был удобным и практичным, необходимо учитывать ваш вес до беременности, повседневную активность, образ жизни и режим дня.;;;
Общий набор веса за беременность индивидуален для каждой женщины. Тем не менее специалисты рекомендуют ориентироваться на определённые диапазоны. При нормально протекающей беременности набор веса будущей мамы в пределах 9-12 кг считается нормальным. Для будущих мам с недостаточным или избыточным весом этот диапазон может отличаться. Размер растущего в животе малыша также напрямую влияет на набор веса. Мамы, ожидающие малыша небольшого размера, обычно набирают меньше веса, а мамы, у которых малыш крупный, — больше.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сейчас самое время пересмотреть свой гардероб. Узкие брюки и ремни могут сдавливать тело и нарушать кровообращение. Начните приобретать брюки для беременных с эластичным поясом или свободные платья. Комфорт важнее всего.') WHERE id = '96171009-62e6-4557-a2c9-ebf16692943d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По мере развития мозга движения вашего малыша становятся всё более осознанными. Благодаря этому малыш активнее двигается в течение дня. Он уже умеет сгибать ручки и шевелить маленькими пальчиками ног, которые недавно отделились друг от друга.;;;
В организме человека есть три типа мышц: сердечная, гладкая и поперечно-полосатая мышечная ткань. Поперечно-полосатые мышцы — единственный тип мышечной ткани, которым человек может управлять сознательно. Эти мышцы расположены в руках, спине и ногах. После определённой нагрузки они утомляются. Сердечная мышца имеет особое строение. Она сокращается самостоятельно и непрерывно работает на протяжении всей жизни человека. Последний тип — гладкие мышцы — играет важную роль в работе пищеварительной системы. Они сокращаются непроизвольно и активно участвуют в процессах пищеварения. Все три типа мышечной ткани обладают общими свойствами: эластичностью, способностью сокращаться, реагировать на раздражители и проводить возбуждение.'), baby_message_ru = COALESCE(baby_message_ru, 'Я зеваю! 🥱 Может быть, читая это, ты тоже зевнула? Да, я уже умею широко открывать рот и зевать. Но не потому, что хочу спать, а чтобы развивать мышцы челюсти и лёгкие. А ещё иногда я икаю. Ты пока не чувствуешь этих лёгких толчков, но внутри у меня очень много дел.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Хурма'), body_changes_ru = COALESCE(body_changes_ru, 'На протяжении всей истории люди выдвигали разные предположения о том, как предугадать пол будущего малыша. Например, считалось, что у будущих мам, которым хочется кислого, родится девочка, а у тех, кто предпочитает сладкое, — мальчик. Однако исследования показывают, что между пищевыми пристрастиями или отвращением к определённым продуктам и полом малыша нет никакой связи.;;;
На животе может стать заметнее тёмная линия, называемая чёрной линией, или linea nigra. Она тянется вниз от пупка, а иногда и вверх. Это совершенно нормальное следствие гормональных изменений, которое не представляет никакой опасности. Через несколько месяцев после родов линия постепенно побледнеет и исчезнет сама.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить газообразование, старайтесь не разговаривать во время еды, чтобы не заглатывать воздух. Тщательно пережёвывайте пищу. Также может помочь временный отказ от бобовых и газированных напитков.') WHERE id = '1980273b-7820-40aa-b793-4b715fda3015';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Пол вашего малыша определяется уже в момент оплодотворения — в зависимости от того, какую хромосому, X или Y, несёт сперматозоид отца. Однако формирование половых органов занимает некоторое время. На 5-й неделе и у мальчиков, и у девочек появляется одинаково выглядящий небольшой бугорок. На 8-й неделе особые клетки, из которых будут формироваться половые органы, начинают перемещаться в эту область. Интересно, что до 12-й недели определить пол малыша по внешнему виду практически невозможно.;;;
Если у малыша есть Y-хромосома, клетки превращаются в яички и к 12-й неделе начинают вырабатывать гормон тестостерон. Именно он обеспечивает формирование наружных половых органов у мальчиков. Если у малыша две X-хромосомы, то есть это девочка, клетки формируют матку и маточные трубы. В этом процессе важную роль играет гормон эстроген, который способствует развитию характерных для девочек внутренних и наружных половых структур.'), baby_message_ru = COALESCE(baby_message_ru, 'Я размером с клубничку! Уже не такая маленькая, правда? Моё тело выпрямляется, а позвоночник удлиняется. Хотя твой животик пока почти не заметен, внутри я уже заняла своё просторное местечко. Мы растём вместе, Anacan. Спасибо тебе за то, что оберегаешь меня.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Клубника'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности следует уделять особое внимание уходу за полостью рта. Из-за происходящих в организме изменений могут возникнуть проблемы с зубами и дёснами. Правильный уход за зубами во время беременности очень важен для здоровья мамы и малыша. Употребление достаточного количества продуктов, богатых кальцием, помогает предотвратить заболевания зубов и полости рта и способствует благополучному течению беременности и родов. В этот период важно придерживаться сбалансированного питания ради себя и малыша. Чистите зубы после еды и пользуйтесь зубной нитью, чтобы обеспечить эффективный уход и предотвратить образование налёта.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку первый триместр подходит к концу, вы можете почувствовать прилив сил. Это идеальное время, чтобы начать выполнять лёгкие физические упражнения или заниматься плаванием. Из-за сохраняющейся чувствительности дёсен уделяйте особое внимание гигиене полости рта. Следите, чтобы в рационе было достаточно белка и кальция. На следующей неделе нас ждёт 12-я неделя — завершение первого важного этапа!') WHERE id = '2348cc6e-cce7-4823-afd3-9cc2309eebb6';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Почки вашего малыша продолжают развиваться и уже достаточно созрели, чтобы вырабатывать мочу. Однако на этом этапе они ещё не настолько развиты, чтобы в полной мере выводить продукты обмена из организма. В ближайшие недели вырабатываемая почками моча будет поступать в амниотическую жидкость, окружающую малыша. Как бы необычно это ни звучало, в ней нет мочевины, а согласно исследованиям, она стерильнее питьевой воды. Кроме того, она выполняет защитную функцию, помогая противостоять инфекциям.'), baby_message_ru = COALESCE(baby_message_ru, 'Можешь меня пощекотать? Шучу! 😂 Но если бы ты только знала, какой чувствительной стала моя кожа... Если кто-нибудь, например врач во время УЗИ, прикоснётся к твоему животу, я сразу отреагирую и отодвинусь. Мои рефлексы настолько обострились, что я всё чувствую. Я уже не просто скопление клеток, а живое существо, способное ощущать.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Клубника'), body_changes_ru = COALESCE(body_changes_ru, 'По мере стабилизации гормонального фона и уменьшения тошноты у вас мог усилиться аппетит. Теперь вы питаетесь и для себя, и для малыша. Поэтому следует отказаться от вредных продуктов, курения и алкогольных напитков. Ограничение продуктов с пустыми калориями поможет избежать чрезмерного набора веса. Желание поесть ночью возникает у многих будущих мам. Однако из-за приёма пищи в ночное время может нарушаться выработка лептина — гормона, участвующего в регуляции уровня сахара в крови. Недостаточная выработка лептина может привести к быстрому набору веса. Поэтому после 9 часов вечера рекомендуется ничего не есть и не пить, кроме воды: это важно как для здоровья желудка, так и для контроля веса.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если тошнота прошла, самое время сделать рацион разнообразнее: сосредоточьтесь на зелёных овощах и качественных источниках белка. Продолжайте использовать увлажняющие масла для кожи, испытывающей растяжение. Если энергия вернулась, спокойные 20-минутные прогулки в течение дня помогут улучшить снабжение кислородом и вашего организма, и малыша.') WHERE id = '726669c0-162f-4b1a-a70b-ca60baf4c509';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Наружные уши вашего малыша уже приобрели окончательную форму. Сейчас они расположены немного ниже, но по мере роста малыша будут подниматься вверх, занимая своё обычное положение. В глазах уже сформировались основные оптические структуры, обеспечивающие зрение, а веки теперь полностью закрывают глаза.;;;
Во рту развиваются зачатки зубов, а на лице начинают появляться первые тонкие волоски бровей. На этом этапе тело малыша уже не имеет форму буквы "C" и всё больше приобретает человеческие очертания.;;;
Кроме того, плацента, формирующаяся подобно пуповине, продолжает удлиняться. Эта структура играет важнейшую роль в связи между мамой и малышом. К её основным функциям относятся обеспечение газообмена, доставка питательных веществ малышу, выведение продуктов обмена из его организма в организм мамы и выработка некоторых гормонов, необходимых для роста малыша. Плацента также передаёт от мамы малышу глюкозу, аминокислоты, жирные кислоты, кальций, витамин D и кислород, а углекислый газ и другие продукты обмена переносит от малыша к маме.'), baby_message_ru = COALESCE(baby_message_ru, 'Я занимаюсь акробатикой! 🤸‍♂️ Anacan, я не просто лежу — я потягиваюсь, поворачиваюсь и даже делаю сальто. Матка пока для меня как просторный бассейн, и я этим пользуюсь. Эти движения помогают развиваться моим мышцам и суставам. Вы пока ничего не чувствуете, но я здесь устраиваю настоящее шоу!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Курага'), body_changes_ru = COALESCE(body_changes_ru, 'Под влиянием гормона прогестерона во время беременности изменяется способность роговицы — прозрачного слоя в передней части глаза — удерживать воду. В результате зрение может стать затуманенным, а у тех, кто носит контактные линзы, может появиться повышенная чувствительность к ним. В этот период лучше по возможности отказаться от использования контактных линз.;;;
Хотя нарушения зрения у беременных могут возникать по физиологическим причинам, всем будущим мамам с жалобами на зрение следует регулярно проходить обследование у офтальмолога. Из-за гормональных изменений проблемы с глазами во время беременности могут быть связаны с изменениями сосудов. К ним относятся структурные нарушения внутричерепных сосудов, закупорка артерии сетчатки, спонтанные кровоизлияния в глазницу и кровоизлияния в гипофиз.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Витамин C укрепляет дёсны. Ешьте апельсины, киви, красный перец и другие продукты, богатые этим витамином. Не чистите зубы слишком интенсивно, используйте мягкую зубную щётку и не забывайте пользоваться зубной нитью.') WHERE id = '2519d258-d4d3-4114-9156-6af5c1a49493';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ещё один орган, который стремительно развивается на этом этапе, — кожа. Пока она выглядит почти прозрачной, поэтому сквозь неё видны кровеносные сосуды и органы, но она продолжает быстро утолщаться. Кожа малыша станет органом, обеспечивающим осязание. Она защищает тело от внешних воздействий, обеспечивает выделение кожного сала и пота, способствует получению организмом витамина D, регулирует температуру тела и предотвращает потерю воды. Матка, внутри которой находятся малыш, плацента и околоплодные воды, с начала беременности увеличилась примерно вдвое. На этой неделе объём околоплодных вод составляет около 30 ml. На данном этапе они образуются путём фильтрации жидкой части крови мамы.'), baby_message_ru = COALESCE(baby_message_ru, 'Моё обоняние пробуждается! 👃 Anacan, вы не поверите, но я уже тренируюсь дышать носом (только вместо воздуха здесь вода). И я уже чувствую запах околоплодных вод! Ароматы блюд, которые вы едите, тоже доходят до меня. Когда вы едите чеснок, я это замечаю, и когда шоколад — тоже! Наши вкусовые предпочтения начинают формироваться уже сейчас.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Финик'), body_changes_ru = COALESCE(body_changes_ru, 'Объём крови и количество эритроцитов увеличиваются. Однако жидкая часть крови возрастает ещё сильнее, поэтому может развиться относительная анемия. В таком случае может потребоваться приём препаратов железа. Сердце также начинает работать быстрее, поэтому время от времени может возникать учащённое сердцебиение. Это начинается на ранних сроках беременности и достигает максимума на 20-24-й неделях. ;;;
Под влиянием вырабатываемых гормонов артериальное давление может немного снижаться. По мере развития беременности, особенно в положении лёжа на правом боку, матка может сдавливать крупную вену и вызывать резкое снижение давления. Поэтому врачи рекомендуют беременным, особенно на поздних сроках, лежать на левом боку.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Всегда носите в сумке бутылку воды. Если от обычной воды вас тошнит, добавьте в неё ломтик лимона, огурца или листик мяты. Это изменит вкус воды и поможет вам почувствовать себя свежее.') WHERE id = 'f068ab76-fa64-4eef-8ed3-e47df04dba49';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Мозг вашего малыша растёт с невероятной скоростью. На этом этапе каждую 4 минуту в нём образуется 1 миллион нейронов. На развитие нервной системы малыша влияют разные факторы, прежде всего генетический код, полученный от мамы и папы.;;;
Фолиевая кислота — важнейший витамин, который помогает защитить малыша от возможных нарушений развития нервной системы на протяжении формирования мозга. Фолиевая кислота относится к витаминам группы B и в большом количестве содержится в брюссельской и кудрявой капусте, шпинате, спарже, свёкле, салате и красном перце. Однако одной фолиевой кислоты недостаточно. Важно также получать все необходимые питательные вещества и пить достаточно воды.;;;
Для здорового развития малыша необходимо употреблять белковые продукты, свежие фрукты и овощи. Позитивный эмоциональный настрой также относится к важным факторам, влияющим на развитие мозга малыша.;;;
Все обследования, проводимые во время беременности, дают информацию о нервной системе и мозге малыша. "Двойной тест", выполняемый на 11-14-й неделях беременности, и "тройной тест", выполняемый на 16-18-й неделях, важны для оценки риска возможных генетических нарушений у малыша.'), baby_message_ru = COALESCE(baby_message_ru, 'Я умею разжимать кулачки! ✊🖐️ Мои пальчики уже полностью разделились, и теперь я могу сжимать ладони в кулачки, а затем разжимать их. Для меня это словно новая игрушка. Иногда я касаюсь руками лица, а иногда пытаюсь схватиться за пуповину. Мой хватательный рефлекс развивается. С нетерпением жду дня, когда смогу ухватиться за ваш палец!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Финик'), body_changes_ru = COALESCE(body_changes_ru, 'Сердцебиение малыша в матке обычно начинает определяться примерно на 6-7-й неделях. По мере развития беременности частота сердечных сокращений, составляющая 90-110 ударов в минуту, к концу первого триместра превышает 140 ударов. Это примерно вдвое больше обычной частоты сердцебиения взрослого человека. Когда на приёме у врача вы услышите сердцебиение малыша, оно может показаться вам очень быстрым. ;;;
Если учесть, что после родов вас ждут бессонные дни, сейчас вам будет полезно как следует высыпаться. Здоровый режим сна помогает гормональному фону легче прийти в равновесие.;;;
Матка, которая обычно меньше вашего кулака, к этой неделе достигает размера крупного грейпфрута.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы поддержать работу пищеварительной системы, употребляйте продукты, богатые клетчаткой, и пейте достаточно воды. Если у вас появились боли в пояснице, внимательно выбирайте обувь: она должна быть удобной, без слишком высокого каблука и не на слишком плоской подошве. Находите время для отдыха в течение дня и по возможности лежите на левом боку, чтобы улучшить кровообращение.') WHERE id = 'e6ecf1e2-7281-4cf6-94ac-a3478b23c498';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Ваш малыш уже достиг 6 см в длину и весит 7-8 граммов. Хвостик полностью исчез, и эмбриональный период завершился. Теперь все органы находятся на своих местах, и начинается этап быстрого роста. В течение следующих 8 недель малыш станет в 30 раз тяжелее и в 3 раза длиннее, чем сейчас. Чтобы поддержать этот рост, в вашем организме увеличиваются объём крови и количество кровеносных сосудов. Сейчас голова малыша выглядит большой по сравнению с телом, но вскоре пропорции тела станут более гармоничными. Пальчики уже удлинились; теперь малыш не только сжимает кулачки, но и раскрывает ладони, начиная исследовать окружающее пространство.'), baby_message_ru = COALESCE(baby_message_ru, 'Я девочка или мальчик? Тайна вот-вот раскроется! 🩷💙 Мои наружные половые органы уже начинают различаться. Несколько недель назад мы все выглядели одинаково, но теперь половой бугорок меняет угол наклона. Возможно, врачи пока не смогут сказать точно, но процесс уже идёт. А что чувствуешь ты? Говорят, материнское сердце не обманет.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Клубника'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности, особенно в первом триместре, под действием гормона прогестерона некоторые гладкие мышцы расслабляются. Из-за этого пища медленнее продвигается по пищеварительной системе, дольше задерживается в желудке и кишечнике, что может вызывать проблемы с пищеварением. Если вздутие становится настолько выраженным, что причиняет дискомфорт, следует обратиться к врачу для подбора лечения. Приём лекарств или растительных средств без контроля врача может негативно повлиять на развитие малыша.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в пояснице, старайтесь сидеть прямо, а во время сна лежать на левом боку. Утолять усилившийся аппетит лучше полезными перекусами. Чтобы улучшить усвоение железа, включайте в рацион продукты, богатые витамином C. Каждый день хотя бы 10 минут глубоко дышите в спокойной обстановке, стараясь установить связь со своим малышом.') WHERE id = '8c65943a-4d31-4534-b028-6c3f95fa6988';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Клетки головного мозга вашего малыша размножаются с невероятной скоростью. С момента рождения эти клетки начинают устанавливать связи друг с другом, и этот процесс продолжается на протяжении всей жизни. По мере взросления человека всё больше места в мозге занимают не сами клетки, а связи между ними. Уже сейчас нервная система малыша развита настолько, что может передавать в мозг информацию, поступающую от органов чувств.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой голос скоро зазвучит! 🎤 (А пока беззвучно). Мои голосовые связки начинают формироваться. Сейчас я нахожусь в воде, поэтому не могу издавать звуки, но готовлюсь к тому, чтобы после рождения ты услышала моё первое "Уа-а!". Представляешь этот момент? Мой голос станет для тебя самой прекрасной музыкой в мире.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Инжир'), body_changes_ru = COALESCE(body_changes_ru, 'В течение дня у вас могут часто возникать судороги. Они могут ощущаться в паховой области, а также в ногах и икрах. Хотя точная причина судорог в ногах до конца не установлена, среди основных факторов называют дефицит кальция и магния. Поэтому во время беременности особенно важно получать достаточное количество магния и кальция. Посоветовавшись с врачом, вы можете принимать подходящие витаминно-минеральные добавки.;;;
Нарушения кровообращения, возникающие во время беременности из-за давления растущей матки на венозную систему, также играют важную роль в появлении судорог. Поскольку минералы из вашего организма передаются малышу через плаценту, объём внутрисосудистой жидкости увеличивается, а уровень магния в крови снижается. При судороге постарайтесь сохранять спокойствие, выпрямите колено и медленно поднимите ногу. Попробуйте расслабиться, мягко растягивая мышцы ноги. Лёгкий массаж области судороги, тёплое полотенце на мышцах и осторожное подтягивание пальцев стопы вверх помогают уменьшить спазм. Кроме того, молочные продукты, рыба, орехи, например миндаль, а также фасоль, чечевица и семена кунжута помогают восполнить запасы магния и кальция в организме и предотвратить судороги.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы избежать головокружения, медленно вставайте из положения сидя или лёжа. Из-за увеличения объёма крови важно пить достаточно жидкости. Если вы ещё не были у врача для проведения "Двойного теста" (скрининга), эта неделя — самое подходящее время. Если ваш аппетит усилился, уделите особое внимание продуктам, богатым кальцием и магнием.') WHERE id = '1a115c93-d622-40f8-b3f4-8d1be6d3b8e9';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'По мере развития мозга ваш малыш уже начинает совершать рефлекторные движения. Они происходят непроизвольно и закладывают основу будущих физических навыков малыша. Например, один из первых рефлексов — открывание рта при прикосновении к чему-либо внутри матки.;;;
Это развитие состоит из двух этапов:;;;
Сбор информации: на этом этапе, который начинается уже сейчас, малыш посредством движений приобретает рефлексы поиска пищи и самозащиты. Например, при внезапном толчке он вскидывает руки, словно испугавшись, а затем сводит их вместе (рефлекс Моро).;;;
Обработка информации: на этом этапе, который начинается через 4 месяца после рождения, центральные структуры мозга продолжают совершенствоваться.;;;
В результате эти непроизвольные рефлексы, сформировавшиеся в утробе матери, постепенно сменяются осознанными, произвольными движениями, такими как умение сидеть, хватать предметы и вставать.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой кишечник вернулся домой! 🏠 Anacan, помнишь, из-за того, что мой животик был ещё маленьким, кишечник временно находился внутри пуповины? Сегодня он официально вернулся на своё место в брюшной полости. Теперь мой животик гладкий и красивый. Все мои внутренние органы уже находятся на своих местах и работают. С каждым днём я становлюсь всё совершеннее.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Инжир'), body_changes_ru = COALESCE(body_changes_ru, 'Начиная с этой недели беременности, когда первый триместр подходит к концу, можно провести двойной скрининговый тест для оценки риска врождённых пороков у малыша. Этот двойной скрининг также известен как тест первого триместра. В рамках обследования проводится подробное УЗИ и определяется уровень двух важных белков в крови. Во время УЗИ оценивают толщину воротникового пространства малыша и наличие носовой кости. При нормально развивающейся беременности толщина воротникового пространства должна составлять не более 2.5 mm. Чем она больше, тем выше вероятность хромосомной аномалии. Кроме того, наличие носовой кости при двойном тесте является важным показателем здорового развития малыша. При хромосомных нарушениях носовая кость может отсутствовать или быть значительно меньше ожидаемого размера.;;;
По результатам двойного теста нельзя точно определить, есть ли у малыша аномалии. Эти исследования лишь оценивают их вероятность. Если риск окажется выше нормы, врач может рекомендовать такие методы, как амниоцентез, чтобы получить более точный ответ.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Старайтесь поддерживать стабильный уровень сахара в крови. Длительные перерывы между приёмами пищи могут вызвать головокружение и слабость. Всегда носите в сумке полезный перекус, например сухофрукты, орехи или яблоко.') WHERE id = '6d7fa2b9-68dc-41a1-b8e4-2909aebba355';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Нёбо вашего малыша начало формироваться. Нёбо — это сводчатая структура, образующая верхнюю стенку полости рта малыша и участвующая в произнесении некоторых звуков. Передняя часть нёба, образующая твёрдый свод, называется твёрдым нёбом, а задняя — мягким нёбом.;;;
Нёбо прикреплено к основанию черепа малыша двумя парами мышц, расположенными с обеих сторон. Оно также отделяет полость рта малыша от полости носа. Подвижное мягкое нёбо при глотании поднимается и закрывает носовую полость, предотвращая попадание туда пищи. Посередине заднего края мягкого нёба расположен нёбный язычок (uvula), который помогает произносить некоторые звуки. Задняя часть нёба участвует в формировании малышом таких заднеязычных согласных, как "q, k, ğ".'), baby_message_ru = COALESCE(baby_message_ru, 'Я уже умею корчить рожицы! 😝 Мышцы моего лица развились настолько, что теперь я могу показывать разные выражения. Я хмурю брови, поджимаю губы, улыбаюсь или удивляюсь. Для меня это игра. Я уже тренируюсь, чтобы смешить тебя после рождения. А ты мне улыбаешься?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Инжир'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности не рекомендуется худеть и соблюдать диеты, поскольку это может негативно повлиять на развитие малыша. Однако чрезмерная прибавка в весе также иногда может оказывать неблагоприятное влияние. Чтобы избежать слишком быстрого набора веса и обеспечить оптимальную прибавку в течение беременности, важно следить за своим питанием.;;;
Кроме того, полезно отказаться от готовых продуктов с добавленным сахаром, твёрдых жиров и продуктов с низкой пищевой ценностью, содержащих пустые калории. Избыточное потребление углеводов и привычка есть по ночам также могут приводить к увеличению веса. Под влиянием гормонов обмен веществ во время беременности замедляется, а при недостатке физической активности прибавка в весе может стать неизбежной. Справиться с внезапными приступами голода в течение дня и контролировать вес помогут полезные перекусы. Если у вас нет проблем со здоровьем, некоторые специально разработанные для беременных упражнения также помогут предотвратить слишком быстрый набор веса.;;;
Кроме того, следует отказаться от любых непастеризованных молочных продуктов. Вопреки распространённому мнению, пастеризация считается одним из важнейших изобретений прошлого века: она позволяет обезвредить содержащиеся в молоке опасные микроорганизмы, сохранив его пищевую ценность. При кипячении сырого молока в домашних условиях погибают многие как полезные, так и вредные микроорганизмы, однако некоторые устойчивые формы бактерий могут сохраняться. Поэтому вместо сырого молока рекомендуется выбирать пастеризованное молоко с коротким сроком хранения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если чувствительность дёсен сохраняется, ешьте фрукты, богатые витамином C. Если у вас усилился аппетит, поддерживайте баланс белка и кальция в рационе. Возьмите за привычку ежедневно выпивать не менее 2 литров воды. Если у вас болит поясница, старайтесь носить удобную обувь и сидеть с прямой спиной. Каждый день уделяйте время себе и слушайте спокойную музыку — это подарит положительные эмоции и вам, и малышу.') WHERE id = 'f769e4b1-414a-408e-8810-543b96add6b7';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Развивается сосательный рефлекс. Плод подносит пальцы ко рту и совершает сосательные движения. Это основа инстинкта, необходимого для питания после рождения. Кроме того, плод заглатывает амниотическую жидкость, которая проходит через пищеварительную систему и фильтруется почками.'), baby_message_ru = COALESCE(baby_message_ru, 'Я учусь сосать! 🍼 Я подношу большой палец ко рту и пытаюсь его сосать. Это важнейший навык, который поможет мне после рождения легко сосать твоё молоко. Иногда у меня получается, а иногда рука ускользает ото рта. Но я не сдаюсь и продолжаю тренироваться. Ты тоже готовься к нашей встрече, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Инжир'), body_changes_ru = COALESCE(body_changes_ru, 'Рыба богата жирными кислотами Омега-3 и Омега-6, поэтому её употребление во время беременности имеет большое значение для развития мозга и зрения малыша. Рыба также богата белком и витамином D и вносит важный вклад в развитие малыша. Благодаря лёгкой усвояемости врачи рекомендуют при здоровой беременности есть рыбу два раза в неделю. Однако это не означает, что можно употреблять любую рыбу. Некоторые виды содержат большое количество ртути, которая может негативно повлиять на развитие малыша. Лосось, тунец, сардины, форель и скумбрия относятся к видам рыбы, которые можно употреблять во время беременности с учётом рекомендаций врача; они обладают высокой пищевой ценностью и содержат фолиевую кислоту. Эти виды рыбы богаты жирными кислотами Омега-3 и Омега-6, а содержание ртути в них обычно невысокое. Достаточно съедать примерно 300-400 граммов приготовленной рыбы в неделю. Во время беременности следует избегать сырой рыбы и консервов с добавками. При жарке многие витамины разрушаются, поэтому лучше готовить рыбу на пару, на гриле или запекать в духовке.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если у вас усилился аппетит, ешьте часто и небольшими порциями, чтобы поддерживать стабильный уровень сахара в крови. Продолжайте пользоваться увлажняющими маслами (миндальным или кокосовым), чтобы поддерживать эластичность кожи. Можете начать выбирать одежду для беременных — сейчас удобство важнее всего. Чтобы провести день в хорошем настроении, посмотрите любимый фильм.') WHERE id = '32fc4b43-9967-407f-bd27-ce27ec4287ad';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Сейчас, когда завершилась 11-я неделя беременности, вы уже можете более отчётливо увидеть малыша на УЗИ. На этом этапе начинают формироваться его половые органы. Область, которая раньше выглядела как небольшой участок ткани, теперь развивается в пенис или клитор. Если малыш занимает в матке подходящее положение, его пол уже может быть виден на УЗИ.;;;
В то же время продолжают развиваться уши, постепенно занимая своё место по бокам головы. Между наружным и средним ухом формируется барабанная перепонка. Она служит барьером, препятствующим проникновению бактерий внутрь, а также помогает малышу впервые воспринимать звуки внешнего мира. Малыш уже слышит звуки, но пока не умеет их различать.;;;
По мере приближения к концу первого триместра меняется и положение тела малыша. Его шея удлиняется, подбородок отделяется от груди, а голова начинает держаться более прямо. Так малыш постепенно выходит из прежнего согнутого положения в форме "C", и его тело выпрямляется.'), baby_message_ru = COALESCE(baby_message_ru, '12 НЕДЕЛЬ ПОЗАДИ! 🎉 Anacan, мы успешно завершили первый триместр! Это был самый сложный и важный этап беременности. Все мои органы уже заложились и сформировались. Теперь я официально "маленький человечек". Впереди нас ждут более лёгкие и энергичные дни. Я горжусь тобой — мы отличная команда!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Инжир'), body_changes_ru = COALESCE(body_changes_ru, 'С этого дня плацента начинает полноценно работать и перенимает выработку гормонов у "жёлтого тела". Этот переход обычно сопровождается уменьшением тошноты и приливом энергии. Вы можете почувствовать себя бодрее. Самый уязвимый период беременности уже позади!;;;
Из-за гормональных изменений во время беременности могут возникнуть некоторые проблемы с кожей. Возможно появление экземы и псориаза или обострение уже имеющихся заболеваний. Чтобы снизить риск обострений экземы и псориаза, важно поддерживать кожу увлажнённой, пить достаточно воды, есть свежие фрукты и овощи.;;;
На последних неделях беременности из-за значительного увеличения живота могут появиться высыпания. Они особенно часто встречаются при первой беременности и могут сопровождаться появлением зудящих пятен.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отпразднуйте завершение первого триместра любимым ритуалом! С возвращением энергии вы можете постепенно вернуться к более активному образу жизни, но старайтесь не поднимать тяжести. Поскольку аппетит усилился, сосредоточьтесь не на питании "за двоих", а на качественном питании "для двоих". Если вы ещё не прошли "двойной тест", уточните у врача допустимые сроки его проведения. Готовьтесь наслаждаться вторым триместром — "медовым месяцем" беременности!') WHERE id = '43e2ccf7-0f43-404f-b8d5-9a230d2fcf1f';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Мочевыделительная система малыша стремительно развивается. Она состоит из двух почек, мочеточников и мочевого пузыря. Её основная задача — очищать кровь от вредных веществ и поддерживать водно-солевой баланс организма. Начиная с этой недели малыш уже выделяет мочу, которая смешивается с окружающими его околоплодными водами. Внутри почек формируются миллионы крошечных фильтров, называемых нефронами, которые фильтруют кровь. Сейчас в почках функционируют нефроны как с короткими, так и с длинными петлями. Когда малыш полностью сформируется, в каждой его почке будет более 1 миллиона таких крошечных фильтров. Благодаря этим канальцевым структурам кровь малыша постоянно очищается, а обмен веществ регулируется.'), baby_message_ru = COALESCE(baby_message_ru, 'Добро пожаловать во второй триместр! ☀️ Его называют «золотым периодом». Ведь вы будете чувствовать себя лучше, а я буду стремительно расти. Сейчас я размером с лайм. Мои движения стали более скоординированными. Теперь они не случайны — я двигаюсь так, как хочу. Я хочу прикоснуться к вам, Anacan.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лайм'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности необходимо внимательно относиться к любым жалобам. Например, в результате аллергической реакции на теле могут появиться сыпь, красные пятна и зуд. В первые месяцы беременности такие высыпания и зуд могут быть связаны с гормоном прогестероном. Однако если они сохраняются на более поздних сроках, необходимо обязательно сдать анализы крови. В рамках этих анализов проверяют печёночные ферменты, маркеры гепатита, показатели желчи и гормоны щитовидной железы. Если результаты этих анализов отличаются от нормы, необходимо пройти лечение ради здоровья как вашего, так и малыша.;;;
Кроме того, такие симптомы, как отсутствие аппетита, слабость, утомляемость, покраснение или пожелтение глаз, изменение запаха и цвета мочи, могут указывать на нарушение показателей работы печени. Такое состояние называется холестазом беременных. Женщинам с холестазом беременных требуется тщательное наблюдение и регулярное обследование с помощью НСТ, допплерометрии и ультразвукового исследования.;;;
Вероятность появления этих симптомов особенно высока, если между беременностями не было длительного перерыва.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Проконсультируйтесь с врачом по поводу половой жизни. Если риски отсутствуют (кровотечение, угроза выкидыша), половые контакты во время беременности совершенно безопасны и даже могут быть полезны (благодаря гормону окситоцину).') WHERE id = '931efc18-1bb9-41fb-bf51-8eb31fb5efd5';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Кишечник малыша уже значительно развился. В первые недели он представлял собой простую ткань, а теперь, образуя изгибы, разделился на передний и средний отделы и быстро удлиняется параллельно с развитием сердца и лёгких. В этот период объём околоплодных вод, окружающих малыша, достигает примерно 50 ml. Одновременно начинает работать гипофиз, который называют «главной железой» мозга. Эта маленькая железа вырабатывает множество гормонов, необходимых для роста, обмена веществ и будущей работы репродуктивной системы. Работой гипофиза управляет другой отдел мозга — гипоталамус. Вместе они поддерживают внутреннее равновесие организма. Если какой-либо процесс в организме нарушается, эти железы с помощью гормонов сразу помогают нормализовать состояние.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои отпечатки пальцев готовы! 🧬 Мои уникальные отпечатки пальцев, которых нет больше ни у кого в мире, полностью сформировались. Это моё удостоверение личности. Даже если бы у меня был близнец, его отпечатки отличались бы от моих. Я один такой, я неповторим!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лайм'), body_changes_ru = COALESCE(body_changes_ru, 'Если во время беременности вы испытываете чрезмерную жажду, очень часто мочитесь, чувствуете онемение в ногах или замечаете резкие изменения веса, возможно, у вас развился сахарный диабет. Если раньше у вас не было сахарного диабета, такое состояние, возникшее во время беременности, называется «гестационным диабетом». У женщин с гестационным диабетом могут наблюдаться повышенное артериальное давление, головокружение и головные боли. Вопреки распространённому мнению, это состояние возникает не только у беременных с избыточным весом. Риск выше у тех, в чьей семье были случаи сахарного диабета. Гестационный диабет развивается из-за того, что плацента растёт, поддерживая малыша на протяжении беременности, а выделяемые ею гормоны снижают чувствительность организма матери к инсулину. Это состояние называется инсулинорезистентностью. Если инсулин действует недостаточно эффективно, глюкоза в крови не может использоваться для получения энергии, и уровень сахара в крови повышается. В результате развивается гестационный диабет.;;;
Лечение включает соблюдение диеты и, при необходимости, применение инсулина. На протяжении всей беременности особенно важно придерживаться правильного режима питания. При отсутствии лечения гестационный диабет может привести к выкидышу, преждевременным родам, чрезмерно быстрому набору веса малышом и некоторым нарушениям его развития. Наличие гестационного диабета определяют с помощью глюкозотолерантного теста, который проводят на 24-28-й неделях беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Утолять усилившийся во втором триместре аппетит лучше полезными продуктами — орехами, свежими фруктами и творогом. Если у вас появились лёгкие боли в пояснице, подкладывайте под спину небольшую поддерживающую подушку, когда сидите. Чтобы предотвратить появление пигментации во время беременности, избегайте прямых солнечных лучей и используйте солнцезащитные средства с высоким фактором защиты.') WHERE id = 'ec212007-cf13-4d3e-9523-fa6762234108';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поджелудочная железа малыша уже начинает вырабатывать инсулин. 99% этой железы производит ферменты, помогающие пищеварению, а оставшиеся небольшие группы клеток, составляющие 1%, выделяют инсулин. Инсулин позволяет клеткам использовать сахар (глюкозу) — основной источник энергии для организма. Его главная задача — не допускать чрезмерного повышения уровня сахара в крови. Инсулин забирает сахар из крови и направляет его в мышечные и жировые клетки для выработки энергии. Если уровень сахара в крови снижается, выработка инсулина прекращается, а организм задействует другие гормоны, чтобы поддерживать нормальный уровень сахара. Таким образом, в организме малыша идеально регулируется баланс углеводов, жиров и белков.'), baby_message_ru = COALESCE(baby_message_ru, 'Я начинаю слышать звуки? 👂 Мои уши продолжают развиваться, и я уже чувствую вибрации. Стук вашего сердца, шум крови и звуки желудка — моя колыбельная. Скоро я смогу узнавать и ваш голос. Разговаривайте со мной, Anacan, я вас слушаю.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лайм'), body_changes_ru = COALESCE(body_changes_ru, 'Риск появления растяжек на коже повышается. По мере роста живота, бёдер и груди кожа растягивается. Генетика играет здесь большую роль, однако увлажнение кожи повышает её эластичность и уменьшает зуд. Сухая кожа быстрее покрывается растяжками. Поэтому важно ежедневно увлажнять кожу и делать массаж 1-2 раза в неделю.;;;
Не забывайте включать орехи и семена в рацион во время беременности. Они богаты ценными питательными веществами, и, чтобы получить от них максимальную пользу, их следует употреблять сырыми, а не обжаренными. Особенно полезны грецкие орехи, миндаль, фисташки, кешью, фундук, сушёный инжир, тыквенные семечки, курага и арахис. Грецкие орехи поддерживают развитие мозга малыша; фундук благодаря содержащемуся в нём кальцию способствует развитию костей малыша; миндаль помогает восполнить суточную потребность в цинке; арахис — потребность в витаминах B и E, а также в калии, фосфоре, натрии и магнии. Кроме того, следует в умеренном количестве употреблять высушенные естественным способом фрукты, например инжир и абрикосы, поскольку они содержат множество витаминов и минералов, необходимых вам и малышу во время беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить боль в круглых связках матки, старайтесь не делать резких движений; вставая с кровати, сначала повернитесь на бок. Для здоровья дёсен продолжайте употреблять продукты, богатые кальцием, и пользуйтесь мягкой зубной щёткой. Если у вас усилился аппетит, следите за достаточным содержанием магния в рационе, чтобы предотвратить судороги мышц ног.') WHERE id = '51726a4c-4dfd-4d8d-8fdf-a1b799174400';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Голосовые связки — один из самых чувствительных органов в теле вашего малыша — уже полностью сформировались. Хотя впервые он воспользуется ими только после рождения (во время своего первого плача), всё уже готово. Голосовые связки похожи на две тонкие складки, расположенные в гортани. Когда они вибрируют, щель между ними сужается и расширяется, регулируя высоту голоса. При узкой щели возникают высокие звуки, а при широкой — низкие. Во время родов воздух, поступающий из лёгких, заставит эти связки вибрировать, и вы услышите голос своего малыша. Интересный факт: у девочек голосовые связки формируются более короткими и тонкими, а у мальчиков — более длинными и толстыми. При рождении их длина составляет всего 6 mm. Кроме того, ваш малыш уже начал сосать палец! Это одна из его самых ранних и милых привычек, но увидеть её на УЗИ пока ещё немного рано.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую вкус еды! 🍲 Вкус амниотической жидкости меняется в зависимости от того, что вы едите. Сладкое, кислое, с чесноком... Я всё это глотаю и чувствую вкус. Уже сейчас формируются мои будущие предпочтения в еде. Поэтому, пожалуйста, ешьте побольше овощей, чтобы я тоже их полюбил!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лайм'), body_changes_ru = COALESCE(body_changes_ru, 'Из-за физиологических и психологических изменений, возникающих во время беременности, вы можете избегать половых контактов, опасаясь навредить малышу. Однако при нормально протекающей беременности, если врач не рекомендовал иное, ограничений для половой жизни нет. Более того, по мере развития беременности и стабилизации гормонального фона сексуальное желание может усилиться.;;;
Женщинам, у которых ранее были повторные выкидыши или преждевременные роды, врач может рекомендовать ограничить половую жизнь в первом триместре. Кроме того, врач категорически запрещает половые контакты на любом сроке беременности при угрозе выкидыша или преждевременных родов, а также при вагинальном кровотечении. Запрет сохраняется до подтверждения того, что угроза полностью миновала. При беременности высокого риска, в том числе при так называемом предлежании плаценты — состоянии, при котором плацента расположена ниже малыша и перекрывает шейку матки, — также следует воздерживаться от половых контактов из-за риска кровотечения.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить изжогу, не ложитесь сразу после еды и избегайте острых и сильно приправленных блюд. Ешьте небольшими порциями, но часто. Чтобы увеличить поступление железа, включайте в рацион красное мясо, чечевицу и тёмно-зелёные овощи. Пока у вас достаточно энергии, можно уделить время занятиям, которые приносят вам радость, например планированию первых покупок для малыша.') WHERE id = '18d4758f-242c-49df-ab25-cc0a8449dd65';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Голосовые связки — один из самых чувствительных органов в теле вашего малыша — уже полностью сформировались. Хотя впервые он воспользуется ими только после рождения (во время своего первого плача), всё уже готово. Голосовые связки похожи на две тонкие складки, расположенные в гортани. Когда они вибрируют, щель между ними сужается и расширяется, регулируя высоту голоса. При узкой щели возникают высокие звуки, а при широкой — низкие. Во время родов воздух, поступающий из лёгких, заставит эти связки вибрировать, и вы услышите голос своего малыша. Интересный факт: у девочек голосовые связки формируются более короткими и тонкими, а у мальчиков — более длинными и толстыми. При рождении их длина составляет всего 6 mm. Кроме того, ваш малыш уже начал сосать палец! Это одна из его самых ранних и милых привычек, но увидеть её на УЗИ пока ещё немного рано.'), baby_message_ru = COALESCE(baby_message_ru, 'Мои кости укрепляются! 🦴 Мой скелет, который раньше состоял только из хрящевой ткани, теперь превращается в настоящие кости. Мои руки и ноги удлиняются. Я уже выгляжу более пропорционально. Голова всё ещё большая, но тело старается её догнать. Я стану крепким малышом, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Слива'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности прогестерон при участии эстрогена выполняет несколько важных функций: утолщает стенку матки, помогая малышу закрепиться; снижает чувствительность мышц матки к окситоцину и предотвращает их сокращения, тем самым уменьшая риск выкидыша; поддерживает беременность, а также способствует выработке коллагена и повышению эластичности кожи. Из-за повышения уровня прогестерона в крови сфинктер между желудком и пищеводом расслабляется, в результате чего часть желудочной кислоты может попадать в пищевод. Поэтому вы можете ощущать изжогу и кисловатый привкус во рту. Чтобы свести проявления изжоги к минимуму, старайтесь пить жидкость не во время еды, а между приёмами пищи, ешьте небольшими, легко усваиваемыми порциями и тщательно пережёвывайте пищу. Также избегайте острых блюд, кислых фруктовых соков, кофе и шоколада, во время сна держите голову и грудную клетку выше уровня тела и ужинайте пораньше, чтобы организм успел переварить пищу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Из-за увеличения объёма крови возрастает потребность организма в жидкости — убедитесь, что ежедневно выпиваете не менее 2.5 литра воды. Если вы чувствуете напряжение в пояснице, полностью откажитесь от обуви на высоком каблуке и выбирайте удобную ортопедическую обувь. Увеличьте потребление кальция, чтобы укреплялись кости малыша и сохранялось здоровье ваших зубов и костей.') WHERE id = 'e16dc0a2-01a9-4a7e-990c-b0f97835b682';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Поздравляем! Сегодня вы успешно завершили первый триместр — первые три месяца и один из важнейших этапов беременности. 😊 За прошедшие 12 недель все органы вашего малыша полностью сформировались и заняли свои места. Теперь благодаря пропорциям головы и тела, а также чертам лица он выглядит как маленький человек. Это был и самый чувствительный этап: период, когда малыш был наиболее уязвим к внешним воздействиям, а риск выкидыша был высоким, уже позади.;;;
Начинается период, когда вам станет легче и физически. Матка, в которой растёт малыш, уже не помещается в пределах таза и поднимается выше. Благодаря этому давление на мочевой пузырь уменьшается, и необходимость часто ходить в туалет будет беспокоить вас немного реже.'), baby_message_ru = COALESCE(baby_message_ru, '13-я неделя подходит к концу! 👋 Здравствуй, настоящее облегчение! Я уже такой подвижный... Пинаюсь, поворачиваюсь, сжимаю и разжимаю ладошки. Возможно, вы почувствуете в животе что-то похожее на лёгкое "порхание бабочек" (но не волнуйтесь, если пока ничего не чувствуете). Я здесь и продолжаю расти. Мы вместе прошли удивительный путь.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Слива'), body_changes_ru = COALESCE(body_changes_ru, 'Конец 13-й недели. Вы уже полностью адаптировались ко второму триместру. Сон налаживается, аппетит хороший. Живот уже выглядит как небольшой "беременный животик". Выбирать одежду может стать приятнее. Вы можете чувствовать себя более женственной и красивой. Наслаждайтесь этим временем — это "медовый месяц" беременности! Из груди может продолжать выделяться "молозиво" (первое молоко) или его выделение может начаться именно сейчас. Эта густая желтоватая жидкость считается первой защитой малыша. Если она оставляет пятна на одежде, можно использовать специальные вкладыши для груди. Молочные железы активно готовятся к родам.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Выбирайте не постельный режим, а активный образ жизни. Йога или пилатес для беременных укрепят мышцы и помогут подготовиться к родам. Кроме того, в таких группах вы сможете познакомиться с другими беременными женщинами и обменяться опытом.') WHERE id = '451a1e44-829c-4f45-9442-ac30329fca22';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Печень вашего малыша уже начала вырабатывать желчь. Эта жидкость очень важна для пищеварительной системы, поскольку помогает организму усваивать поступающие с пищей жиры и важные витамины (A, D, E, K). Благодаря желчи в кровь попадают вещества, необходимые для здоровья костей малыша (витамин D), зрения (витамин A), защиты клеток (витамин E) и свёртывания крови (витамин K). Одновременно эта жидкость помогает выводить из организма некоторые вредные вещества. Желчь, ежедневно вырабатываемая печенью, по общему желчному протоку поступает в двенадцатиперстную кишку. Часть этой жидкости накапливается в расположенном под печенью грушевидном желчном пузыре. При необходимости желчный пузырь выделяет её в тонкий кишечник, поддерживая процесс пищеварения.'), baby_message_ru = COALESCE(baby_message_ru, '13 НЕДЕЛЬ! ПРИВЕТ, 2-Й ТРИМЕСТР! 🎉 Anacan, поздравляю нас! Мы прошли уже треть (1/3) беременности. Самые трудные дни остались позади. Теперь начинается период, когда и тебе, и мне будет легче дышать. Я уже размером со сливу. Мои голосовые связки сформировались. Хотя я пока не могу с тобой разговаривать, я уже готовлю свой голос. На этом новом этапе нас ждёт ещё больше прекрасных дней.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Слива'), body_changes_ru = COALESCE(body_changes_ru, 'Одно из наиболее частых явлений во время беременности — усиление выделений из влагалища. Поскольку уровень гормона эстрогена в вашем организме повышается, увеличение объёма выделений чаще всего считается нормой. Они могут быть белыми, жёлтыми или немного темноватыми. Из-за повышения уровня гормонов в крови внешний вид и консистенция выделений могут отличаться от тех, что были до беременности, и это естественно. Обратите внимание: если выделения приобрели тёмно-жёлтый или зеленоватый оттенок, стали очень густыми и, главное, появился неприятный запах, напоминающий запах испорченной рыбы, это может быть признаком вагинальной инфекции, которую необходимо лечить. Чтобы предотвратить появление выделений и инфекций, во время душа не направляйте струю воды внутрь влагалища, не очищайте внутреннюю или наружную область ароматизированными салфетками и мылом, а также избегайте использования дезодорантов и парфюмерных средств. Подобные процедуры вредны, поскольку нарушают естественную микрофлору влагалища. В этот период выбирайте нижнее бельё из хлопка и при необходимости меняйте его 2-3 раза в день. Не используйте ежедневные прокладки, поскольку они препятствуют циркуляции воздуха, а для дополнительной гигиены проглаживайте нижнее бельё горячим утюгом.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Этот период — самое безопасное и комфортное время для путешествий ("Babymoon"). У вас достаточно энергии, а живот ещё не очень большой. Посоветовавшись с врачом, вы можете запланировать небольшой отпуск.') WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'К концу первого триместра самый близкий друг вашего малыша в утробе — плацента — уже полностью сформировалась. Этот временный орган, существующий всего несколько месяцев, играет жизненно важную роль в выживании и развитии малыша. До этого момента сохраняющий беременность гормон прогестерон вырабатывало «жёлтое тело» в вашем организме, но теперь эту ответственную работу берёт на себя плацента. Она передаёт малышу кислород, воду и глюкозу из крови матери, выводит продукты обмена, образующиеся в его организме, служит барьером для некоторых инфекций в материнской крови и пропускает только необходимые малышу вещества. Иными словами, плацента выполняет для вашего малыша функции лёгких, почек и защитной системы.'), baby_message_ru = COALESCE(baby_message_ru, 'Моё тело покрывается волосками! 🐻 Anacan, на моей коже начинают появляться очень тонкие и мягкие волоски, которые называются «лануго». Теперь я похож на маленький персик. Эти волоски не дают мне замёрзнуть в воде и помогают сохранять тепло тела. К рождению большая их часть выпадет, но пока мне нужна эта «шубка». Ты согреваешь меня, а я — себя.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Киви'), body_changes_ru = COALESCE(body_changes_ru, 'С наступлением второго триместра вы можете время от времени ощущать внезапную колющую боль в нижней части живота или в паху. Она возникает из-за растяжения связок вокруг увеличивающейся матки, в которой растёт ваш малыш. Одна из них — круглая связка матки ("round ligament"). Обычно такая боль появляется при вставании, поворотах с боку на бок в постели, резких движениях или кашле. Эти действия вызывают натяжение связок вокруг матки, что и приводит к боли. Отдых, изменение положения тела, отказ от резких движений, тёплый душ и тёплый компресс на болезненную область помогут облегчить состояние.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку ваш аппетит усилился, сделайте рацион разнообразным: ешьте разные овощи и фрукты, чтобы малыш знакомился с различными вкусами. Увеличьте потребление железа (нежирное мясо, чечевица, шпинат), чтобы защитить себя от анемии. Поскольку у вас достаточно энергии, ежедневные лёгкие прогулки по 15-20 минут благоприятно повлияют и на настроение, и на пищеварение.') WHERE id = '00f39406-c90d-4b7e-818d-3a2edbdeef33';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя лёгкие вашего малыша уже сформированы анатомически, они относятся к органам, которые завершают своё развитие последними. Их полное созревание продолжается до 38-й недели беременности. Сейчас малыш находится в амниотической жидкости, поэтому не дышит лёгкими. Необходимый кислород он получает непосредственно из вашей крови, а углекислый газ передаёт обратно в неё. Иными словами, он словно дышит вашими лёгкими.;;;
Несмотря на это, малыш уже тренируется дышать. Вместо воздуха он втягивает и выталкивает через нос и рот жидкость, укрепляя дыхательные мышцы. Эти небольшие движения уже можно увидеть во время ультразвукового исследования. Благодаря таким тренировкам малыш сможет легко сделать свой первый вдох сразу после рождения.'), baby_message_ru = COALESCE(baby_message_ru, 'После отпечатков пальцев у меня теперь появляются и ногти! 💅 Anacan, на кончиках моих пальцев начали формироваться маленькие тонкие ноготки. Пока они очень мягкие, но к рождению отрастут. Иногда я могу поцарапать своё лицо, поэтому после рождения тебе придётся надевать на меня рукавички. Всё во мне похоже на тебя, а ногти?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Киви'), body_changes_ru = COALESCE(body_changes_ru, 'Фолат — это водорастворимая форма витамина B, естественным образом содержащаяся в продуктах, а фолиевой кислотой называют его синтетическую форму. Для большинства людей фолиевая кислота безопасна при приёме внутрь или введении в организм в виде инъекций. Её приём особенно важен во время беременности для развития нервной системы малыша и закрытия нервной трубки. В первые недели беременности она играет значительную роль в кроветворении, образовании новых клеток, поддержании их жизнедеятельности, а также синтезе ДНК и РНК.;;;
Рекомендуется начать приём как минимум за три месяца до беременности и продолжать до её середины. Если принимать препарат невозможно, включите в рацион больше продуктов с высоким содержанием фолата: бамию, спаржу, фасоль, дрожжи, грибы, мясо, бананы, шпинат, брокколи и листовой салат.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Следите за осанкой: прямая спина облегчит дыхание и уменьшит боль в пояснице. Если ваши дёсны стали чувствительными, ешьте продукты, богатые витамином C. Если аппетит усилился, выбирайте для перекуса источники полезных жиров, например орехи. Каждый день выделяйте несколько минут, чтобы поговорить с малышом.') WHERE id = 'aee96903-8ce9-4152-9673-4163944c634d';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Объём окружающей вашего малыша амниотической жидкости достиг примерно 80 мл. Сейчас голова малыша составляет около половины длины его тела, поскольку головной мозг и нервная система развиваются очень быстро. Не беспокойтесь: в ближайшие недели тело начнёт расти быстрее, и пропорции выровняются. К моменту рождения голова будет составлять всего четверть длины тела. Благодаря совершенствованию нервной системы сосательный и глотательный рефлексы малыша становятся всё сильнее. Его сердце бьётся очень быстро и ускоряет кровообращение, чтобы снабжать кровью всё растущее тело. Хотя вы пока этого не чувствуете, ваш малыш уже очень активен внутри: он зевает, толкается, переворачивается и шевелит пальчиками. Если малыш прикоснётся к стенке матки дольше чем на секунду, возможно, совсем скоро вы сможете почувствовать эти лёгкие касания.'), baby_message_ru = COALESCE(baby_message_ru, 'Я мальчик или девочка? Это уже определено! 🩷💙 Мои половые органы полностью сформировались. Если я девочка, в моих яичниках уже есть 2 миллиона яйцеклеток. Если я мальчик, у меня формируется предстательная железа. Возможно, врачи уже смогут определить мой пол с помощью хорошего аппарата УЗИ. А что чувствуешь ты? Материнская интуиция бывает очень сильной!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Киви'), body_changes_ru = COALESCE(body_changes_ru, 'Матка прощупывается на несколько сантиметров ниже пупка. Из-за увеличения объёма крови ваше сердце бьётся быстрее — это нормально. Пигментация кожи, например веснушки или потемневшие родинки, может стать заметнее под воздействием гормонов. Возможно резкое усиление аппетита. Поскольку утренняя тошнота прошла, вы снова начинаете ощущать вкус еды. Однако будьте внимательны: тяга к сладостям и выпечке может привести к чрезмерному набору веса. Отдавайте предпочтение полезным источникам калорий.;;;
Вены на молочных железах становятся заметнее, а ареолы темнеют и увеличиваются. Это естественный механизм, создающий своего рода «мишень», чтобы после рождения малышу было легче найти грудь. Появление желтоватой жидкости из груди нормально, как и её отсутствие.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если вам не терпится узнать пол малыша, дождитесь следующего УЗИ. Но помните, что положение малыша иногда не позволяет его определить. Что-нибудь сладкое перед обследованием может заставить малыша активнее двигаться.') WHERE id = '35661bc0-afeb-48b5-9303-88d093e85d1a';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Один из новых развивающихся органов малыша — селезёнка. Мягкая и губчатая по структуре, она уже достаточно выросла, чтобы взять на себя некоторые важные функции печени. Селезёнка служит в организме малыша своеобразным центром «безопасности и хранения». Она вырабатывает белые клетки крови, которые борются с микробами, и разрушает старые, утратившие свои функции эритроциты. Кроме того, она хранит эритроциты, чтобы использовать их при необходимости. Когда расход энергии возрастает, селезёнка сокращается и выбрасывает этот запас крови в кровеносную систему. Одновременно тело малыша покрывается очень тонкими, мягкими и бесцветными волосками, которые называются лануго. Эти волоски образуют жизненно важный защитный слой. Поскольку жировая прослойка на теле малыша ещё не сформировалась полностью, лануго помогает поддерживать стабильную температуру его тела.'), baby_message_ru = COALESCE(baby_message_ru, 'Я слушаю твой голос! 👂 Мои ушки уже поднялись от шеи к боковым сторонам головы — туда, где им и положено быть. Теперь я слышу тебя лучше. Рассказывай мне сказки, пой песни. Твой голос успокаивает меня. Пусть папа тоже со мной разговаривает — я хочу узнать и его голос.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мандарин'), body_changes_ru = COALESCE(body_changes_ru, 'К этому сроку вы могли набрать в среднем 3-4 килограмма. Во время беременности каждая женщина набирает вес по-разному в зависимости от особенностей телосложения. В среднем нормальной прибавкой за беременность считается 8-12 килограммов. Однако не каждая женщина набирает именно столько. Это совершенно естественно.;;;
Во время беременности талия естественным образом становится шире независимо от того, много или мало веса вы набрали. На протяжении всей беременности следует избегать одежды, сдавливающей живот, тугих носков, ремней, стягивающих талию, и обуви на высоком каблуке. При выборе одежды ставьте на первое место свой комфорт. Правильный выбор нижнего белья также очень важен как для удобства, так и для гигиены. Откажитесь от белья из синтетических и нейлоновых тканей и отдавайте предпочтение хлопковому. Бюстгальтеры также должны быть прежде всего удобными и эластичными.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Направьте возросшую энергию на творчество или планы на будущее. Если вы ощущаете зуд в области живота, это признак растяжения кожи; продолжайте регулярно увлажнять её натуральными маслами (миндальным, оливковым). Следите за достаточным поступлением кальция и витамина D, чтобы кости малыша укреплялись. Ежедневное чтение книг малышу или прослушивание музыки вместе с ним в спокойной обстановке в течение 10 минут поможет ещё сильнее укрепить вашу связь.') WHERE id = 'a57894a0-cfe4-43ea-b3a3-609e569ae8e7';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Нёбная кость и свод полости рта вашего малыша уже полностью сформировались. В его щёчках развиваются особые мышцы, которые позволят ему сосать молоко сразу после рождения. Сосание — это не просто движение, а важнейший навык для питания, иммунитета и ощущения безопасности малыша. Он уже тренируется в утробе, посасывая палец. Благодаря этим тренировкам с самого рождения у него будут сила и техника, необходимые для сосания груди. Процесс происходит так: малыш захватывает сосок губами, верхним нёбом и языком, создавая во рту сильный вакуум (герметичное пространство без воздуха). Его язык оттягивается назад, освобождая во рту место для молока, а рот плотно смыкается, чтобы жидкость не вытекала. Этот рефлекс настолько силён, что в ближайшие недели благодаря таким движениям во рту малыша начнёт вырабатываться слюна, которая после рождения облегчит пищеварение.'), baby_message_ru = COALESCE(baby_message_ru, 'Я плаваю! 🏊‍♂️ Ты не поверишь, но я двигаю ручками и толкаюсь ножками. Я словно маленький лягушонок, плавающий в бассейне. Эти движения очень важны для развития моего мозга. Ты пока меня не чувствуешь, потому что окружающая вода смягчает толчки, но я очень сильный!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мандарин'), body_changes_ru = COALESCE(body_changes_ru, 'Боли в паху могут появиться уже с первой недели беременности, и это нормально. Они даже могут напоминать ощущения перед началом менструации. Такие боли могут возникать при любой беременности: в первые месяцы — из-за увеличения матки и растяжения её мышц, а на поздних сроках — из-за давления растущего малыша на матку и нижнюю часть живота. Кроме того, по мере увеличения срока боли могут быть связаны с движениями малыша. Приём магния под наблюдением врача может уменьшить эти жалобы. Сильные боли в паху, особенно на поздних сроках, которые не проходят после отдыха, могут быть признаком приближающихся родов. Если у вас есть риск преждевременных родов, в подобных случаях может потребоваться обратиться в больницу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Не забывайте пользоваться солнцезащитным кремом (SPF 50). Даже зимой! Это лучший способ предотвратить появление стойких пигментных пятен на лице. Не выходите на солнце без головного убора.') WHERE id = 'f4ba8684-d553-4733-84cb-3f9f1059e979';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Телосложение вашего малыша становится всё более пропорциональным. Руки уже достигли нужной длины и теперь будут расти с той же скоростью, что и тело. А вот ногам понадобится ещё немного времени. В медицине важнейшим показателем для определения роста малыша является бедренная кость — самая длинная и прочная кость тела. Она уже хорошо видна во время обследований и позволяет достаточно точно оценить общий рост малыша. В последние годы для расчёта роста применяется ещё один интересный метод — измерение длины стопы. Особенно после 20-й недели примерный рост малыша можно определить, умножив длину бедренной кости или стопы на 7 (с небольшой погрешностью).'), baby_message_ru = COALESCE(baby_message_ru, 'Я уже умею строить рожицы! 😜 Мышцы моего лица развились настолько, что я могу хмурить брови, щуриться и улыбаться. Иногда я открываю рот и зеваю. Это не просто развлечение — так я готовлюсь к общению. Когда вы меня увидите, я подарю вам свою самую милую улыбку.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Мандарин'), body_changes_ru = COALESCE(body_changes_ru, 'Во время беременности скорость базального обмена веществ в среднем повышается примерно на 20 процентов по сравнению с обычным уровнем. Другими словами, в период беременности ваша потребность в энергии увеличивается примерно на 300 калорий в день. Также происходят заметные изменения в жировом обмене. Особенно во втором триместре усиливается накопление жира, а в третьем триместре, когда потребность малыша в жирах возрастает, часть этой жировой ткани передаётся малышу, поэтому объём запасов уменьшается. Кроме того, к концу беременности общее количество белка в вашем организме увеличивается примерно на 1 кг. Во время беременности в организме накапливается около 6-7 литров воды, а в ногах может скапливаться примерно 1-2 литра отёчной жидкости. Объём циркулирующей крови увеличивается на 40-50 процентов. Этот процесс начинается ещё в уже завершившемся первом триместре. Из-за увеличения объёма крови частота сердечных сокращений возрастает примерно на 10 процентов, а артериальное давление снижается.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить связочные боли, избегайте резких движений, а вставая с кровати, сначала повернитесь на бок. При повышенной чувствительности дёсен продолжайте употреблять продукты, богатые кальцием (сыр, йогурт, кунжут). На следующей неделе малыш начнёт расти ещё быстрее, поэтому пейте достаточно жидкости и придерживайтесь сбалансированного питания.') WHERE id = 'e561aed2-5768-4e9c-b71e-e052866b75f4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На этой неделе во время ультразвукового исследования вы сможете отчётливо увидеть, как активно малыш двигает кистями, руками и ногами. Хотя он постоянно движется в матке, вам понадобится ещё несколько недель, чтобы почувствовать этот "танец". Обычно к 16-17-й неделям беременности движения становятся достаточно сильными, чтобы их можно было ощутить. Однако у всех это происходит по-разному: При первой беременности: Поскольку мышцы живота более крепкие, первые движения можно не ощущать вплоть до 22-й недели. При повторной беременности: Опытные мамы распознают эти ощущения раньше, иногда уже с 16-й недели. Первые движения похожи не на сильные толчки, а скорее на лёгкое "щекотание", "порхание бабочки" или "взмах крыльев птицы". В среднем движения становятся регулярными и ощущаются каждый день начиная с 24-26-й недели.'), baby_message_ru = COALESCE(baby_message_ru, '14 НЕДЕЛЬ! 📏 Я размером с персик! Теперь моё тело растёт быстрее головы, поэтому я всё больше похож на маленького ребёнка. Моя шея удлинилась, а подбородок сформировался. С каждым днём я понемногу расту и становлюсь всё ближе к встрече с вами.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Персик'), body_changes_ru = COALESCE(body_changes_ru, 'Утренняя тошнота и внезапная рвота всё ещё могут продолжаться. Это считается одним из обычных проявлений беременности и чаще всего не требует лечения.;;;
 Почти у половины беременных эти симптомы наблюдаются с разной степенью выраженности. Однако при беременности двойней они могут быть более продолжительными и тяжёлыми. Утренняя тошнота, особенно характерная для первых недель беременности, свидетельствует о том, что гормоны выполняют свою функцию. Тем не менее точные причины тошноты и рвоты неизвестны. Различия в выраженности утренней тошноты могут быть связаны с уровнем гормонов, степенью стресса и усталостью.;;;
Чтобы облегчить это неприятное состояние, можно принять некоторые меры. Придерживайтесь рациона, богатого белками и углеводами, пейте достаточно жидкости, поскольку при рвоте организм её теряет, регулярно принимайте назначенные витамины и избегайте любых запахов, вкусов и продуктов, вид которых может вызвать тошноту.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сейчас отличное время для покупки одежды! Приобретите несколько вещей для беременных, в которых вы будете чувствовать себя комфортно и красиво. Тесная одежда может нарушать кровообращение и способствовать появлению варикозного расширения вен.') WHERE id = 'a6400bac-f975-43dc-a8f8-6c0a5411246c';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Маленькие мышцы на лице вашего малыша уже достаточно развиты, чтобы выполнять различные мимические движения. Эти мышцы расположены вокруг рта, глаз, носа и ушей и в будущем помогут выражать эмоции. Вот некоторые важные мышцы лица малыша: Мышцы вокруг глаз: Помогают открывать и закрывать веки, а также хмурить брови. Мышцы вокруг рта: Позволяют смыкать и вытягивать губы. Эти мышцы также важны для произнесения звуков. Мышцы для "дутья" (щёчные мышцы): Расположены в области щёк и в будущем будут участвовать в пережёвывании пищи и выдувании воздуха. Хотя малыш пока не управляет этой мимикой осознанно (например, ещё не улыбается намеренно), по мере развития мозга именно с помощью этих мышц он будет показывать вам свою радость, злость, голод или усталость.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую вкус! 🍭 Вкусовые рецепторы на моём языке уже работают. Вкус еды, которую вы едите, попадает в околоплодные воды. Если вы съедите что-нибудь сладкое, я проглочу больше жидкости, потому что люблю сладкое! А если вы съедите что-нибудь горькое или кислое, я могу поморщиться. Вы мой первый повар, Anacan!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Персик'), body_changes_ru = COALESCE(body_changes_ru, 'У 30% беременных может наблюдаться расстройство пищевого поведения под названием пика, при котором возникает желание есть несъедобные вещества. Слово «пика» происходит из латинского языка и означает сороку — птицу, которая ест всё, что найдёт. Люди с этим синдромом чаще всего едят лёд, золу, глину, мыло, бумагу, волосы, кирпичную пыль, побелку, листья и грифели карандашей. У малышей беременных, употребляющих такие вещества, могут возникнуть серьёзные проблемы. Точные причины эпизодов пики у женщин неизвестны. Однако, по мнению специалистов, они могут быть связаны с дефицитом железа или с попыткой организма получить другим способом витамины и минералы, которых ему не хватает при обычном питании.;;;
Среди возможных причин также называют психологический дискомфорт, недостаток любви, неуверенность и эмоциональную неудовлетворённость. Если присутствует железодефицитная анемия, её необходимо лечить. Ради здоровья мамы и малыша употребление таких веществ следует прекратить. Также необходимо устранить факторы, вызывающие психологические проблемы.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы предотвратить запор, ешьте продукты, богатые клетчаткой (абрикосы, сливы, овсянку, овощи). Стакан тёплой воды натощак по утрам помогает запустить работу кишечника. Недостаток движения ещё больше замедляет его работу, поэтому выходите на прогулки.') WHERE id = '85f3613e-2010-4d4b-a7cf-efafd3875999';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Кожа вашего малыша быстро развивается, становится толще и продолжает покрываться волосками лануго, которые помогают сохранять тепло тела. Кожа — крупнейший орган тела — начинает формироваться уже на третьей неделе беременности. Рост волосков в самом наружном слое кожи уже ускорился. В этот период они растут быстрее и становятся гуще. Одновременно в коже появляются особые клетки — меланоциты. Они вырабатывают пигмент меланин, определяющий цвет кожи и волос. Меланоциты действуют как естественный "солнцезащитный крем" организма. Они защищают нас от вредного солнечного излучения:;;;
Когда солнца много: Меланоциты перемещаются ближе к поверхности кожи, делая её темнее и препятствуя проникновению вредных лучей вглубь.;;;
Когда солнца мало: Эти клетки перемещаются в более глубокие слои кожи. Благодаря этому кожа светлеет, а организм может эффективнее использовать солнечные лучи (например, для выработки витамина D).'), baby_message_ru = COALESCE(baby_message_ru, '100 ДНЕЙ! 💯 Anacan, трудно поверить, но мы вместе уже 100 дней! Я размером с ладошку. Сейчас я учусь сосать большой палец. Это меня успокаивает. Когда вы волнуетесь или устаёте, я это чувствую и сосу пальчик, чтобы успокоиться. Мы чувствуем друг друга. Я вас очень люблю!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лимон'), body_changes_ru = COALESCE(body_changes_ru, 'На некоторых сроках беременности заложенность носа может причинять значительный дискомфорт. Примерно у трети беременных она возникает при отсутствии аллергии или привычных заболеваний, таких как простуда и грипп. Это состояние называется насморком беременных, или ринитом беременных.;;;
Помимо заложенности носа, могут появиться выделения из носа. Из-за заложенности ночью приходится дышать ртом, что может вызывать сухость в горле. Также одышка и кашель по ночам могут стать причиной бессонницы. Отёк слизистой оболочки и связанное с ним ухудшение вентиляции околоносовых пазух могут привести к головной боли. Повышенный во время беременности уровень эстрогена — одного из гормонов материнства — вызывает отёк тканей внутри носа и усиливает образование выделений. Кроме того, увеличение объёма циркулирующей крови во время беременности приводит к расширению кровеносных сосудов и отёку слизистой оболочки носа.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Отметьте этот особенный день небольшим ритуалом! Может быть, напишете первое письмо своему малышу? Поскольку ваша потребность в кальции возросла, увеличьте количество творога, сыра и йогурта в рационе. Если у вас болит поясница, во время сна положите подушку между ног — это уменьшит нагрузку на позвоночник. Не забывайте пить достаточно воды и гулять на свежем воздухе.') WHERE id = '0cebfe33-ab23-4322-9649-a229de8418e8';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В организме вашего малыша происходит удивительный процесс кроветворения. В первые недели беременности клетки крови образовывались в желточном мешке, затем эту функцию выполняла печень, а с 12-й недели эту важную задачу взял на себя костный мозг. К моменту рождения в организме малыша будет примерно 350 ml крови. Сейчас ваш малыш словно состоит из "воды". Около 94% его тела составляет вода. По мере укрепления костей и роста мышц этот показатель немного снизится: в середине 2-го триместра: 80-85% воды. Ближе к родам: 70% воды (поскольку в этот период быстро увеличивается жировая прослойка). Для сравнения: в организме взрослого человека вода составляет всего 60%.;;;
С момента рождения для поддержания водного баланса гипофиз в головном мозге малыша начнёт вырабатывать гормон вазопрессин (ADH). Этот гормон регулирует обратное всасывание воды в почках, предотвращая обезвоживание и поддерживая баланс жидкости в организме малыша.'), baby_message_ru = COALESCE(baby_message_ru, 'Здравствуйте, Anacan! 👋 Сегодня я занимаюсь настоящей подводной гимнастикой. Вы пока этого не чувствуете, но я кувыркаюсь, поворачиваюсь и вытягиваю ножки. Здесь для меня ещё очень просторно, и я могу двигаться как захочу. Эти движения укрепляют мои мышцы и кости. Вы отдыхайте, а я продолжу тренировку. Однажды вы тоже почувствуете эти толчки!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лимон'), body_changes_ru = COALESCE(body_changes_ru, 'Практически каждая женщина на определённом этапе беременности сталкивается с запором. Одна из его причин — повышение уровня гормона прогестерона, вырабатываемого в том числе плацентой. Он расслабляет гладкую мускулатуру, включая мышцы пищеварительного тракта. Запор также может усиливаться из-за давления растущей матки на кишечник. Расслабление мышц кишечника замедляет продвижение пищи и отходов по пищеварительной системе. Препараты железа, особенно в высоких дозах, могут усугублять запор во время беременности. Кроме того, натуживание при дефекации или прохождение твёрдого стула может вызвать набухание вен прямой кишки и привести к геморрою. Если у вас запор и вы принимаете препараты железа, обязательно пейте достаточно воды. Если, несмотря на это, состояние не улучшается, по рекомендации врача может потребоваться переход на другой препарат железа.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Поскольку слух малыша развивается, включайте ему спокойную музыку или рассказывайте сказки. Чтобы ничего не забывать, записывайте важные дела в блокнот. Не беспокойтесь об изменениях пигментации кожи — после родов они пройдут. Продолжайте пить достаточно жидкости и употреблять продукты, богатые кальцием (миндаль, брокколи, молочные продукты).') WHERE id = '4b92a6ac-df2b-4f98-b986-b23497226910';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'В удлиняющемся и образующем петли кишечнике вашего малыша начинает накапливаться меконий (первородный кал). Меконий — это липкое вещество без запаха, образующееся из смеси проглоченных малышом во время беременности околоплодных вод, выпавших волосков лануго и кишечных выделений. На 90% это вещество состоит из воды и накапливается в кишечнике малыша до рождения. В норме малыш выводит этот кал в течение первых 24 часов после рождения. Поскольку меконий не контактировал с воздухом, он стерилен и не причиняет малышу в утробе никакого вреда. Обычно он имеет тёмно-зелёный или чёрный цвет, но после того, как малыш начинает питаться, постепенно светлеет и становится жёлтым. Иногда, особенно при переношенной беременности, меконий может выделиться ещё в матке. В таких случаях после родов врачи сразу очищают дыхательные пути малыша, чтобы вещество не попало в лёгкие и не вызвало осложнений.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую свет! 💡 Anacan, вы не поверите, но даже с закрытыми веками я могу ощущать яркий свет. Если вы посветите ярким фонариком на живот, я могу повернуть лицо в ту сторону или прикрыть его рукой, потому что свет слепит мне глаза. Мой мир уже не полностью тёмный. Интересно, насколько красочен ваш мир?'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лимон'), body_changes_ru = COALESCE(body_changes_ru, 'После прикрепления малыша к стенке матки молочные протоки и ткани молочных желёз начинают развиваться, готовясь к родам и выработке молока. Начиная с 16-й недели беременности вы можете время от времени замечать желтоватую жидкость, выделяющуюся из груди. Эти выделения не имеют запаха и могут быть жёлтыми или прозрачными. Это молозиво содержит множество антител, необходимых малышу, чья иммунная система ещё не сформирована, и защищает его от различных вирусов и микробов. В молозиве содержится больше белка, чем в зрелом грудном молоке.'), daily_tip_ru = COALESCE(daily_tip_ru, 'По мере роста живота начинайте менять позу для сна. Сон на спине может привести к тому, что матка будет давить на крупные кровеносные сосуды матери. Сон на левом боку — наиболее подходящее положение для кровообращения как у вас, так и у малыша.') WHERE id = '6ada13a0-2697-47e7-9001-03b1698db1b4';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Нервная система вашего малыша уже развилась настолько, что он может более осознанно управлять кистями, руками и ногами. Теперь он не просто двигается: сжимает кулачки, шевелит каждым пальчиком по отдельности, сгибает запястья и делает хватательные движения, словно пытается что-то удержать. Первые движения вашего малыша начались ещё на 7-8-й неделях с движений позвоночника. Тогда он был совсем крошечным, поэтому вы не могли почувствовать эти наклоны вперёд и сгибания в стороны, но теперь они стали более сильными и целенаправленными. До того момента, когда вы ощутите это удивительное чувство, осталось совсем немного! Обычно мамы начинают чувствовать первые движения малыша между 16-й и 20-й неделями. Сначала вы можете ощутить небольшие толчки, возникающие, когда малыш пинается, толкается локтем или выгибает тело назад. Если это ваша первая беременность или у вас есть небольшой лишний вес, вы можете не чувствовать движений вплоть до 24-й недели — это совершенно нормально. В таких случаях можно прибегнуть к небольшой хитрости: сладкое повышает уровень сахара в крови, благодаря чему малыш может стать активнее, а вы — быстрее почувствовать его движения.'), baby_message_ru = COALESCE(baby_message_ru, 'Я учусь дышать! 🌬️ Конечно, здесь нет воздуха, только вода. Но я втягиваю амниотическую жидкость в лёгкие и выталкиваю её обратно. Это помогает моим лёгочным пузырькам раскрываться и готовит их к первому вдоху в будущем. Иногда, когда жидкость попадает мне в горло, я икаю. Возможно, через несколько недель ты почувствуешь эту ритмичную икоту.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Лимон'), body_changes_ru = COALESCE(body_changes_ru, 'Бессонница — это состояние, при котором трудно заснуть или поддерживать сон. Во время беременности эта проблема встречается довольно часто. Бессонница затрагивает почти всех беременных и особенно заметна в последние три месяца, когда живот значительно увеличивается и беременность становится наиболее ощутимой. С самого начала беременности из-за происходящих в организме изменений мозг начинает подавать вам сигналы о том, что нужно больше отдыхать. В течение дня вы чувствуете усталость и сильнее нуждаетесь в отдыхе и сне. Однако некоторые неприятные ощущения, особенно в последние месяцы беременности, могут нарушать режим сна. Среди причин бессонницы во время беременности — изжога, напряжение в ногах, частое мочеиспускание, учащённое сердцебиение, одышка, судороги и боли из-за повышенной нагрузки на ноги, а также кислотный рефлюкс, связанный с замедлением работы пищеварительной системы. Кроме того, сильный стресс и подавленное настроение также могут вызывать бессонницу во время беременности.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Чтобы уменьшить усталость в ногах, в течение дня чаще меняйте положение тела и не стойте подолгу. По вечерам отдыхайте 15 минут, подняв ноги выше уровня сердца. Придерживайтесь здорового рациона с высоким содержанием белка и клетчатки. Если вы носите обувь на каблуке, пора перейти на более низкие и ортопедические модели.') WHERE id = 'ad6452f4-e2be-4e97-a304-4ef7692bd10b';